);

-- ---------------------------------------------------------------------------
-- Shared trigger: keep updated_at honest
-- ---------------------------------------------------------------------------
create or replace function pms.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ####################################################################
-- ## 0002_identity_property.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0002 Identity, company settings, property hierarchy, units
-- ============================================================================

-- ---------------------------------------------------------------------------
-- profiles : one row per auth.users row. Role lives here and drives RLS.
-- ---------------------------------------------------------------------------
create table profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  role          app_role not null default 'tenant',
  full_name     text not null default '',
  email         text,
  phone         text,
  whatsapp      text,
  avatar_path   text,
  locale        text not null default 'en',            -- 'en' | 'ar'
  job_title     text,
  is_active     boolean not null default true,
  last_login_at timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index profiles_role_idx on profiles(role) where is_active;
create trigger profiles_touch before update on profiles
  for each row execute function pms.touch_updated_at();

-- Auto-provision a profile whenever Supabase Auth creates a user.
create or replace function pms.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
begin
  insert into public.profiles (id, email, full_name, phone, role)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    new.raw_user_meta_data->>'phone',
    coalesce((new.raw_user_meta_data->>'role')::app_role, 'tenant')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function pms.handle_new_user();

-- ---------------------------------------------------------------------------
-- company_settings : single-row configuration for the D|R|P entity.
-- Management fee %, VAT rate and notice periods are configurable, never
-- hardcoded in application logic.
-- ---------------------------------------------------------------------------
create table company_settings (
  id                          boolean primary key default true check (id),
  legal_name                  text not null default 'D|R|P Real Estate',
  trade_name                  text not null default 'D|R|P',
  trade_licence_number        text,
  trade_licence_expiry        date,
  rera_broker_number          text,
  trn                         text,                        -- UAE VAT registration number
  registered_address          text,
  emirate                     emirate not null default 'dubai',
  phone                       text,
  email                       text,
  website                     text,

  base_currency               char(3) not null default 'AED',
  vat_rate                    numeric(5,4) not null default 0.0500,   -- 5% UAE VAT
  default_management_fee_pct  numeric(5,2) not null default 8.00,
  default_str_management_fee_pct numeric(5,2) not null default 20.00,

  -- Regulatory notice windows (days). Editable by Super Admin.
  rent_increase_notice_days   integer not null default 90,
  lease_renewal_notice_days   integer not null default 90,
  ejari_occupant_update_days  integer not null default 30,  -- 2026 Ejari currency rule
  permit_renewal_reminder_days integer not null default 60,  -- DET permit
  document_alert_days         integer[] not null default '{60,30,7}',

  -- Owner approval threshold for maintenance spend (AED).
  maintenance_owner_approval_threshold numeric(12,2) not null default 1000.00,

  invoice_prefix              text not null default 'DRP-INV',
  invoice_next_number         integer not null default 1,
  statement_prefix            text not null default 'DRP-STM',
  lease_prefix                text not null default 'DRP-LSE',
  booking_prefix              text not null default 'DRP-BKG',
  ticket_prefix               text not null default 'DRP-MNT',

  brand_primary_hex           text not null default '#0F172A',
  brand_accent_hex            text not null default '#C6A15B',
  logo_path                   text,

  default_locale              text not null default 'en',
  enabled_locales             text[] not null default '{en,ar}',
  display_currencies          char(3)[] not null default '{AED,USD,EUR,GBP}',

  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now()
);
create trigger company_settings_touch before update on company_settings
  for each row execute function pms.touch_updated_at();

insert into company_settings (id) values (true) on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Property hierarchy: community -> property (building/complex) -> unit
-- ---------------------------------------------------------------------------
create table communities (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  name_ar      text,
  emirate      emirate not null default 'dubai',
  city         text not null default 'Dubai',
  dld_community_number text,
  latitude     numeric(10,7),
  longitude    numeric(10,7),
  notes        text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (name, emirate)
);
create trigger communities_touch before update on communities
  for each row execute function pms.touch_updated_at();

create table properties (
  id                     uuid primary key default gen_random_uuid(),
  community_id           uuid references communities(id) on delete set null,
  name                   text not null,
  name_ar                text,
  kind                   property_kind not null default 'building',
  address_line           text,
  makani_number          text,                  -- Dubai Makani geo-address
  plot_number            text,
  developer_name         text,
  year_built             integer,
  floors                 integer,
  total_units            integer,

  -- Owners' association / Mollak (service charges)
  owners_association_name text,
  mollak_property_id      text,
  oa_management_company   text,

  building_noc_required   boolean not null default true,  -- for holiday-home use
  amenities               text[] not null default '{}',
  cover_image_path        text,
  is_active               boolean not null default true,
  notes                   text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);
create index properties_community_idx on properties(community_id);
create trigger properties_touch before update on properties
  for each row execute function pms.touch_updated_at();

create table units (
  id                    uuid primary key default gen_random_uuid(),
  property_id           uuid not null references properties(id) on delete restrict,
  unit_number           text not null,
  reference_code        text unique,                 -- internal D|R|P code
  kind                  unit_kind not null default 'apartment',
  floor                 text,
  bedrooms              numeric(3,1) not null default 1,   -- 0 = studio, 1.5 etc.
  bathrooms             numeric(3,1) not null default 1,
  size_sqft             numeric(10,2),
  size_sqm              numeric(10,2) generated always as (round(size_sqft * 0.09290304, 2)) stored,
  furnishing            furnishing_status not null default 'unfurnished',
  parking_spaces        integer not null default 0,
  parking_numbers       text[],
  balcony               boolean not null default false,
  view_description      text,
  amenities             text[] not null default '{}',

  -- Dubai-specific identifiers
  dewa_premise_number   text,
  dewa_account_number   text,
  title_deed_number     text,
  makani_number         text,
  dld_property_number   text,
  mollak_unit_id        text,

  operating_mode        operating_mode not null default 'long_term',
  status                unit_status not null default 'vacant',

  -- Indicative pricing (actual figures live on leases / bookings)
  target_annual_rent_aed numeric(12,2),
  base_nightly_rate_aed  numeric(10,2),
  min_nights             integer not null default 1,
  max_guests             integer,

  handover_date          date,
  is_active              boolean not null default true,
  notes                  text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (property_id, unit_number)
);
create index units_property_idx on units(property_id);
create index units_status_idx on units(status) where is_active;
create index units_mode_idx on units(operating_mode) where is_active;
create trigger units_touch before update on units
  for each row execute function pms.touch_updated_at();

create table unit_media (
  id          uuid primary key default gen_random_uuid(),
  unit_id     uuid not null references units(id) on delete cascade,
  bucket      text not null default 'media',
  storage_path text not null,
  caption     text,
  sort_order  integer not null default 0,
  is_cover    boolean not null default false,
  uploaded_by uuid references profiles(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index unit_media_unit_idx on unit_media(unit_id, sort_order);
create unique index unit_media_one_cover_idx on unit_media(unit_id) where is_cover;

-- ---------------------------------------------------------------------------
-- Staff scoping: which units/properties a property manager or agent may see.
-- Super admin / finance bypass this; everyone else is scoped.
-- ---------------------------------------------------------------------------
create table staff_property_assignments (
  profile_id  uuid not null references profiles(id) on delete cascade,
  property_id uuid not null references properties(id) on delete cascade,
  assigned_at timestamptz not null default now(),
  primary key (profile_id, property_id)
);

create table staff_unit_assignments (
  profile_id  uuid not null references profiles(id) on delete cascade,
  unit_id     uuid not null references units(id) on delete cascade,
  assigned_at timestamptz not null default now(),
  primary key (profile_id, unit_id)
);

-- ####################################################################
-- ## 0003_owners.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0003 Owners, ownership, management agreements, owner portal link
-- ============================================================================

create table owners (
  id                   uuid primary key default gen_random_uuid(),
  is_company           boolean not null default false,
  full_name            text not null,                 -- individual name or company name
  company_trade_licence text,
  email                text,
  phone                text,
  whatsapp             text,
  nationality          text,
  emirates_id          text,
  emirates_id_expiry   date,
  passport_number      text,
  passport_expiry      date,
  trn                  text,                          -- if VAT-registered
  address_line         text,
  country_of_residence text,
  preferred_locale     text not null default 'en',
  preferred_channel    message_channel not null default 'whatsapp',
  is_active            boolean not null default true,
  notes                text,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index owners_name_idx on owners using gin (to_tsvector('simple', full_name));
create trigger owners_touch before update on owners
  for each row execute function pms.touch_updated_at();

-- Bank details are sensitive: separate table so RLS can lock it down harder
-- than the owner record itself.
create table owner_bank_accounts (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid not null references owners(id) on delete cascade,
  account_holder text not null,
  bank_name      text not null,
  branch         text,
  iban           text not null,
  swift_bic      text,
  currency       char(3) not null default 'AED',
  is_primary     boolean not null default true,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create unique index owner_bank_primary_idx on owner_bank_accounts(owner_id)
  where is_primary and is_active;
create trigger owner_bank_touch before update on owner_bank_accounts
  for each row execute function pms.touch_updated_at();

-- Link an owner record to a portal login. An owner may have several logins
-- (e.g. spouse, family office) and one login may cover several owner records.
create table owner_users (
  owner_id   uuid not null references owners(id) on delete cascade,
  profile_id uuid not null references profiles(id) on delete cascade,
  can_approve_maintenance boolean not null default true,
  created_at timestamptz not null default now(),
  primary key (owner_id, profile_id)
);
create index owner_users_profile_idx on owner_users(profile_id);

-- Fractional ownership supported: percentages per unit must not exceed 100.
create table unit_ownerships (
  id                uuid primary key default gen_random_uuid(),
  unit_id           uuid not null references units(id) on delete cascade,
  owner_id          uuid not null references owners(id) on delete restrict,
  ownership_pct     numeric(5,2) not null default 100.00
                      check (ownership_pct > 0 and ownership_pct <= 100),
  title_deed_number text,
  purchase_date     date,
  purchase_price_aed numeric(14,2),
  is_primary_contact boolean not null default true,
  start_date        date not null default current_date,
  end_date          date,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index unit_ownerships_unit_idx on unit_ownerships(unit_id) where end_date is null;
create index unit_ownerships_owner_idx on unit_ownerships(owner_id) where end_date is null;
create trigger unit_ownerships_touch before update on unit_ownerships
  for each row execute function pms.touch_updated_at();

-- Guard: active ownership shares for a unit must total <= 100%.
create or replace function pms.check_ownership_total()
returns trigger
language plpgsql
as $$
declare
  total numeric(6,2);
begin
  select coalesce(sum(ownership_pct), 0) into total
  from unit_ownerships
  where unit_id = new.unit_id
    and end_date is null
    and id <> new.id;

  if total + new.ownership_pct > 100.00 then
    raise exception 'Ownership for unit % would total %%%, exceeding 100%%',
      new.unit_id, total + new.ownership_pct;
  end if;
  return new;
end;
$$;

create trigger unit_ownerships_total_check
  before insert or update on unit_ownerships
  for each row when (new.end_date is null)
  execute function pms.check_ownership_total();

-- ---------------------------------------------------------------------------
-- Management agreements: the commercial contract between D|R|P and the owner.
-- Drives the management fee applied on owner statements.
-- ---------------------------------------------------------------------------
create table management_agreements (
  id                 uuid primary key default gen_random_uuid(),
  agreement_number   text unique,
  unit_id            uuid not null references units(id) on delete cascade,
  owner_id           uuid not null references owners(id) on delete restrict,
  service_mode       operating_mode not null default 'long_term',
  start_date         date not null,
  end_date           date not null,
  commission_pct     numeric(5,2),                 -- % of collected revenue
  fixed_fee_aed      numeric(12,2),                -- alternative flat fee
  fee_vat_applicable boolean not null default true, -- management fee is a taxable service
  leasing_commission_pct numeric(5,2),             -- one-off, on new tenancy
  auto_renew         boolean not null default true,
  notice_days        integer not null default 60,
  is_active          boolean not null default true,
  terminated_on      date,
  termination_reason text,
  notes              text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (end_date > start_date),
  check (commission_pct is not null or fixed_fee_aed is not null)
);
create index mgmt_agreements_unit_idx on management_agreements(unit_id) where is_active;
create index mgmt_agreements_owner_idx on management_agreements(owner_id) where is_active;
create index mgmt_agreements_expiry_idx on management_agreements(end_date) where is_active;
create trigger mgmt_agreements_touch before update on management_agreements
  for each row execute function pms.touch_updated_at();

-- ####################################################################
-- ## 0004_leasing.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0004 Long-term leasing (Ejari-ready)
--
-- Dubai specifics baked in:
--   * Ejari registration number / expiry tracked on the lease itself
--   * Declared occupants list + 30-day Ejari data-currency rule (2026)
--   * Cheque-based payment schedules (1/2/4/6/12 cheques) with bounce tracking
--   * Rent-increase notices referencing the RERA Smart Rental Index
--   * E-signature fields left provider-agnostic so UAE Pass / Dubai REST
--     can be wired in later without a schema change
-- ============================================================================

create table tenants (
  id                  uuid primary key default gen_random_uuid(),
  is_company          boolean not null default false,
  full_name           text not null,
  company_trade_licence text,
  email               text,
  phone               text,
  whatsapp            text,
  nationality         text,
  date_of_birth       date,
  emirates_id         text,
  emirates_id_expiry  date,
  passport_number     text,
  passport_expiry     date,
  visa_number         text,
  visa_expiry         date,
  employer            text,
  occupation          text,
  trn                 text,
  emergency_contact_name  text,
  emergency_contact_phone text,
  preferred_locale    text not null default 'en',
  preferred_channel   message_channel not null default 'whatsapp',
  profile_id          uuid references profiles(id) on delete set null,  -- portal login
  is_active           boolean not null default true,
  notes               text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index tenants_profile_idx on tenants(profile_id);
create trigger tenants_touch before update on tenants
  for each row execute function pms.touch_updated_at();

create table leases (
  id                    uuid primary key default gen_random_uuid(),
  lease_number          text unique not null,
  unit_id               uuid not null references units(id) on delete restrict,
  tenant_id             uuid not null references tenants(id) on delete restrict,
  status                lease_status not null default 'draft',

  start_date            date not null,
  end_date              date not null,
  annual_rent_aed       numeric(12,2) not null check (annual_rent_aed >= 0),
  contract_value_aed    numeric(12,2),          -- if term <> 12 months
  security_deposit_aed  numeric(12,2) not null default 0,
  deposit_status        deposit_status not null default 'not_collected',

  payment_method        rent_payment_method not null default 'cheque',
  installment_count     integer not null default 1
                          check (installment_count in (1,2,3,4,6,12)),
  ejari_fee_aed         numeric(10,2),
  agency_fee_aed        numeric(10,2),

  -- Ejari (RERA/DLD tenancy registration)
  ejari_status          ejari_status not null default 'not_registered',
  ejari_contract_number text,
  ejari_registered_on   date,
  ejari_expiry          date,
  -- Last time the declared-occupant list was pushed to Ejari. The 30-day
  -- data-currency rule is measured from occupant changes against this date.
  ejari_occupants_synced_at timestamptz,

  -- E-signature: provider-agnostic. UAE Pass / Dubai REST plugs in here.
  signature_provider    text,
  signature_reference   text,
  tenant_signed_at      timestamptz,
  landlord_signed_at    timestamptz,

  renewal_of_lease_id   uuid references leases(id) on delete set null,
  notice_period_days    integer not null default 90,
  agent_id              uuid references profiles(id) on delete set null,
  managed_under_agreement_id uuid references management_agreements(id) on delete set null,

  move_in_date          date,
  move_out_date         date,
  terminated_on         date,
  termination_reason    text,

  notes                 text,
  created_by            uuid references profiles(id) on delete set null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  check (end_date > start_date)
);
create index leases_unit_idx on leases(unit_id);
create index leases_tenant_idx on leases(tenant_id);
create index leases_status_idx on leases(status);
create index leases_expiry_idx on leases(end_date) where status in ('active','expiring');
create index leases_ejari_expiry_idx on leases(ejari_expiry) where ejari_status = 'registered';
create trigger leases_touch before update on leases
  for each row execute function pms.touch_updated_at();

-- A unit may not have two overlapping non-terminal leases.
alter table leases add constraint leases_no_overlap
  exclude using gist (
    unit_id with =,
    daterange(start_date, end_date, '[]') with &&
  ) where (status in ('pending_signature','active','expiring','renewed'));

-- ---------------------------------------------------------------------------
-- Declared occupants (Ejari 2026 data-currency requirement)
-- Any add/remove must be reflected in Ejari within company_settings
-- .ejari_occupant_update_days (default 30) days.
-- ---------------------------------------------------------------------------
create table lease_occupants (
  id             uuid primary key default gen_random_uuid(),
  lease_id       uuid not null references leases(id) on delete cascade,
  full_name      text not null,
  relationship   text,                       -- self, spouse, child, flatmate, staff
  nationality    text,
  date_of_birth  date,
  emirates_id    text,
  passport_number text,
  is_primary     boolean not null default false,
  declared_on    date not null default current_date,
  removed_on     date,
  -- Set when this specific occupant record has been reflected in Ejari.
  ejari_synced_at timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index lease_occupants_lease_idx on lease_occupants(lease_id) where removed_on is null;
create index lease_occupants_unsynced_idx on lease_occupants(lease_id)
  where ejari_synced_at is null and removed_on is null;
create trigger lease_occupants_touch before update on lease_occupants
  for each row execute function pms.touch_updated_at();

-- Changing the occupant list invalidates the lease-level Ejari sync stamp,
-- which is what makes the compliance flag light up.
create or replace function pms.invalidate_ejari_occupant_sync()
returns trigger
language plpgsql
as $$
declare
  target uuid;
begin
  if tg_op = 'DELETE' then
    target := old.lease_id;
  else
    target := new.lease_id;
  end if;

  update leases
     set ejari_occupants_synced_at = null
   where id = target
     and ejari_occupants_synced_at is not null;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create trigger lease_occupants_invalidate_sync
  after insert or update of full_name, emirates_id, passport_number, removed_on
     or delete on lease_occupants
  for each row execute function pms.invalidate_ejari_occupant_sync();

-- ---------------------------------------------------------------------------
-- Rent / cheque schedule
-- ---------------------------------------------------------------------------
create table lease_installments (
  id              uuid primary key default gen_random_uuid(),
  lease_id        uuid not null references leases(id) on delete cascade,
  installment_no  integer not null,
  due_date        date not null,
  amount_aed      numeric(12,2) not null check (amount_aed >= 0),
  method          rent_payment_method not null default 'cheque',
  cheque_number   text,
  cheque_bank     text,
  cheque_date     date,
  status          installment_status not null default 'scheduled',
  amount_paid_aed numeric(12,2) not null default 0,
  presented_on    date,
  cleared_on      date,
  bounced_on      date,
  bounce_reason   text,
  bounce_charge_aed numeric(10,2),
  notes           text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (lease_id, installment_no)
);
create index lease_installments_due_idx on lease_installments(due_date)
  where status in ('scheduled','presented','part_paid');
create index lease_installments_bounced_idx on lease_installments(lease_id) where status = 'bounced';
create trigger lease_installments_touch before update on lease_installments
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Security deposit movements
-- ---------------------------------------------------------------------------
create table deposit_transactions (
  id          uuid primary key default gen_random_uuid(),
  lease_id    uuid not null references leases(id) on delete cascade,
  kind        deposit_txn_kind not null,
  amount_aed  numeric(12,2) not null check (amount_aed > 0),
  occurred_on date not null default current_date,
  reason      text,                        -- required for deductions
  recorded_by uuid references profiles(id) on delete set null,
  created_at  timestamptz not null default now(),
  check (kind <> 'deducted' or reason is not null)
);
create index deposit_txn_lease_idx on deposit_transactions(lease_id);

-- ---------------------------------------------------------------------------
-- Rent increase notices (RERA Smart Rental Index)
-- The permitted increase % from the index is stored alongside the notice so
-- the calculation is auditable years later even if the index changes.
-- ---------------------------------------------------------------------------
create table rent_increase_notices (
  id                     uuid primary key default gen_random_uuid(),
  lease_id               uuid not null references leases(id) on delete cascade,
  current_rent_aed       numeric(12,2) not null,
  proposed_rent_aed      numeric(12,2) not null,
  increase_pct           numeric(6,2) generated always as (
                            case when current_rent_aed > 0
                              then round(((proposed_rent_aed - current_rent_aed) / current_rent_aed) * 100, 2)
                              else 0 end
                         ) stored,
  -- Snapshot of the RERA Smart Rental Index / Rental Calculator result
  rera_index_rent_aed    numeric(12,2),
  rera_permitted_pct     numeric(6,2),
  rera_index_checked_on  date,
  rera_reference         text,

  notice_date            date not null default current_date,
  effective_date         date not null,
  required_notice_days   integer not null default 90,
  delivered_via          message_channel,
  status                 notice_status not null default 'draft',
  issued_by              uuid references profiles(id) on delete set null,
  notes                  text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  -- Legally required notice period must be respected before it can take effect
  check (effective_date >= notice_date + required_notice_days)
);
create index rent_increase_lease_idx on rent_increase_notices(lease_id);
create trigger rent_increase_touch before update on rent_increase_notices
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- General lease notices: renewal, non-renewal, termination, eviction
-- ---------------------------------------------------------------------------
create table lease_notices (
  id                   uuid primary key default gen_random_uuid(),
  lease_id             uuid not null references leases(id) on delete cascade,
  kind                 notice_kind not null,
  status               notice_status not null default 'draft',
  issued_on            date not null default current_date,
  effective_on         date not null,
  required_notice_days integer not null default 90,
  grounds              text,                  -- eviction grounds (Law 26/2007 art.25 etc.)
  delivered_via        message_channel,
  delivered_on         date,
  acknowledged_on      date,
  issued_by            uuid references profiles(id) on delete set null,
  body                 text,                  -- generated document body
  notes                text,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index lease_notices_lease_idx on lease_notices(lease_id);
create trigger lease_notices_touch before update on lease_notices
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- UAEDDS (UAE Direct Debit System) integration point.
-- Not implemented now - the mandate record exists so switching a lease from
-- cheques to direct debit later needs no migration.
-- ---------------------------------------------------------------------------
create table direct_debit_mandates (
  id                 uuid primary key default gen_random_uuid(),
  lease_id           uuid not null references leases(id) on delete cascade,
  provider           text not null default 'uaedds',
  mandate_reference  text,
  payer_iban         text,
  payer_bank         text,
  amount_aed         numeric(12,2),
  frequency_months   integer not null default 1,
