  end_date           date,
  status             text not null default 'draft',
  registered_on      date,
  last_collection_on date,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index dd_mandates_lease_idx on direct_debit_mandates(lease_id);
create trigger dd_mandates_touch before update on direct_debit_mandates
  for each row execute function pms.touch_updated_at();

-- ####################################################################
-- ## 0005_short_term.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0005 Holiday Homes / short-term rental (DET-ready)
--
-- Dubai specifics:
--   * DET (formerly DTCM) holiday home permit per unit, with building NOC
--   * A unit cannot go live on any channel without a valid, unexpired permit
--   * Permit number must appear on every OTA listing (DET requirement)
--   * Guest registration records retained per booking
--   * Tourism Dirham fee tracked per booking
-- ============================================================================

create table holiday_home_permits (
  id                 uuid primary key default gen_random_uuid(),
  unit_id            uuid not null references units(id) on delete cascade,
  permit_number      text not null,
  operator_name      text,                       -- licensed operator on the permit
  operator_licence_number text,
  det_classification text,                       -- e.g. 'Deluxe' / 'Standard'
  issued_on          date not null,
  expires_on         date not null,
  status             permit_status not null default 'active',
  -- Building/developer NOC permitting short-term use
  noc_reference      text,
  noc_expires_on     date,
  renewal_reminder_days integer not null default 60,
  renewal_submitted_on  date,
  notes              text,
  created_by         uuid references profiles(id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (expires_on > issued_on)
);
create unique index hh_permits_number_idx on holiday_home_permits(permit_number)
  where status in ('active','pending');
create index hh_permits_unit_idx on holiday_home_permits(unit_id);
create index hh_permits_expiry_idx on holiday_home_permits(expires_on) where status = 'active';
create trigger hh_permits_touch before update on holiday_home_permits
  for each row execute function pms.touch_updated_at();

-- Does this unit currently hold a valid DET permit?
create or replace function pms.unit_has_valid_permit(p_unit_id uuid, p_on date default current_date)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from holiday_home_permits
    where unit_id = p_unit_id
      and status = 'active'
      and issued_on <= p_on
      and expires_on >= p_on
  );
$$;

-- The permit number to print on OTA listings (DET requires it on every listing).
create or replace function pms.unit_permit_number(p_unit_id uuid)
returns text
language sql
stable
as $$
  select permit_number
  from holiday_home_permits
  where unit_id = p_unit_id and status = 'active' and expires_on >= current_date
  order by expires_on desc
  limit 1;
$$;

-- ---------------------------------------------------------------------------
-- Channel listings. Provider-agnostic: the sync fields exist now, the actual
-- OTA API calls land in Phase 3 behind lib/channels/*.
-- ---------------------------------------------------------------------------
create table channel_listings (
  id                  uuid primary key default gen_random_uuid(),
  unit_id             uuid not null references units(id) on delete cascade,
  channel             sales_channel not null,
  external_listing_id text,
  listing_url         text,
  is_active           boolean not null default false,
  headline            text,
  description         text,
  -- Denormalised so listing content can be generated/validated without a join.
  displayed_permit_number text,
  base_rate_aed       numeric(10,2),
  min_nights          integer not null default 1,
  cleaning_fee_aed    numeric(10,2),
  channel_commission_pct numeric(5,2),
  last_synced_at      timestamptz,
  sync_status         text,
  sync_error          text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (unit_id, channel)
);
create index channel_listings_unit_idx on channel_listings(unit_id);
create trigger channel_listings_touch before update on channel_listings
  for each row execute function pms.touch_updated_at();

-- Hard gate: no unit goes live on a channel without a valid DET permit, and
-- the permit number is stamped onto the listing automatically.
create or replace function pms.enforce_permit_before_listing()
returns trigger
language plpgsql
as $$
begin
  if new.is_active then
    if not pms.unit_has_valid_permit(new.unit_id) then
      raise exception
        'Unit % cannot be listed for short-term rental: no valid DET holiday home permit on file',
        new.unit_id
        using errcode = 'check_violation';
    end if;
    new.displayed_permit_number := pms.unit_permit_number(new.unit_id);
  end if;
  return new;
end;
$$;

create trigger channel_listings_permit_gate
  before insert or update of is_active, unit_id on channel_listings
  for each row execute function pms.enforce_permit_before_listing();

-- Dynamic pricing integration point (PriceLabs-style). We store the connection
-- and the guard rails; the pricing engine itself is external.
create table pricing_connections (
  id              uuid primary key default gen_random_uuid(),
  unit_id         uuid not null references units(id) on delete cascade,
  provider        text not null,               -- 'pricelabs' | 'wheelhouse' | 'manual'
  external_ref    text,
  is_active       boolean not null default false,
  min_rate_aed    numeric(10,2),
  max_rate_aed    numeric(10,2),
  base_rate_aed   numeric(10,2),
  last_pulled_at  timestamptz,
  last_pushed_at  timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (unit_id, provider)
);
create trigger pricing_connections_touch before update on pricing_connections
  for each row execute function pms.touch_updated_at();

-- Nightly rate overrides (manual or pushed from the pricing provider).
create table nightly_rates (
  unit_id     uuid not null references units(id) on delete cascade,
  stay_date   date not null,
  rate_aed    numeric(10,2) not null,
  min_nights  integer,
  is_available boolean not null default true,
  source      text not null default 'manual',
  updated_at  timestamptz not null default now(),
  primary key (unit_id, stay_date)
);

-- ---------------------------------------------------------------------------
-- Guests
-- ---------------------------------------------------------------------------
create table guests (
  id               uuid primary key default gen_random_uuid(),
  full_name        text not null,
  email            text,
  phone            text,
  whatsapp         text,
  nationality      text,
  date_of_birth    date,
  passport_number  text,
  passport_expiry  date,
  emirates_id      text,
  address_line     text,
  preferred_locale text not null default 'en',
  profile_id       uuid references profiles(id) on delete set null,
  notes            text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index guests_profile_idx on guests(profile_id);
create trigger guests_touch before update on guests
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Bookings
-- Internal accounting is always AED. quoted_currency / fx_rate only record
-- what the guest was shown.
-- ---------------------------------------------------------------------------
create table bookings (
  id                    uuid primary key default gen_random_uuid(),
  booking_number        text unique not null,
  unit_id               uuid not null references units(id) on delete restrict,
  guest_id              uuid references guests(id) on delete set null,
  channel               sales_channel not null default 'direct',
  external_booking_id   text,
  status                booking_status not null default 'inquiry',

  check_in              date not null,
  check_out             date not null,
  nights                integer generated always as (check_out - check_in) stored,
  check_in_time         time,
  check_out_time        time,
  adults                integer not null default 1,
  children              integer not null default 0,
  infants               integer not null default 0,

  -- Money (AED base)
  nightly_rate_aed      numeric(10,2),
  accommodation_aed     numeric(12,2) not null default 0,
  cleaning_fee_aed      numeric(10,2) not null default 0,
  extra_fees_aed        numeric(10,2) not null default 0,
  tourism_dirham_aed    numeric(10,2) not null default 0,
  channel_commission_aed numeric(10,2) not null default 0,
  gross_total_aed       numeric(12,2) not null default 0,
  payout_expected_aed   numeric(12,2),

  damage_deposit_aed    numeric(10,2) not null default 0,
  damage_deposit_status deposit_status not null default 'not_collected',

  quoted_currency       char(3) not null default 'AED',
  fx_rate_to_aed        numeric(12,6) not null default 1,

  -- Permit in force at the time of booking, captured for the audit trail.
  permit_number_at_booking text,

  guest_message         text,
  internal_notes        text,
  cancelled_on          date,
  cancellation_reason   text,
  created_by            uuid references profiles(id) on delete set null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  check (check_out > check_in),
  check (adults + children > 0)
);
create index bookings_unit_idx on bookings(unit_id);
create index bookings_dates_idx on bookings(check_in, check_out);
create index bookings_status_idx on bookings(status);
create index bookings_guest_idx on bookings(guest_id);
create trigger bookings_touch before update on bookings
  for each row execute function pms.touch_updated_at();

-- No double-booking a unit for confirmed/in-house stays. Half-open range:
-- one guest checking out on the same day another checks in is allowed.
alter table bookings add constraint bookings_no_overlap
  exclude using gist (
    unit_id with =,
    daterange(check_in, check_out, '[)') with &&
  ) where (status in ('tentative','confirmed','checked_in'));

-- Confirming a booking requires a live DET permit and snapshots it.
create or replace function pms.enforce_permit_before_booking()
returns trigger
language plpgsql
as $$
begin
  if new.status in ('tentative','confirmed','checked_in') then
    if not pms.unit_has_valid_permit(new.unit_id, new.check_in) then
      raise exception
        'Booking for unit % rejected: no valid DET holiday home permit covering check-in date %',
        new.unit_id, new.check_in
        using errcode = 'check_violation';
    end if;
    if new.permit_number_at_booking is null then
      new.permit_number_at_booking := pms.unit_permit_number(new.unit_id);
    end if;
  end if;
  return new;
end;
$$;

create trigger bookings_permit_gate
  before insert or update of status, unit_id, check_in on bookings
  for each row execute function pms.enforce_permit_before_booking();

-- Guest registration records. Dubai holiday home operators must keep records
-- of every guest staying in the unit, not just the booker.
create table booking_guests (
  id              uuid primary key default gen_random_uuid(),
  booking_id      uuid not null references bookings(id) on delete cascade,
  guest_id        uuid references guests(id) on delete set null,
  full_name       text not null,
  nationality     text,
  date_of_birth   date,
  passport_number text,
  emirates_id     text,
  is_lead_guest   boolean not null default false,
  id_document_id  uuid,                        -- FK added in 0008 (documents)
  registered_at   timestamptz,
  registered_by   uuid references profiles(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index booking_guests_booking_idx on booking_guests(booking_id);

-- ---------------------------------------------------------------------------
-- Calendar blocks: bookings, maintenance, owner stays, channel-sync holds
-- ---------------------------------------------------------------------------
create table availability_blocks (
  id          uuid primary key default gen_random_uuid(),
  unit_id     uuid not null references units(id) on delete cascade,
  start_date  date not null,
  end_date    date not null,
  reason      block_reason not null default 'blocked',
  booking_id  uuid references bookings(id) on delete cascade,
  source_channel sales_channel,
  note        text,
  created_by  uuid references profiles(id) on delete set null,
  created_at  timestamptz not null default now(),
  check (end_date > start_date)
);
create index availability_blocks_unit_idx on availability_blocks(unit_id, start_date, end_date);

-- ---------------------------------------------------------------------------
-- Housekeeping / turnover, scheduled into the checkout -> next check-in gap
-- ---------------------------------------------------------------------------
create table housekeeping_tasks (
  id             uuid primary key default gen_random_uuid(),
  unit_id        uuid not null references units(id) on delete cascade,
  booking_id     uuid references bookings(id) on delete set null,
  next_booking_id uuid references bookings(id) on delete set null,
  kind           housekeeping_kind not null default 'turnover',
  status         task_status not null default 'pending',
  scheduled_start timestamptz not null,
  scheduled_end  timestamptz,
  assigned_to    uuid references profiles(id) on delete set null,
  checklist      jsonb not null default '[]'::jsonb,
  started_at     timestamptz,
  completed_at   timestamptz,
  verified_by    uuid references profiles(id) on delete set null,
  supplies_used  jsonb,
  cost_aed       numeric(10,2),
  notes          text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index housekeeping_unit_idx on housekeeping_tasks(unit_id, scheduled_start);
create index housekeeping_assignee_idx on housekeeping_tasks(assigned_to)
  where status in ('pending','assigned','in_progress');
create trigger housekeeping_touch before update on housekeeping_tasks
  for each row execute function pms.touch_updated_at();

-- ####################################################################
-- ## 0006_finance.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0006 Finance
--
-- Rules encoded here:
--   * AED is the base currency for every stored amount. Foreign currency is a
--     display concern (quoted_currency + fx_rate on the source record).
--   * VAT applicability is PER LINE ITEM, not per document. Long-term
--     residential rent is normally exempt; management fees, commission and
--     furnishing services are normally standard-rated. The accountant
--     configures the default per GL category and can override per line.
--   * Owner payout = collected income - management fee - owner expenses - VAT
--     where applicable. Every component traces back to a ledger entry.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Chart of accounts (simplified, configurable by Finance)
-- ---------------------------------------------------------------------------
create table gl_categories (
  id                     uuid primary key default gen_random_uuid(),
  code                   text unique not null,
  name                   text not null,
  name_ar                text,
  direction              ledger_direction not null,
  -- Default VAT treatment. Overridable on each line item.
  default_vat_applicable boolean not null default true,
  -- Does this hit the owner statement (recharged to / paid by the owner)?
  affects_owner_statement boolean not null default true,
  is_active              boolean not null default true,
  sort_order             integer not null default 100,
  created_at             timestamptz not null default now()
);

insert into gl_categories (code, name, direction, default_vat_applicable, affects_owner_statement, sort_order) values
  ('INC-RENT',       'Long-term rent',            'income',  false, true,  10),
  ('INC-BOOKING',    'Short-term booking revenue','income',  true,  true,  20),
  ('INC-CLEANING',   'Cleaning fee income',       'income',  true,  true,  30),
  ('INC-OTHER',      'Other income',              'income',  true,  true,  90),
  ('EXP-MGMT-FEE',   'Management fee',            'expense', true,  true,  100),
  ('EXP-COMMISSION', 'Leasing commission',        'expense', true,  true,  110),
  ('EXP-MAINT',      'Maintenance & repairs',     'expense', true,  true,  120),
  ('EXP-HOUSEKEEP',  'Housekeeping & laundry',    'expense', true,  true,  130),
  ('EXP-DEWA',       'DEWA utilities',            'expense', false, true,  140),
  ('EXP-CHILLER',    'Chiller / district cooling','expense', true,  true,  145),
  ('EXP-SERVICE-CHG','OA service charges (Mollak)','expense',true,  true,  150),
  ('EXP-INSURANCE',  'Insurance',                 'expense', true,  true,  160),
  ('EXP-EJARI',      'Ejari & government fees',   'expense', false, true,  170),
  ('EXP-PERMIT',     'DET permit & NOC fees',     'expense', false, true,  175),
  ('EXP-TOURISM-DH', 'Tourism Dirham fee',        'expense', false, true,  180),
  ('EXP-CHANNEL',    'OTA channel commission',    'expense', false, true,  185),
  ('EXP-FURNISH',    'Furnishing & interior design','expense',true, true,  190),
  ('EXP-OTHER',      'Other expenses',            'expense', true,  true,  900)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------------
-- Ledger: the single source of truth behind owner statements and P&L.
-- Every income/expense event in the system writes exactly one entry here.
-- ---------------------------------------------------------------------------
create table ledger_entries (
  id               uuid primary key default gen_random_uuid(),
  entry_date       date not null default current_date,
  unit_id          uuid references units(id) on delete set null,
  owner_id         uuid references owners(id) on delete set null,
  category_id      uuid not null references gl_categories(id) on delete restrict,
  direction        ledger_direction not null,
  description      text not null,

  -- Amounts are always AED and always VAT-exclusive in `amount_aed`.
  amount_aed       numeric(14,2) not null check (amount_aed >= 0),
  vat_applicable   boolean not null default false,
  vat_rate         numeric(5,4) not null default 0,
  vat_amount_aed   numeric(14,2) not null default 0,
  total_aed        numeric(14,2) generated always as (amount_aed + vat_amount_aed) stored,

  -- Provenance: what created this entry
  source_table     text,
  source_id        uuid,
  lease_id         uuid references leases(id) on delete set null,
  booking_id       uuid references bookings(id) on delete set null,
  invoice_id       uuid,                      -- FK added after invoices exists
  statement_id     uuid,                      -- set once included in a statement

  is_owner_visible boolean not null default true,
  recorded_by      uuid references profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (vat_applicable or vat_amount_aed = 0)
);
create index ledger_unit_date_idx on ledger_entries(unit_id, entry_date);
create index ledger_owner_date_idx on ledger_entries(owner_id, entry_date);
create index ledger_statement_idx on ledger_entries(statement_id);
create index ledger_source_idx on ledger_entries(source_table, source_id);
create trigger ledger_touch before update on ledger_entries
  for each row execute function pms.touch_updated_at();

-- Compute VAT from the rate when the caller does not supply the amount.
create or replace function pms.apply_vat()
returns trigger
language plpgsql
as $$
begin
  if not new.vat_applicable then
    new.vat_rate := 0;
    new.vat_amount_aed := 0;
  else
    if new.vat_rate is null or new.vat_rate = 0 then
      select vat_rate into new.vat_rate from company_settings where id;
    end if;
    if new.vat_amount_aed is null or new.vat_amount_aed = 0 then
      new.vat_amount_aed := round(new.amount_aed * new.vat_rate, 2);
    end if;
  end if;
  return new;
end;
$$;

create trigger ledger_apply_vat before insert or update on ledger_entries
  for each row execute function pms.apply_vat();

-- ---------------------------------------------------------------------------
-- Invoices (tax-compliant sequential numbering)
-- ---------------------------------------------------------------------------
create table invoices (
  id             uuid primary key default gen_random_uuid(),
  invoice_number text unique not null,
  kind           invoice_kind not null,
  direction      invoice_direction not null default 'receivable',
  status         invoice_status not null default 'draft',

  party_kind     party_kind not null,
  party_id       uuid not null,               -- polymorphic: owner/tenant/guest/vendor
  party_name     text not null,               -- snapshot for the printed document
  party_trn      text,

  unit_id        uuid references units(id) on delete set null,
  lease_id       uuid references leases(id) on delete set null,
  booking_id     uuid references bookings(id) on delete set null,

  issue_date     date not null default current_date,
  due_date       date,
  currency       char(3) not null default 'AED',

  subtotal_aed   numeric(14,2) not null default 0,
  vat_total_aed  numeric(14,2) not null default 0,
  total_aed      numeric(14,2) not null default 0,
  paid_aed       numeric(14,2) not null default 0,
  balance_aed    numeric(14,2) generated always as (total_aed - paid_aed) stored,

  place_of_supply text not null default 'Dubai, UAE',
  notes          text,
  terms          text,
  pdf_path       text,
  voided_reason  text,
  created_by     uuid references profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index invoices_party_idx on invoices(party_kind, party_id);
create index invoices_unit_idx on invoices(unit_id);
create index invoices_status_idx on invoices(status) where status in ('issued','part_paid','overdue');
create trigger invoices_touch before update on invoices
  for each row execute function pms.touch_updated_at();

create table invoice_lines (
  id               uuid primary key default gen_random_uuid(),
  invoice_id       uuid not null references invoices(id) on delete cascade,
  line_no          integer not null default 1,
  description      text not null,
  category_id      uuid references gl_categories(id) on delete set null,
  quantity         numeric(10,2) not null default 1,
  unit_price_aed   numeric(14,2) not null default 0,
  discount_aed     numeric(14,2) not null default 0,
  -- Per-line VAT flag: this is what makes exempt residential rent and
  -- standard-rated management fees coexist on one document.
  vat_applicable   boolean not null default true,
  vat_rate         numeric(5,4) not null default 0.05,
  line_subtotal_aed numeric(14,2) generated always as
                     (round(quantity * unit_price_aed - discount_aed, 2)) stored,
  line_vat_aed     numeric(14,2) not null default 0,
  line_total_aed   numeric(14,2) not null default 0,
  created_at       timestamptz not null default now(),
  unique (invoice_id, line_no)
);
create index invoice_lines_invoice_idx on invoice_lines(invoice_id);

create or replace function pms.compute_invoice_line()
returns trigger
language plpgsql
as $$
declare
  sub numeric(14,2);
begin
  sub := round(new.quantity * new.unit_price_aed - new.discount_aed, 2);
  if new.vat_applicable then
    if new.vat_rate is null then
      select vat_rate into new.vat_rate from company_settings where id;
    end if;
    new.line_vat_aed := round(sub * new.vat_rate, 2);
  else
    new.vat_rate := 0;
    new.line_vat_aed := 0;
  end if;
  new.line_total_aed := sub + new.line_vat_aed;
  return new;
end;
$$;

create trigger invoice_lines_compute before insert or update on invoice_lines
  for each row execute function pms.compute_invoice_line();

create or replace function pms.recalc_invoice_totals()
returns trigger
language plpgsql
as $$
declare
  target uuid;
begin
  target := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;

  update invoices i
     set subtotal_aed  = coalesce(t.sub, 0),
         vat_total_aed = coalesce(t.vat, 0),
         total_aed     = coalesce(t.sub, 0) + coalesce(t.vat, 0)
    from (
      select sum(line_subtotal_aed) as sub, sum(line_vat_aed) as vat
      from invoice_lines where invoice_id = target
    ) t
   where i.id = target;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create trigger invoice_lines_rollup
  after insert or update or delete on invoice_lines
  for each row execute function pms.recalc_invoice_totals();

alter table ledger_entries
  add constraint ledger_invoice_fk
  foreign key (invoice_id) references invoices(id) on delete set null;

-- Sequential, gap-free invoice numbering (UAE tax requirement).
create or replace function pms.next_invoice_number()
returns text
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  prefix text;
  n      integer;
begin
  update company_settings
     set invoice_next_number = invoice_next_number + 1
   where id
  returning invoice_prefix, invoice_next_number - 1 into prefix, n;

  return prefix || '-' || to_char(now(), 'YYYY') || '-' || lpad(n::text, 5, '0');
end;
$$;

-- ---------------------------------------------------------------------------
-- Payments + reconciliation
-- ---------------------------------------------------------------------------
create table payments (
  id                uuid primary key default gen_random_uuid(),
  payment_reference text unique not null,
  direction         payment_direction not null,
  status            payment_status not null default 'pending',
  method            rent_payment_method not null default 'bank_transfer',

  party_kind        party_kind not null,
  party_id          uuid,
  party_name        text,

  amount_aed        numeric(14,2) not null check (amount_aed > 0),
  currency          char(3) not null default 'AED',
  fx_rate_to_aed    numeric(12,6) not null default 1,

  paid_on           date not null default current_date,
  -- Provider is abstracted: never branch on this in business logic.
  provider          text,
  provider_reference text,
  bank_reference    text,
  reconciled_at     timestamptz,
  reconciled_by     uuid references profiles(id) on delete set null,

  unit_id           uuid references units(id) on delete set null,
  lease_id          uuid references leases(id) on delete set null,
  booking_id        uuid references bookings(id) on delete set null,
  installment_id    uuid references lease_installments(id) on delete set null,

  notes             text,
  recorded_by       uuid references profiles(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index payments_party_idx on payments(party_kind, party_id);
create index payments_unreconciled_idx on payments(paid_on) where reconciled_at is null;
create trigger payments_touch before update on payments
  for each row execute function pms.touch_updated_at();

create table payment_allocations (
  id           uuid primary key default gen_random_uuid(),
  payment_id   uuid not null references payments(id) on delete cascade,
  invoice_id   uuid not null references invoices(id) on delete cascade,
  amount_aed   numeric(14,2) not null check (amount_aed > 0),
  created_at   timestamptz not null default now(),
  unique (payment_id, invoice_id)
);

create or replace function pms.recalc_invoice_paid()
returns trigger
language plpgsql
as $$
declare
  target uuid;
  paid   numeric(14,2);
  tot    numeric(14,2);
begin
  target := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;

  select coalesce(sum(amount_aed), 0) into paid
  from payment_allocations where invoice_id = target;

  select total_aed into tot from invoices where id = target;

  update invoices
     set paid_aed = paid,
         status = case
           when status = 'void' then 'void'
           when paid >= tot and tot > 0 then 'paid'
           when paid > 0 then 'part_paid'
           when due_date is not null and due_date < current_date then 'overdue'
           else status
         end
   where id = target;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create trigger payment_allocations_rollup
  after insert or update or delete on payment_allocations
  for each row execute function pms.recalc_invoice_paid();

-- ---------------------------------------------------------------------------
-- Mollak / owners' association service charges, tracked against the unit
-- ---------------------------------------------------------------------------
create table service_charge_invoices (
  id                 uuid primary key default gen_random_uuid(),
  unit_id            uuid not null references units(id) on delete cascade,
  mollak_invoice_number text,
  oa_name            text,
  management_company text,
  period_start       date not null,
  period_end         date not null,
  amount_aed         numeric(14,2) not null,
  vat_aed            numeric(14,2) not null default 0,
  total_aed          numeric(14,2) generated always as (amount_aed + vat_aed) stored,
  rate_per_sqft_aed  numeric(10,4),
  due_date           date,
  paid_on            date,
  status             invoice_status not null default 'issued',
  ledger_entry_id    uuid references ledger_entries(id) on delete set null,
  notes              text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (period_end > period_start)
);
create index service_charges_unit_idx on service_charge_invoices(unit_id, period_start);
create trigger service_charges_touch before update on service_charge_invoices
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Owner statements
-- Lines are snapshotted from the ledger so a re-issued statement can never
-- silently change history.
-- ---------------------------------------------------------------------------
create table owner_statements (
  id                 uuid primary key default gen_random_uuid(),
  statement_number   text unique not null,
  owner_id           uuid not null references owners(id) on delete restrict,
  period_start       date not null,
  period_end         date not null,
  status             statement_status not null default 'draft',

  gross_income_aed   numeric(14,2) not null default 0,
  total_expenses_aed numeric(14,2) not null default 0,
  management_fee_aed numeric(14,2) not null default 0,
  vat_total_aed      numeric(14,2) not null default 0,
  net_payout_aed     numeric(14,2) not null default 0,
  opening_balance_aed numeric(14,2) not null default 0,
  closing_balance_aed numeric(14,2) not null default 0,

  issued_on          date,
  approved_by        uuid references profiles(id) on delete set null,
  approved_at        timestamptz,
  paid_on            date,
  payment_id         uuid references payments(id) on delete set null,
  pdf_path           text,
  notes              text,
  created_by         uuid references profiles(id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (period_end >= period_start),
  unique (owner_id, period_start, period_end)
);
create index owner_statements_owner_idx on owner_statements(owner_id, period_start desc);
create trigger owner_statements_touch before update on owner_statements
  for each row execute function pms.touch_updated_at();

create table owner_statement_lines (
  id              uuid primary key default gen_random_uuid(),
  statement_id    uuid not null references owner_statements(id) on delete cascade,
  ledger_entry_id uuid references ledger_entries(id) on delete set null,
  unit_id         uuid references units(id) on delete set null,
  unit_label      text,                        -- snapshot
  entry_date      date not null,
  category_code   text,
  description     text not null,
  direction       ledger_direction not null,
  amount_aed      numeric(14,2) not null,
  vat_amount_aed  numeric(14,2) not null default 0,
  total_aed       numeric(14,2) not null,
  sort_order      integer not null default 0
);
create index owner_statement_lines_stmt_idx on owner_statement_lines(statement_id, sort_order);

alter table ledger_entries
  add constraint ledger_statement_fk
  foreign key (statement_id) references owner_statements(id) on delete set null;

-- ####################################################################
-- ## 0007_maintenance_documents.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0007 Maintenance, vendors, documents, compliance, audit trail
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Vendors / contractors
-- ---------------------------------------------------------------------------
create table vendors (
  id                uuid primary key default gen_random_uuid(),
  name              text not null,
  categories        maintenance_category[] not null default '{}',
  contact_name      text,
  phone             text,
  whatsapp          text,
  email             text,
  trade_licence_number text,
  trade_licence_expiry date,
  trn               text,
  address_line      text,
  hourly_rate_aed   numeric(10,2),
  callout_fee_aed   numeric(10,2),
  payment_terms_days integer not null default 30,
  rating            numeric(2,1) check (rating is null or (rating >= 0 and rating <= 5)),
  is_approved       boolean not null default false,
  is_active         boolean not null default true,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create trigger vendors_touch before update on vendors
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Maintenance requests
-- Owner approval is required once the quote exceeds the configured threshold.
-- ---------------------------------------------------------------------------
create table maintenance_requests (
  id                uuid primary key default gen_random_uuid(),
  ticket_number     text unique not null,
  unit_id           uuid not null references units(id) on delete cascade,
  lease_id          uuid references leases(id) on delete set null,
  booking_id        uuid references bookings(id) on delete set null,

  category          maintenance_category not null default 'other',
  priority          maintenance_priority not null default 'medium',
  status            maintenance_status not null default 'submitted',
  title             text not null,
  description       text,
  access_notes      text,               -- keys, guest in residence, pets etc.

  raised_by         uuid references profiles(id) on delete set null,
  raised_by_kind    party_kind not null default 'staff',
  reported_at       timestamptz not null default now(),
  acknowledged_at   timestamptz,

  assigned_to       uuid references profiles(id) on delete set null,
  vendor_id         uuid references vendors(id) on delete set null,
  scheduled_for     timestamptz,

  quoted_amount_aed   numeric(12,2),
  approved_amount_aed numeric(12,2),
  final_amount_aed    numeric(12,2),
  cost_borne_by       cost_bearer not null default 'owner',

  owner_approval_required boolean not null default false,
  owner_approved_by   uuid references profiles(id) on delete set null,
  owner_approved_at   timestamptz,
  owner_rejected_at   timestamptz,
  owner_rejection_reason text,

  started_at        timestamptz,
  completed_at      timestamptz,
  closed_at         timestamptz,
  resolution_notes  text,
  tenant_rating     integer check (tenant_rating is null or tenant_rating between 1 and 5),
  ledger_entry_id   uuid references ledger_entries(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index maintenance_unit_idx on maintenance_requests(unit_id);
create index maintenance_status_idx on maintenance_requests(status)
  where status not in ('closed','cancelled','rejected');
create index maintenance_assignee_idx on maintenance_requests(assigned_to)
  where status not in ('closed','cancelled','rejected');
create index maintenance_vendor_idx on maintenance_requests(vendor_id);
create trigger maintenance_touch before update on maintenance_requests
  for each row execute function pms.touch_updated_at();

-- Flip the owner-approval flag as soon as a quote crosses the threshold.
create or replace function pms.flag_owner_approval()
returns trigger
language plpgsql
as $$
declare
  threshold numeric(12,2);
begin
  select maintenance_owner_approval_threshold into threshold from company_settings where id;

  if coalesce(new.quoted_amount_aed, 0) > threshold and new.cost_borne_by = 'owner' then
    new.owner_approval_required := true;
  end if;

  -- Work may not start on an owner-billed job above the threshold until the
  -- owner has actually approved it.
  if new.owner_approval_required
     and new.owner_approved_at is null
     and new.status in ('approved','scheduled','in_progress','completed') then
    raise exception
      'Ticket % requires owner approval before work proceeds (quote AED %, threshold AED %)',
      new.ticket_number, new.quoted_amount_aed, threshold
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

create trigger maintenance_owner_approval_gate
  before insert or update on maintenance_requests
  for each row execute function pms.flag_owner_approval();

create table maintenance_updates (
  id          uuid primary key default gen_random_uuid(),
  request_id  uuid not null references maintenance_requests(id) on delete cascade,
  author_id   uuid references profiles(id) on delete set null,
  note        text,
  status_from maintenance_status,
  status_to   maintenance_status,
  is_internal boolean not null default false,   -- hidden from tenant/owner portals
  created_at  timestamptz not null default now()
);
create index maintenance_updates_request_idx on maintenance_updates(request_id, created_at);

-- ---------------------------------------------------------------------------
-- Preventive maintenance (AC servicing, pest control, fire safety, pool)
-- ---------------------------------------------------------------------------
create table preventive_maintenance_plans (
  id                uuid primary key default gen_random_uuid(),
  unit_id           uuid references units(id) on delete cascade,
  property_id       uuid references properties(id) on delete cascade,
  category          maintenance_category not null,
  title             text not null,
  frequency_months  integer not null default 6 check (frequency_months > 0),
  vendor_id         uuid references vendors(id) on delete set null,
  estimated_cost_aed numeric(12,2),
  last_completed_on date,
  next_due_on       date not null,
  is_active         boolean not null default true,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (unit_id is not null or property_id is not null)
);
create index pm_plans_due_idx on preventive_maintenance_plans(next_due_on) where is_active;
create trigger pm_plans_touch before update on preventive_maintenance_plans
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Document vault
-- Polymorphic by (entity_kind, entity_id). Sensitive documents (ID copies,
-- bank letters) carry is_sensitive so RLS can restrict them further.
-- ---------------------------------------------------------------------------
create table documents (
  id              uuid primary key default gen_random_uuid(),
  kind            document_kind not null default 'other',
  entity_kind     document_entity not null,
  entity_id       uuid,
  -- Denormalised unit link so unit-scoped RLS and the unit vault stay simple
  -- even for documents attached to a lease or booking.
  unit_id         uuid references units(id) on delete cascade,
  owner_id        uuid references owners(id) on delete cascade,

  title           text not null,
  bucket          text not null default 'documents',
  storage_path    text not null,
  file_name       text not null,
  mime_type       text,
  size_bytes      bigint,
  checksum        text,

  reference_number text,                 -- Ejari no, permit no, policy no...
  issued_on       date,
  expires_on      date,
  issuing_authority text,

  is_sensitive    boolean not null default false,
  is_owner_visible boolean not null default true,
  is_tenant_visible boolean not null default false,

  version         integer not null default 1,
  replaces_id     uuid references documents(id) on delete set null,
  uploaded_by     uuid references profiles(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index documents_entity_idx on documents(entity_kind, entity_id);
create index documents_unit_idx on documents(unit_id);
create index documents_owner_idx on documents(owner_id);
create index documents_expiry_idx on documents(expires_on) where expires_on is not null;
create index documents_kind_idx on documents(kind);
create trigger documents_touch before update on documents
  for each row execute function pms.touch_updated_at();

alter table booking_guests
  add constraint booking_guests_id_document_fk
  foreign key (id_document_id) references documents(id) on delete set null;

-- ---------------------------------------------------------------------------
-- Compliance alerts: one row per (item, threshold) actually dispatched, so a
-- reminder is never sent twice for the same window.
-- ---------------------------------------------------------------------------
create table compliance_alerts (
  id            uuid primary key default gen_random_uuid(),
  kind          compliance_kind not null,
  entity_kind   document_entity not null,
  entity_id     uuid not null,
  unit_id       uuid references units(id) on delete cascade,
  owner_id      uuid references owners(id) on delete cascade,
  label         text not null,
  due_date      date not null,
  threshold_days integer not null,
  severity      compliance_severity not null default 'due_soon',
  channel       message_channel,
  sent_at       timestamptz,
  acknowledged_at timestamptz,
  acknowledged_by uuid references profiles(id) on delete set null,
  resolved_at   timestamptz,
  created_at    timestamptz not null default now(),
  unique (kind, entity_id, due_date, threshold_days)
);
create index compliance_alerts_due_idx on compliance_alerts(due_date) where resolved_at is null;

-- ---------------------------------------------------------------------------
-- Audit trail. Written by triggers on financial and compliance tables so it
-- cannot be bypassed by application code.
-- ---------------------------------------------------------------------------
create table audit_log (
  id          bigserial primary key,
  actor_id    uuid references profiles(id) on delete set null,
  actor_role  app_role,
  action      audit_action not null,
  entity_table text not null,
  entity_id   uuid,
  changed_fields text[],
  before_data jsonb,
  after_data  jsonb,
  note        text,
  ip_address  inet,
  user_agent  text,
  created_at  timestamptz not null default now()
);
create index audit_entity_idx on audit_log(entity_table, entity_id, created_at desc);
create index audit_actor_idx on audit_log(actor_id, created_at desc);

create or replace function pms.write_audit()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_actor  uuid := auth.uid();
  v_role   app_role;
  v_before jsonb;
  v_after  jsonb;
  v_fields text[];
begin
  select role into v_role from profiles where id = v_actor;

  if tg_op = 'DELETE' then
    v_before := to_jsonb(old);
  elsif tg_op = 'INSERT' then
    v_after := to_jsonb(new);
  else
    v_before := to_jsonb(old);
    v_after  := to_jsonb(new);
    select array_agg(key) into v_fields
    from jsonb_each(v_after) a
    where a.value is distinct from v_before -> a.key;

    -- Nothing of substance changed (only updated_at) - skip the noise.
    if v_fields is null or v_fields <@ array['updated_at'] then
      return new;
    end if;
  end if;

  insert into audit_log (actor_id, actor_role, action, entity_table, entity_id,
                         changed_fields, before_data, after_data)
  values (
    v_actor,
    v_role,
    lower(tg_op)::audit_action,
    tg_table_name,
    coalesce((v_after ->> 'id')::uuid, (v_before ->> 'id')::uuid),
    v_fields,
    v_before,
    v_after
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

-- Audit the records regulators and owners will ask about.
do $$
declare
  t text;
begin
  foreach t in array array[
    'leases','lease_installments','lease_occupants','rent_increase_notices','lease_notices',
    'holiday_home_permits','bookings','management_agreements','unit_ownerships',
    'ledger_entries','invoices','payments','owner_statements','service_charge_invoices',
    'documents','maintenance_requests','owner_bank_accounts','company_settings','profiles'
  ]
  loop
    execute format(
      'create trigger %I after insert or update or delete on %I
         for each row execute function pms.write_audit()',
      t || '_audit', t
    );
  end loop;
end;
$$;

-- ####################################################################
-- ## 0008_crm_comms_addons.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0008 CRM, communications hub, interior design, fleet
-- Phase 3 modules. Tables land now so Phase 1/2 data never needs a breaking
-- migration to accommodate them.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- CRM / leads (deliberately lightweight - the brokerage may keep its own CRM)
-- ---------------------------------------------------------------------------
create table leads (
  id                uuid primary key default gen_random_uuid(),
  reference         text unique,
  source            lead_source not null default 'website',
  intent            lead_intent not null default 'long_term_rent',
  stage             lead_stage not null default 'new',

  full_name         text not null,
  email             text,
  phone             text,
  whatsapp          text,
  nationality       text,
  preferred_locale  text not null default 'en',

  budget_min_aed    numeric(12,2),
  budget_max_aed    numeric(12,2),
  preferred_areas   text[],
  bedrooms_wanted   numeric(3,1),
  move_in_from      date,
  -- Short-stay enquiries carry dates instead of a move-in date
  stay_check_in     date,
  stay_check_out    date,
  party_size        integer,

  unit_id           uuid references units(id) on delete set null,
  assigned_to       uuid references profiles(id) on delete set null,
  next_follow_up_at timestamptz,
  lost_reason       text,

  -- Conversion targets: a won lead becomes a lease or a booking, no re-entry.
  converted_lease_id   uuid references leases(id) on delete set null,
  converted_booking_id uuid references bookings(id) on delete set null,
  converted_tenant_id  uuid references tenants(id) on delete set null,
  converted_guest_id   uuid references guests(id) on delete set null,
  converted_at         timestamptz,

  raw_payload       jsonb,          -- original website/WhatsApp payload
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index leads_stage_idx on leads(stage) where stage not in ('won','lost');
create index leads_assignee_idx on leads(assigned_to);
create index leads_followup_idx on leads(next_follow_up_at) where stage not in ('won','lost');
create trigger leads_touch before update on leads
  for each row execute function pms.touch_updated_at();

create table lead_activities (
  id          uuid primary key default gen_random_uuid(),
  lead_id     uuid not null references leads(id) on delete cascade,
  author_id   uuid references profiles(id) on delete set null,
  kind        text not null default 'note',      -- note | call | whatsapp | email | viewing
  body        text,
  stage_from  lead_stage,
  stage_to    lead_stage,
  occurred_at timestamptz not null default now(),
  created_at  timestamptz not null default now()
);
create index lead_activities_lead_idx on lead_activities(lead_id, occurred_at desc);

create table viewings (
  id            uuid primary key default gen_random_uuid(),
  lead_id       uuid references leads(id) on delete cascade,
  unit_id       uuid not null references units(id) on delete cascade,
  agent_id      uuid references profiles(id) on delete set null,
  scheduled_at  timestamptz not null,
  duration_minutes integer not null default 30,
  status        task_status not null default 'pending',
  feedback      text,
  interest_level integer check (interest_level is null or interest_level between 1 and 5),
  vehicle_booking_id uuid,                    -- FK added after vehicle_bookings
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index viewings_unit_idx on viewings(unit_id, scheduled_at);
create index viewings_agent_idx on viewings(agent_id, scheduled_at);
create trigger viewings_touch before update on viewings
  for each row execute function pms.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Communications hub. WhatsApp-first, email fallback.
-- Provider is abstracted - business logic must never branch on it.
-- ---------------------------------------------------------------------------
create table message_templates (
  id           uuid primary key default gen_random_uuid(),
  code         text not null,
  channel      message_channel not null default 'whatsapp',
  locale       text not null default 'en',
  name         text not null,
  category     text not null default 'general',
  subject      text,
  body         text not null,
  -- Variables the renderer will substitute, e.g. {tenant_name}, {due_date}
  variables    text[] not null default '{}',
  -- WhatsApp Business API approved template name, when applicable
  provider_template_name text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (code, channel, locale)
);
create trigger message_templates_touch before update on message_templates
  for each row execute function pms.touch_updated_at();

create table messages (
  id            uuid primary key default gen_random_uuid(),
  channel       message_channel not null,
  direction     message_direction not null default 'outbound',
  status        message_status not null default 'queued',
  template_id   uuid references message_templates(id) on delete set null,

  party_kind    party_kind not null,
  party_id      uuid,
  to_address    text not null,               -- phone (E.164) or email
  from_address  text,

  unit_id       uuid references units(id) on delete set null,
  lease_id      uuid references leases(id) on delete set null,
  booking_id    uuid references bookings(id) on delete set null,
  maintenance_request_id uuid references maintenance_requests(id) on delete set null,

  subject       text,
  body          text not null,
  variables     jsonb,
  provider      text,
  provider_message_id text,
  error_message text,
  queued_at     timestamptz not null default now(),
  sent_at       timestamptz,
  delivered_at  timestamptz,
  read_at       timestamptz,
  created_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now()
);
create index messages_party_idx on messages(party_kind, party_id, created_at desc);
create index messages_unit_idx on messages(unit_id, created_at desc);
create index messages_pending_idx on messages(queued_at) where status = 'queued';

-- ---------------------------------------------------------------------------
-- Module L: interior design / furnishing service orders
-- ---------------------------------------------------------------------------
create table service_orders (
  id                uuid primary key default gen_random_uuid(),
  order_number      text unique not null,
  kind              service_order_kind not null default 'furnishing',
  status            service_order_status not null default 'requested',
  unit_id           uuid not null references units(id) on delete cascade,
  owner_id          uuid references owners(id) on delete set null,
  tenant_id         uuid references tenants(id) on delete set null,
  requested_by      uuid references profiles(id) on delete set null,

  title             text not null,
  brief             text,
  quoted_amount_aed numeric(12,2),
  approved_amount_aed numeric(12,2),
  final_amount_aed  numeric(12,2),
  vat_applicable    boolean not null default true,   -- furnishing is a taxable supply

  quoted_at         timestamptz,
  approved_by       uuid references profiles(id) on delete set null,
  approved_at       timestamptz,
  started_at        timestamptz,
  delivered_at      timestamptz,
  invoice_id        uuid references invoices(id) on delete set null,
  ledger_entry_id   uuid references ledger_entries(id) on delete set null,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index service_orders_unit_idx on service_orders(unit_id);
create index service_orders_status_idx on service_orders(status)
  where status not in ('delivered','cancelled','invoiced');
create trigger service_orders_touch before update on service_orders
  for each row execute function pms.touch_updated_at();

create table service_order_items (
  id             uuid primary key default gen_random_uuid(),
  order_id       uuid not null references service_orders(id) on delete cascade,
  description    text not null,
  room           text,
  quantity       numeric(10,2) not null default 1,
  unit_cost_aed  numeric(12,2) not null default 0,
  line_total_aed numeric(12,2) generated always as (round(quantity * unit_cost_aed, 2)) stored,
  supplier       text,
  lead_time_days integer,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now()
);
create index service_order_items_order_idx on service_order_items(order_id, sort_order);

-- ---------------------------------------------------------------------------
-- Module M: fleet register (simple internal scheduling tool)
-- ---------------------------------------------------------------------------
create table vehicles (
  id                uuid primary key default gen_random_uuid(),
  make              text not null,
  model             text not null,
  model_year        integer,
  colour            text,
  plate_number      text not null,
  plate_emirate     emirate not null default 'dubai',
  plate_code        text,
  vin               text,
  category          vehicle_category not null default 'staff',
  seats             integer not null default 5,
  registration_expiry date,                 -- Mulkiya
  insurance_expiry  date,
  insurance_policy_number text,
  odometer_km       integer,
  default_driver_id uuid references profiles(id) on delete set null,
  is_active         boolean not null default true,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (plate_emirate, plate_code, plate_number)
);
create index vehicles_expiry_idx on vehicles(registration_expiry, insurance_expiry) where is_active;
create trigger vehicles_touch before update on vehicles
  for each row execute function pms.touch_updated_at();

create table vehicle_bookings (
  id            uuid primary key default gen_random_uuid(),
  vehicle_id    uuid not null references vehicles(id) on delete cascade,
  driver_id     uuid references profiles(id) on delete set null,
  purpose       vehicle_booking_purpose not null default 'viewing',
  status        task_status not null default 'pending',
  start_at      timestamptz not null,
  end_at        timestamptz not null,
  pickup        text,
  destination   text,
  passenger_name text,
  lead_id       uuid references leads(id) on delete set null,
  viewing_id    uuid references viewings(id) on delete set null,
  booking_id    uuid references bookings(id) on delete set null,   -- guest transfer
  odometer_start integer,
  odometer_end  integer,
  notes         text,
  created_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (end_at > start_at)
);
create index vehicle_bookings_vehicle_idx on vehicle_bookings(vehicle_id, start_at);
create trigger vehicle_bookings_touch before update on vehicle_bookings
  for each row execute function pms.touch_updated_at();

-- One vehicle, one trip at a time.
alter table vehicle_bookings add constraint vehicle_bookings_no_overlap
  exclude using gist (
    vehicle_id with =,
    tstzrange(start_at, end_at) with &&
  ) where (status in ('pending','assigned','in_progress'));

alter table viewings
  add constraint viewings_vehicle_booking_fk
  foreign key (vehicle_booking_id) references vehicle_bookings(id) on delete set null;

-- ####################################################################
-- ## 0009_views_access.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0009 Access helper functions + reporting views
--
-- The helpers are SECURITY DEFINER so RLS policies can consult profiles /
-- ownership tables without recursing into their own policies.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Who am I?
-- ---------------------------------------------------------------------------
create or replace function pms.my_role()
returns app_role
language sql
stable
security definer
set search_path = public, pms
as $$
  select role from profiles where id = auth.uid() and is_active;
$$;

create or replace function pms.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select coalesce(pms.my_role() = 'super_admin', false);
$$;

-- Roles that work inside the back office (as opposed to portal users).
create or replace function pms.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select coalesce(
    pms.my_role() in ('super_admin','property_manager','agent','finance','marketing','maintenance'),
    false
  );
$$;

-- Roles allowed to see money in full.
create or replace function pms.is_finance()
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select coalesce(pms.my_role() in ('super_admin','finance'), false);
$$;

-- Roles that may create/modify property, lease and booking records.
create or replace function pms.is_manager()
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select coalesce(pms.my_role() in ('super_admin','property_manager'), false);
$$;

-- ---------------------------------------------------------------------------
-- Unit scoping. One function, used by nearly every policy.
-- ---------------------------------------------------------------------------
create or replace function pms.owns_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1
    from unit_ownerships uo
    join owner_users ou on ou.owner_id = uo.owner_id
    where uo.unit_id = p_unit_id
      and uo.end_date is null
      and ou.profile_id = auth.uid()
  );
$$;

create or replace function pms.my_owner_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, pms
as $$
  select owner_id from owner_users where profile_id = auth.uid();
$$;

create or replace function pms.tenants_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1
    from leases l
    join tenants t on t.id = l.tenant_id
    where l.unit_id = p_unit_id
      and t.profile_id = auth.uid()
      and l.status in ('pending_signature','active','expiring','renewed')
  );
$$;

create or replace function pms.stays_in_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1
    from bookings b
    join guests g on g.id = b.guest_id
    where b.unit_id = p_unit_id
      and g.profile_id = auth.uid()
      and b.status in ('confirmed','checked_in')
      and b.check_out >= current_date - 7
  );
$$;

-- Staff assignment: super admin, finance and marketing see everything;
-- property managers, agents and maintenance staff see only what they are
-- assigned to (directly on the unit, or via the whole property).
create or replace function pms.staff_scoped_to_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select case
    when pms.my_role() in ('super_admin','finance','marketing') then true
    when pms.my_role() in ('property_manager','agent','maintenance') then exists (
      select 1 from staff_unit_assignments sua
      where sua.unit_id = p_unit_id and sua.profile_id = auth.uid()
      union all
      select 1 from staff_property_assignments spa
      join units u on u.property_id = spa.property_id
      where u.id = p_unit_id and spa.profile_id = auth.uid()
    )
    else false
  end;
$$;

-- The master gate used by unit-scoped policies.
create or replace function pms.can_read_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.staff_scoped_to_unit(p_unit_id)
      or pms.owns_unit(p_unit_id)
      or pms.tenants_unit(p_unit_id)
      or pms.stays_in_unit(p_unit_id);
$$;

create or replace function pms.can_write_unit(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.my_role() in ('super_admin','property_manager','agent')
     and pms.staff_scoped_to_unit(p_unit_id);
$$;

-- ---------------------------------------------------------------------------
-- Cross-table access helpers.
--
-- These exist because RLS policies must never query a table whose own policy
-- queries back: `leases` <-> `tenants` and `bookings` <-> `guests` would
-- recurse forever. Wrapping each lookup in a SECURITY DEFINER function breaks
-- the cycle, because the body runs with RLS bypassed.
-- ---------------------------------------------------------------------------
create or replace function pms.is_my_tenant_record(p_tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from tenants where id = p_tenant_id and profile_id = auth.uid()
  );
$$;

create or replace function pms.is_my_guest_record(p_guest_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from guests where id = p_guest_id and profile_id = auth.uid()
  );
$$;

create or replace function pms.can_read_tenant(p_tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.is_my_tenant_record(p_tenant_id)
      or pms.my_role() in ('super_admin','finance')
      or exists (
           select 1 from leases l
           where l.tenant_id = p_tenant_id
             and pms.staff_scoped_to_unit(l.unit_id)
         );
$$;

create or replace function pms.can_read_guest(p_guest_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.is_my_guest_record(p_guest_id)
      or pms.my_role() in ('super_admin','finance')
      or exists (
           select 1 from bookings b
           where b.guest_id = p_guest_id
             and pms.staff_scoped_to_unit(b.unit_id)
         );
$$;

create or replace function pms.can_read_lease(p_lease_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from leases l
    where l.id = p_lease_id
      and (pms.can_read_unit(l.unit_id) or pms.is_my_tenant_record(l.tenant_id))
  );
$$;

create or replace function pms.can_write_lease(p_lease_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from leases l
    where l.id = p_lease_id and pms.can_write_unit(l.unit_id)
  );
$$;

-- Tenants may maintain their own declared-occupant list: that is what keeps
-- the Ejari record current within the 30-day window.
create or replace function pms.can_declare_occupants(p_lease_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from leases l
    where l.id = p_lease_id
      and (pms.can_write_unit(l.unit_id) or pms.is_my_tenant_record(l.tenant_id))
  );
$$;

create or replace function pms.can_read_booking(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from bookings b
    where b.id = p_booking_id
      and (pms.can_read_unit(b.unit_id) or pms.is_my_guest_record(b.guest_id))
  );
$$;

create or replace function pms.can_register_booking_guests(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from bookings b
    where b.id = p_booking_id
      and (pms.can_write_unit(b.unit_id) or pms.is_my_guest_record(b.guest_id))
  );
$$;

create or replace function pms.can_read_property(p_property_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.my_role() in ('super_admin','finance','marketing')
      or exists (
           select 1 from units u
           where u.property_id = p_property_id and pms.can_read_unit(u.id)
         );
$$;

grant execute on all functions in schema pms to authenticated;

-- ============================================================================
-- Reporting views
-- ============================================================================

-- ---------------------------------------------------------------------------
-- v_units_overview : the shape the unit list / property card needs, without
-- the client having to run six joins.
-- ---------------------------------------------------------------------------
create or replace view v_units_overview
with (security_invoker = true)
as
select
  u.id,
  u.unit_number,
  u.reference_code,
  u.kind,
  u.bedrooms,
  u.bathrooms,
  u.size_sqft,
  u.furnishing,
  u.operating_mode,
  u.status,
  u.target_annual_rent_aed,
  u.base_nightly_rate_aed,
  u.is_active,
  p.id   as property_id,
  p.name as property_name,
  p.kind as property_kind,
  c.id   as community_id,
  c.name as community_name,
  c.emirate,
  -- Primary owner
  o.id   as owner_id,
  o.full_name as owner_name,
  -- Current long-term lease
  l.id   as current_lease_id,
  l.lease_number,
  l.end_date as lease_end_date,
  l.annual_rent_aed,
  l.ejari_status,
  l.ejari_expiry,
  -- Live DET permit
  hp.permit_number as det_permit_number,
  hp.expires_on    as det_permit_expiry,
  pms.unit_has_valid_permit(u.id) as has_valid_permit,
  -- Cover image
  (select um.storage_path from unit_media um
    where um.unit_id = u.id order by um.is_cover desc, um.sort_order limit 1) as cover_path,
  (select count(*) from maintenance_requests mr
    where mr.unit_id = u.id
      and mr.status not in ('closed','cancelled','rejected')) as open_tickets
from units u
join properties p on p.id = u.property_id
left join communities c on c.id = p.community_id
left join lateral (
  select uo.owner_id from unit_ownerships uo
  where uo.unit_id = u.id and uo.end_date is null
  order by uo.is_primary_contact desc, uo.ownership_pct desc limit 1
) po on true
left join owners o on o.id = po.owner_id
left join lateral (
  select * from leases lx
  where lx.unit_id = u.id and lx.status in ('active','expiring')
  order by lx.start_date desc limit 1
) l on true
left join lateral (
  select * from holiday_home_permits hx
  where hx.unit_id = u.id and hx.status = 'active'
  order by hx.expires_on desc limit 1
) hp on true;

-- ---------------------------------------------------------------------------
-- v_compliance_calendar : one unified feed of everything that expires.
-- This is the single source for the compliance dashboard and the alert job.
-- ---------------------------------------------------------------------------
create or replace view v_compliance_calendar
with (security_invoker = true)
as
with settings as (select * from company_settings where id)
-- Ejari registration expiry
select
  'ejari_expiry'::compliance_kind as kind,
  'lease'::document_entity        as entity_kind,
  l.id                            as entity_id,
  l.unit_id,
  null::uuid                      as owner_id,
  'Ejari ' || coalesce(l.ejari_contract_number, l.lease_number) as label,
  l.ejari_expiry                  as due_date,
  (l.ejari_expiry - current_date) as days_remaining
from leases l
where l.ejari_status = 'registered'
  and l.ejari_expiry is not null
  and l.status in ('active','expiring')

union all
-- Ejari occupant declaration staleness (2026 30-day data-currency rule).
-- Due date = the deadline by which Ejari must be updated.
select
  'ejari_occupant_declaration'::compliance_kind,
  'lease'::document_entity,
  l.id,
  l.unit_id,
  null::uuid,
  'Ejari occupant details - ' || l.lease_number,
  (oc.last_change::date + (select ejari_occupant_update_days from settings)),
  (oc.last_change::date + (select ejari_occupant_update_days from settings)) - current_date
from leases l
join lateral (
  select max(greatest(o.updated_at, o.created_at)) as last_change
  from lease_occupants o
  where o.lease_id = l.id and o.removed_on is null
) oc on true
where l.status in ('active','expiring')
  and oc.last_change is not null
  -- Stale = occupants changed since the last push to Ejari (or never pushed).
  and (l.ejari_occupants_synced_at is null
       or l.ejari_occupants_synced_at < oc.last_change)

union all
-- Lease expiry itself
select
  'lease_expiry'::compliance_kind,
  'lease'::document_entity,
  l.id,
  l.unit_id,
  null::uuid,
  'Tenancy ' || l.lease_number,
  l.end_date,
  l.end_date - current_date
from leases l
where l.status in ('active','expiring')

union all
-- DET holiday home permit
select
  'det_permit_expiry'::compliance_kind,
  'permit'::document_entity,
  hp.id,
  hp.unit_id,
  null::uuid,
  'DET permit ' || hp.permit_number,
  hp.expires_on,
  hp.expires_on - current_date
from holiday_home_permits hp
where hp.status = 'active'

union all
-- Building NOC backing the permit
select
  'building_noc_expiry'::compliance_kind,
  'permit'::document_entity,
  hp.id,
  hp.unit_id,
  null::uuid,
  'Building NOC ' || coalesce(hp.noc_reference, ''),
  hp.noc_expires_on,
  hp.noc_expires_on - current_date
from holiday_home_permits hp
where hp.status = 'active' and hp.noc_expires_on is not null

union all
-- Management agreement
select
  'management_agreement_expiry'::compliance_kind,
  'management_agreement'::document_entity,
  ma.id,
  ma.unit_id,
  ma.owner_id,
  'Management agreement ' || coalesce(ma.agreement_number, ''),
  ma.end_date,
  ma.end_date - current_date
from management_agreements ma
where ma.is_active

union all
-- Any document in the vault carrying an expiry date
select
  case d.kind
    when 'insurance_policy' then 'insurance_expiry'
    when 'emirates_id'      then 'emirates_id_expiry'
    when 'passport'         then 'passport_expiry'
    when 'trade_licence'    then 'trade_licence_expiry'
    else 'document_expiry'
  end::compliance_kind,
  d.entity_kind,
  d.id,
  d.unit_id,
  d.owner_id,
  d.title,
  d.expires_on,
  d.expires_on - current_date
from documents d
where d.expires_on is not null

union all
-- Preventive maintenance
select
  'preventive_maintenance'::compliance_kind,
  'unit'::document_entity,
  pm.id,
  pm.unit_id,
  null::uuid,
  pm.title,
  pm.next_due_on,
  pm.next_due_on - current_date
from preventive_maintenance_plans pm
where pm.is_active

union all
-- Fleet
select
  'vehicle_registration'::compliance_kind,
  'vehicle'::document_entity,
  v.id, null::uuid, null::uuid,
  'Mulkiya ' || v.plate_number,
  v.registration_expiry,
  v.registration_expiry - current_date
from vehicles v
where v.is_active and v.registration_expiry is not null

union all
select
  'vehicle_insurance'::compliance_kind,
  'vehicle'::document_entity,
  v.id, null::uuid, null::uuid,
  'Vehicle insurance ' || v.plate_number,
  v.insurance_expiry,
  v.insurance_expiry - current_date
from vehicles v
where v.is_active and v.insurance_expiry is not null;

-- Severity banding applied on top, so the thresholds live in one place.
create or replace view v_compliance_status
with (security_invoker = true)
as
select
  cc.*,
  case
    when cc.days_remaining < 0   then 'overdue'
    when cc.days_remaining <= 7  then 'urgent'
    when cc.days_remaining <= 60 then 'due_soon'
    else 'ok'
  end::compliance_severity as severity
from v_compliance_calendar cc
where cc.due_date is not null;

-- ---------------------------------------------------------------------------
-- v_unit_financials : per-unit income/expense rollup driving the P&L views
-- ---------------------------------------------------------------------------
create or replace view v_unit_financials
with (security_invoker = true)
as
select
  le.unit_id,
  date_trunc('month', le.entry_date)::date as period_month,
  sum(le.amount_aed) filter (where le.direction = 'income')  as income_aed,
  sum(le.amount_aed) filter (where le.direction = 'expense') as expense_aed,
  sum(le.vat_amount_aed)                                     as vat_aed,
  sum(case when le.direction = 'income' then le.amount_aed else -le.amount_aed end) as net_aed,
  count(*) as entry_count
from ledger_entries le
where le.unit_id is not null
group by le.unit_id, date_trunc('month', le.entry_date);

-- ---------------------------------------------------------------------------
-- v_occupancy_daily : long-term vs short-term occupancy, for the dashboard
-- ---------------------------------------------------------------------------
create or replace view v_occupancy_daily
with (security_invoker = true)
as
select
  d.day::date as day,
  u.id as unit_id,
  u.operating_mode,
  exists (
    select 1 from leases l
    where l.unit_id = u.id and l.status in ('active','expiring')
      and d.day between l.start_date and l.end_date
  ) as long_term_occupied,
  exists (
    select 1 from bookings b
    where b.unit_id = u.id and b.status in ('confirmed','checked_in','checked_out')
      and d.day >= b.check_in and d.day < b.check_out
  ) as short_term_occupied
from units u
cross join lateral generate_series(
  date_trunc('month', current_date - interval '11 months'),
  date_trunc('month', current_date) + interval '1 month' - interval '1 day',
  interval '1 day'
) d(day)
where u.is_active;

-- ####################################################################
-- ## 0010_rls.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0010 Row Level Security
--
-- Principle: every table is deny-by-default. Access is granted by the helper
-- functions in 0009, which resolve a user to the units they may see:
--   staff  -> assigned units (super_admin / finance / marketing: all)
--   owner  -> units they own, via owner_users -> unit_ownerships
--   tenant -> units on their active lease, via tenants.profile_id
--   guest  -> units on their current/recent booking, via guests.profile_id
--
-- The service_role key bypasses RLS entirely and is only ever used by
-- server-side jobs (alerts, statement generation), never by request handlers
-- acting on behalf of a user.
-- ============================================================================

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles','company_settings','communities','properties','units','unit_media',
    'staff_property_assignments','staff_unit_assignments',
    'owners','owner_bank_accounts','owner_users','unit_ownerships','management_agreements',
    'tenants','leases','lease_occupants','lease_installments','deposit_transactions',
    'rent_increase_notices','lease_notices','direct_debit_mandates',
    'holiday_home_permits','channel_listings','pricing_connections','nightly_rates',
    'guests','bookings','booking_guests','availability_blocks','housekeeping_tasks',
    'gl_categories','ledger_entries','invoices','invoice_lines','payments',
    'payment_allocations','service_charge_invoices','owner_statements','owner_statement_lines',
    'vendors','maintenance_requests','maintenance_updates','preventive_maintenance_plans',
    'documents','compliance_alerts','audit_log',
    'leads','lead_activities','viewings','message_templates','messages',
    'service_orders','service_order_items','vehicles','vehicle_bookings'
  ]
  loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
create policy profiles_self_read on profiles
  for select to authenticated
  using (id = auth.uid() or pms.is_staff());

create policy profiles_self_update on profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid() and role = (select role from profiles p where p.id = auth.uid()));

create policy profiles_admin_all on profiles
  for all to authenticated
  using (pms.is_admin()) with check (pms.is_admin());

-- ---------------------------------------------------------------------------
-- company_settings : everyone signed in may read branding/VAT rate;
-- only super admin writes.
-- ---------------------------------------------------------------------------
create policy company_settings_read on company_settings
  for select to authenticated using (true);

create policy company_settings_write on company_settings
  for all to authenticated
  using (pms.is_admin()) with check (pms.is_admin());

