create policy housekeeping_write on housekeeping_tasks
  for all to authenticated
  using (assigned_to = auth.uid() or pms.can_write_unit(unit_id))
  with check (assigned_to = auth.uid() or pms.can_write_unit(unit_id));

-- ---------------------------------------------------------------------------
-- Finance. Owners see their own numbers; tenants and guests see none of it
-- except the invoices addressed to them.
-- ---------------------------------------------------------------------------
create policy ledger_read on ledger_entries
  for select to authenticated
  using (
    pms.is_finance()
    or (unit_id is not null and pms.staff_scoped_to_unit(unit_id))
    or (is_owner_visible and owner_id in (select pms.my_owner_ids()))
  );
create policy ledger_write on ledger_entries
  for all to authenticated
  using (pms.is_finance() or (unit_id is not null and pms.can_write_unit(unit_id)))
  with check (pms.is_finance() or (unit_id is not null and pms.can_write_unit(unit_id)));

create policy invoices_read on invoices
  for select to authenticated
  using (
    pms.is_finance()
    or (unit_id is not null and pms.staff_scoped_to_unit(unit_id))
    or (party_kind = 'owner'  and party_id in (select pms.my_owner_ids()))
    or (party_kind = 'tenant' and pms.is_my_tenant_record(party_id))
    or (party_kind = 'guest'  and pms.is_my_guest_record(party_id))
  );
create policy invoices_write on invoices
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

create policy invoice_lines_read on invoice_lines
  for select to authenticated
  using (exists (select 1 from invoices i where i.id = invoice_lines.invoice_id));
create policy invoice_lines_write on invoice_lines
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

create policy payments_read on payments
  for select to authenticated
  using (
    pms.is_finance()
    or (unit_id is not null and pms.staff_scoped_to_unit(unit_id))
    or (party_kind = 'owner' and party_id in (select pms.my_owner_ids()))
  );
create policy payments_write on payments
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

create policy payment_allocations_read on payment_allocations
  for select to authenticated
  using (exists (select 1 from payments p where p.id = payment_allocations.payment_id));
create policy payment_allocations_write on payment_allocations
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

create policy service_charges_read on service_charge_invoices
  for select to authenticated using (pms.is_finance() or pms.can_read_unit(unit_id));
create policy service_charges_write on service_charge_invoices
  for all to authenticated
  using (pms.is_finance() or pms.can_write_unit(unit_id))
  with check (pms.is_finance() or pms.can_write_unit(unit_id));

create policy owner_statements_read on owner_statements
  for select to authenticated
  using (
    pms.is_finance()
    or pms.is_manager()
    or (status in ('issued','approved','paid') and owner_id in (select pms.my_owner_ids()))
  );
create policy owner_statements_write on owner_statements
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

create policy owner_statement_lines_read on owner_statement_lines
  for select to authenticated
  using (exists (select 1 from owner_statements s where s.id = owner_statement_lines.statement_id));
create policy owner_statement_lines_write on owner_statement_lines
  for all to authenticated using (pms.is_finance()) with check (pms.is_finance());

-- ---------------------------------------------------------------------------
-- Maintenance
-- ---------------------------------------------------------------------------
create policy vendors_read on vendors
  for select to authenticated using (pms.is_staff());
create policy vendors_write on vendors
  for all to authenticated
  using (pms.is_manager() or pms.my_role() = 'maintenance')
  with check (pms.is_manager() or pms.my_role() = 'maintenance');

create policy maintenance_read on maintenance_requests
  for select to authenticated
  using (
    raised_by = auth.uid()
    or assigned_to = auth.uid()
    or pms.can_read_unit(unit_id)
  );

-- Tenants and guests raise tickets on their own unit; staff manage them.
create policy maintenance_insert on maintenance_requests
  for insert to authenticated
  with check (pms.can_read_unit(unit_id));

create policy maintenance_update on maintenance_requests
  for update to authenticated
  using (
    assigned_to = auth.uid()
    or pms.can_write_unit(unit_id)
    or (owner_approval_required and pms.owns_unit(unit_id))
  )
  with check (
    assigned_to = auth.uid()
    or pms.can_write_unit(unit_id)
    or (owner_approval_required and pms.owns_unit(unit_id))
  );

create policy maintenance_delete on maintenance_requests
  for delete to authenticated using (pms.is_manager());

create policy maintenance_updates_read on maintenance_updates
  for select to authenticated
  using (
    exists (select 1 from maintenance_requests r where r.id = maintenance_updates.request_id)
    and (not is_internal or pms.is_staff())
  );
create policy maintenance_updates_write on maintenance_updates
  for all to authenticated
  using (exists (select 1 from maintenance_requests r where r.id = maintenance_updates.request_id))
  with check (exists (select 1 from maintenance_requests r where r.id = maintenance_updates.request_id));

create policy pm_plans_read on preventive_maintenance_plans
  for select to authenticated
  using (
    (unit_id is not null and pms.can_read_unit(unit_id))
    or (property_id is not null and pms.is_staff())
  );
create policy pm_plans_write on preventive_maintenance_plans
  for all to authenticated
  using (pms.is_manager() or pms.my_role() = 'maintenance')
  with check (pms.is_manager() or pms.my_role() = 'maintenance');

-- ---------------------------------------------------------------------------
-- Documents. Sensitive files (ID copies, bank letters) are staff-only unless
-- the requester is the party the document belongs to.
-- ---------------------------------------------------------------------------
create policy documents_read on documents
  for select to authenticated
  using (
    case
      when is_sensitive then
        pms.my_role() in ('super_admin','property_manager','finance')
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
      else
        (unit_id is not null and pms.can_read_unit(unit_id))
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
        or (entity_kind = 'company' and pms.is_staff())
        or uploaded_by = auth.uid()
    end
    and (
      pms.is_staff()
      or (is_owner_visible and owner_id in (select pms.my_owner_ids()))
      or (is_tenant_visible and unit_id is not null and (pms.tenants_unit(unit_id) or pms.stays_in_unit(unit_id)))
      or uploaded_by = auth.uid()
    )
  );

create policy documents_insert on documents
  for insert to authenticated
  with check (
    pms.is_staff()
    or (unit_id is not null and pms.can_read_unit(unit_id))
  );

create policy documents_update on documents
  for update to authenticated
  using (pms.is_manager() or uploaded_by = auth.uid())
  with check (pms.is_manager() or uploaded_by = auth.uid());

create policy documents_delete on documents
  for delete to authenticated using (pms.is_admin());

create policy compliance_alerts_read on compliance_alerts
  for select to authenticated
  using (
    pms.is_staff()
    or (unit_id is not null and pms.can_read_unit(unit_id))
    or owner_id in (select pms.my_owner_ids())
  );
create policy compliance_alerts_write on compliance_alerts
  for all to authenticated using (pms.is_staff()) with check (pms.is_staff());

-- Audit log is append-only and readable by super admin + finance only.
create policy audit_read on audit_log
  for select to authenticated using (pms.is_admin() or pms.is_finance());
-- No insert/update/delete policy: only SECURITY DEFINER triggers write here.

-- ---------------------------------------------------------------------------
-- CRM / comms / add-ons
-- ---------------------------------------------------------------------------
create policy leads_read on leads
  for select to authenticated
  using (pms.is_staff() and (assigned_to = auth.uid() or pms.my_role() in ('super_admin','property_manager','marketing')));
create policy leads_write on leads
  for all to authenticated
  using (pms.my_role() in ('super_admin','property_manager','agent','marketing'))
  with check (pms.my_role() in ('super_admin','property_manager','agent','marketing'));

create policy lead_activities_read on lead_activities
  for select to authenticated using (exists (select 1 from leads l where l.id = lead_activities.lead_id));
create policy lead_activities_write on lead_activities
  for all to authenticated using (pms.is_staff()) with check (pms.is_staff());

create policy viewings_read on viewings
  for select to authenticated using (agent_id = auth.uid() or pms.can_read_unit(unit_id));
create policy viewings_write on viewings
  for all to authenticated
  using (agent_id = auth.uid() or pms.can_write_unit(unit_id))
  with check (agent_id = auth.uid() or pms.can_write_unit(unit_id));

create policy messages_read on messages
  for select to authenticated
  using (
    pms.is_staff()
    or (party_kind = 'owner'  and party_id in (select pms.my_owner_ids()))
    or (party_kind = 'tenant' and pms.is_my_tenant_record(party_id))
    or (party_kind = 'guest'  and pms.is_my_guest_record(party_id))
  );
create policy messages_write on messages
  for all to authenticated using (pms.is_staff()) with check (pms.is_staff());

create policy service_orders_read on service_orders
  for select to authenticated
  using (pms.can_read_unit(unit_id) or owner_id in (select pms.my_owner_ids()));
create policy service_orders_write on service_orders
  for all to authenticated
  using (pms.can_write_unit(unit_id) or pms.is_finance())
  with check (pms.can_write_unit(unit_id) or pms.is_finance());

create policy service_order_items_read on service_order_items
  for select to authenticated
  using (exists (select 1 from service_orders o where o.id = service_order_items.order_id));
create policy service_order_items_write on service_order_items
  for all to authenticated using (pms.is_staff()) with check (pms.is_staff());

create policy vehicles_read on vehicles
  for select to authenticated using (pms.is_staff());
create policy vehicles_write on vehicles
  for all to authenticated using (pms.is_manager()) with check (pms.is_manager());

create policy vehicle_bookings_read on vehicle_bookings
  for select to authenticated using (pms.is_staff());
create policy vehicle_bookings_write on vehicle_bookings
  for all to authenticated using (pms.is_staff()) with check (pms.is_staff());

-- ####################################################################
-- ## 0011_functions.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0011 Business logic: sequences, cheque schedules, statements,
-- storage buckets and their access policies.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Human-readable reference numbers, per entity, per year.
-- ---------------------------------------------------------------------------
create sequence if not exists pms.lease_seq;
create sequence if not exists pms.booking_seq;
create sequence if not exists pms.ticket_seq;
create sequence if not exists pms.statement_seq;
create sequence if not exists pms.payment_seq;
create sequence if not exists pms.order_seq;
create sequence if not exists pms.agreement_seq;

create or replace function pms.next_reference(p_kind text)
returns text
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  prefix text;
  n      bigint;
  yr     text := to_char(now(), 'YYYY');
begin
  select case p_kind
    when 'lease'     then lease_prefix
    when 'booking'   then booking_prefix
    when 'ticket'    then ticket_prefix
    when 'statement' then statement_prefix
    else 'DRP'
  end into prefix
  from company_settings where id;

  n := case p_kind
    when 'lease'     then nextval('pms.lease_seq')
    when 'booking'   then nextval('pms.booking_seq')
    when 'ticket'    then nextval('pms.ticket_seq')
    when 'statement' then nextval('pms.statement_seq')
    when 'payment'   then nextval('pms.payment_seq')
    when 'order'     then nextval('pms.order_seq')
    when 'agreement' then nextval('pms.agreement_seq')
    else nextval('pms.lease_seq')
  end;

  if p_kind in ('payment','order','agreement') then
    prefix := 'DRP-' || upper(left(p_kind, 3));
  end if;

  return prefix || '-' || yr || '-' || lpad(n::text, 4, '0');
end;
$$;

-- Auto-number on insert when the caller leaves the field blank.
create or replace function pms.autonumber()
returns trigger
language plpgsql
as $$
begin
  -- The field checks must be nested rather than ANDed into the branch
  -- condition: plpgsql resolves new.<field> when it plans the expression, so a
  -- flat `tg_argv[0] = 'lease' and new.lease_number is null` would fail on
  -- every other table that lacks that column.
  if tg_argv[0] = 'lease' then
    if new.lease_number is null or new.lease_number = '' then
      new.lease_number := pms.next_reference('lease');
    end if;
  elsif tg_argv[0] = 'booking' then
    if new.booking_number is null or new.booking_number = '' then
      new.booking_number := pms.next_reference('booking');
    end if;
  elsif tg_argv[0] = 'ticket' then
    if new.ticket_number is null or new.ticket_number = '' then
      new.ticket_number := pms.next_reference('ticket');
    end if;
  elsif tg_argv[0] = 'statement' then
    if new.statement_number is null or new.statement_number = '' then
      new.statement_number := pms.next_reference('statement');
    end if;
  elsif tg_argv[0] = 'payment' then
    if new.payment_reference is null or new.payment_reference = '' then
      new.payment_reference := pms.next_reference('payment');
    end if;
  elsif tg_argv[0] = 'order' then
    if new.order_number is null or new.order_number = '' then
      new.order_number := pms.next_reference('order');
    end if;
  elsif tg_argv[0] = 'agreement' then
    if new.agreement_number is null or new.agreement_number = '' then
      new.agreement_number := pms.next_reference('agreement');
    end if;
  end if;
  return new;
end;
$$;

create trigger leases_autonumber before insert on leases
  for each row execute function pms.autonumber('lease');
create trigger bookings_autonumber before insert on bookings
  for each row execute function pms.autonumber('booking');
create trigger maintenance_autonumber before insert on maintenance_requests
  for each row execute function pms.autonumber('ticket');
create trigger owner_statements_autonumber before insert on owner_statements
  for each row execute function pms.autonumber('statement');
create trigger payments_autonumber before insert on payments
  for each row execute function pms.autonumber('payment');
create trigger service_orders_autonumber before insert on service_orders
  for each row execute function pms.autonumber('order');
create trigger mgmt_agreements_autonumber before insert on management_agreements
  for each row execute function pms.autonumber('agreement');

-- ---------------------------------------------------------------------------
-- Cheque / installment schedule generation.
-- Dubai convention: rent is split into 1, 2, 4, 6 or 12 cheques dated evenly
-- across the term, the first one on the lease start date.
-- ---------------------------------------------------------------------------
create or replace function generate_lease_installments(p_lease_id uuid)
returns integer
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  l              leases%rowtype;
  months_per     numeric;
  per_amount     numeric(12,2);
  remainder      numeric(12,2);
  total          numeric(12,2);
  i              integer;
  due            date;
  created_count  integer := 0;
begin
  select * into l from leases where id = p_lease_id;
  if not found then
    raise exception 'Lease % not found', p_lease_id;
  end if;

  -- Never silently overwrite money that has already moved.
  if exists (
    select 1 from lease_installments
    where lease_id = p_lease_id and status not in ('scheduled','cancelled')
  ) then
    raise exception 'Lease % already has presented or cleared installments', l.lease_number;
  end if;

  delete from lease_installments where lease_id = p_lease_id and status = 'scheduled';

  total := coalesce(l.contract_value_aed, l.annual_rent_aed);
  months_per := 12.0 / l.installment_count;
  per_amount := round(total / l.installment_count, 2);
  -- Rounding difference goes on the first installment, not lost.
  remainder := total - (per_amount * l.installment_count);

  for i in 1..l.installment_count loop
    due := (l.start_date + ((i - 1) * months_per * interval '1 month'))::date;

    insert into lease_installments (
      lease_id, installment_no, due_date, amount_aed, method, cheque_date, status
    ) values (
      p_lease_id,
      i,
      due,
      per_amount + case when i = 1 then remainder else 0 end,
      l.payment_method,
      case when l.payment_method = 'cheque' then due else null end,
      'scheduled'
    );
    created_count := created_count + 1;
  end loop;

  return created_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- Post rent to the ledger when an installment clears. This is what makes the
-- owner statement reflect COLLECTED income rather than invoiced income.
-- ---------------------------------------------------------------------------
create or replace function pms.post_cleared_installment()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_unit   uuid;
  v_owner  uuid;
  v_cat    uuid;
  v_lease  text;
begin
  if new.status <> 'cleared' or coalesce(old.status, 'scheduled') = 'cleared' then
    return new;
  end if;

  select l.unit_id, l.lease_number into v_unit, v_lease
  from leases l where l.id = new.lease_id;

  select uo.owner_id into v_owner
  from unit_ownerships uo
  where uo.unit_id = v_unit and uo.end_date is null
  order by uo.is_primary_contact desc, uo.ownership_pct desc
  limit 1;

  select id into v_cat from gl_categories where code = 'INC-RENT';

  -- Residential long-term rent is VAT-exempt in the UAE, hence false here.
  insert into ledger_entries (
    entry_date, unit_id, owner_id, category_id, direction, description,
    amount_aed, vat_applicable, source_table, source_id, lease_id
  ) values (
    coalesce(new.cleared_on, current_date),
    v_unit, v_owner, v_cat, 'income',
    'Rent installment ' || new.installment_no || ' - ' || v_lease,
    new.amount_aed, false, 'lease_installments', new.id, new.lease_id
  );

  return new;
end;
$$;

create trigger lease_installments_post_ledger
  after update of status on lease_installments
  for each row execute function pms.post_cleared_installment();

-- ---------------------------------------------------------------------------
-- Owner statement generation.
--   gross income   = collected income on the owner's units in the period
--   expenses       = owner-bearing costs in the period
--   management fee = per the active management agreement (% or flat), + VAT
--   net payout     = income - expenses - fee - VAT on the fee
-- Every line is snapshotted so a re-issue can never rewrite history.
-- ---------------------------------------------------------------------------
create or replace function generate_owner_statement(
  p_owner_id uuid,
  p_period_start date,
  p_period_end date
)
returns uuid
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_statement_id uuid;
  v_income   numeric(14,2) := 0;
  v_expense  numeric(14,2) := 0;
  v_fee      numeric(14,2) := 0;
  v_fee_vat  numeric(14,2) := 0;
  v_vat_rate numeric(5,4);
  v_sort     integer := 0;
  r          record;
begin
  select vat_rate into v_vat_rate from company_settings where id;

  if exists (
    select 1 from owner_statements
    where owner_id = p_owner_id
      and period_start = p_period_start
      and period_end = p_period_end
      and status <> 'void'
  ) then
    raise exception 'A statement already exists for this owner and period';
  end if;

  insert into owner_statements (owner_id, period_start, period_end, status, created_by)
  values (p_owner_id, p_period_start, p_period_end, 'draft', auth.uid())
  returning id into v_statement_id;

  -- Snapshot every ledger entry on this owner's units for the period that has
  -- not already been carried on another statement.
  for r in
    select le.*, gc.code as category_code, gc.affects_owner_statement,
           u.unit_number, p.name as property_name
    from ledger_entries le
    join gl_categories gc on gc.id = le.category_id
    left join units u on u.id = le.unit_id
    left join properties p on p.id = u.property_id
    where le.owner_id = p_owner_id
      and le.entry_date between p_period_start and p_period_end
      and le.statement_id is null
      and le.is_owner_visible
      and gc.affects_owner_statement
      and gc.code <> 'EXP-MGMT-FEE'      -- the fee is computed below, not copied
    order by le.entry_date, le.created_at
  loop
    v_sort := v_sort + 1;

    insert into owner_statement_lines (
      statement_id, ledger_entry_id, unit_id, unit_label, entry_date,
      category_code, description, direction, amount_aed, vat_amount_aed,
      total_aed, sort_order
    ) values (
      v_statement_id, r.id, r.unit_id,
      coalesce(r.property_name || ' - ' || r.unit_number, 'Portfolio'),
      r.entry_date, r.category_code, r.description, r.direction,
      r.amount_aed, r.vat_amount_aed, r.total_aed, v_sort
    );

    update ledger_entries set statement_id = v_statement_id where id = r.id;

    if r.direction = 'income' then
      v_income := v_income + r.amount_aed;
    else
      v_expense := v_expense + r.total_aed;
    end if;
  end loop;

  -- Management fee, per unit, from the agreement in force during the period.
  for r in
    select ma.unit_id, ma.commission_pct, ma.fixed_fee_aed, ma.fee_vat_applicable,
           u.unit_number, p.name as property_name,
           coalesce(sum(le.amount_aed) filter (where le.direction = 'income'), 0) as unit_income
    from management_agreements ma
    join units u on u.id = ma.unit_id
    join properties p on p.id = u.property_id
    left join ledger_entries le
      on le.unit_id = ma.unit_id
     and le.statement_id = v_statement_id
     and le.direction = 'income'
    where ma.owner_id = p_owner_id
      and ma.is_active
      and ma.start_date <= p_period_end
      and ma.end_date >= p_period_start
    group by ma.unit_id, ma.commission_pct, ma.fixed_fee_aed, ma.fee_vat_applicable,
             u.unit_number, p.name
  loop
    declare
      line_fee numeric(14,2);
      line_vat numeric(14,2);
    begin
      if r.commission_pct is not null then
        line_fee := round(r.unit_income * r.commission_pct / 100.0, 2);
      else
        line_fee := coalesce(r.fixed_fee_aed, 0);
      end if;

      if line_fee <= 0 then
        continue;
      end if;

      -- Management fee is a taxable supply of services: VAT normally applies.
      line_vat := case when r.fee_vat_applicable then round(line_fee * v_vat_rate, 2) else 0 end;

      v_fee     := v_fee + line_fee;
      v_fee_vat := v_fee_vat + line_vat;
      v_sort    := v_sort + 1;

      insert into owner_statement_lines (
        statement_id, unit_id, unit_label, entry_date, category_code,
        description, direction, amount_aed, vat_amount_aed, total_aed, sort_order
      ) values (
        v_statement_id, r.unit_id, r.property_name || ' - ' || r.unit_number,
        p_period_end, 'EXP-MGMT-FEE',
        case when r.commission_pct is not null
          then 'Management fee (' || r.commission_pct || '% of AED ' || r.unit_income || ')'
          else 'Management fee (fixed)' end,
        'expense', line_fee, line_vat, line_fee + line_vat, v_sort
      );
    end;
  end loop;

  update owner_statements
     set gross_income_aed   = v_income,
         total_expenses_aed = v_expense,
         management_fee_aed = v_fee,
         vat_total_aed      = v_fee_vat,
         net_payout_aed     = v_income - v_expense - v_fee - v_fee_vat,
         closing_balance_aed = v_income - v_expense - v_fee - v_fee_vat
   where id = v_statement_id;

  return v_statement_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Keep unit.status in step with reality instead of relying on staff to
-- remember. Lease activation/termination and bookings drive it.
-- ---------------------------------------------------------------------------
create or replace function pms.sync_unit_status()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
begin
  if new.status = 'active' then
    update units set status = 'occupied_long_term' where id = new.unit_id;
  elsif new.status in ('terminated','expired','cancelled')
        and not exists (
          select 1 from leases
          where unit_id = new.unit_id and status in ('active','expiring') and id <> new.id
        ) then
    update units
       set status = case
             when operating_mode in ('short_term','both')
                  and pms.unit_has_valid_permit(new.unit_id) then 'listed_short_term'
             else 'vacant'
           end
     where id = new.unit_id;
  end if;
  return new;
end;
$$;

create trigger leases_sync_unit_status
  after insert or update of status on leases
  for each row execute function pms.sync_unit_status();

-- ---------------------------------------------------------------------------
-- Turnover housekeeping: when a booking is confirmed, schedule the clean into
-- the checkout -> next check-in gap automatically.
-- ---------------------------------------------------------------------------
create or replace function pms.schedule_turnover()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_next uuid;
begin
  if new.status not in ('confirmed','checked_out') then
    return new;
  end if;

  if exists (select 1 from housekeeping_tasks
             where booking_id = new.id and kind = 'turnover' and status <> 'cancelled') then
    return new;
  end if;

  select id into v_next
  from bookings
  where unit_id = new.unit_id
    and check_in >= new.check_out
    and status in ('tentative','confirmed','checked_in')
    and id <> new.id
  order by check_in
  limit 1;

  insert into housekeeping_tasks (
    unit_id, booking_id, next_booking_id, kind, status, scheduled_start, scheduled_end
  ) values (
    new.unit_id, new.id, v_next, 'turnover', 'pending',
    (new.check_out + time '11:00') at time zone 'Asia/Dubai',
    (new.check_out + time '15:00') at time zone 'Asia/Dubai'
  );

  return new;
end;
$$;

create trigger bookings_schedule_turnover
  after insert or update of status on bookings
  for each row execute function pms.schedule_turnover();

-- Mirror confirmed bookings into the availability calendar so the channel
-- manager has a single surface to read from.
create or replace function pms.sync_booking_block()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
begin
  delete from availability_blocks where booking_id = new.id;

  if new.status in ('tentative','confirmed','checked_in') then
    insert into availability_blocks (unit_id, start_date, end_date, reason, booking_id, source_channel)
    values (new.unit_id, new.check_in, new.check_out, 'booking', new.id, new.channel);
  end if;

  return new;
end;
$$;

create trigger bookings_sync_block
  after insert or update of status, check_in, check_out on bookings
  for each row execute function pms.sync_booking_block();

-- ---------------------------------------------------------------------------
-- Storage buckets. Private by default; access is mediated by signed URLs
-- issued server-side after the same unit check the tables use.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('documents', 'documents', false, 26214400,
   array['application/pdf','image/jpeg','image/png','image/webp','image/heic',
         'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
         'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']),
  ('media', 'media', false, 15728640,
   array['image/jpeg','image/png','image/webp','image/avif','video/mp4'])
on conflict (id) do nothing;

-- Object paths are namespaced as <entity>/<entity_id>/<filename>, so the unit
-- check can be derived from the path itself.
create policy "documents read for permitted staff and parties"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'documents'
    and (
      pms.is_staff()
      or exists (
        select 1 from documents d
        where d.bucket = 'documents'
          and d.storage_path = storage.objects.name
          and (
            (d.unit_id is not null and pms.can_read_unit(d.unit_id))
            or (d.owner_id is not null and d.owner_id in (select pms.my_owner_ids()))
            or d.uploaded_by = auth.uid()
          )
      )
    )
  );

create policy "documents upload for signed-in users"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'documents');

create policy "documents delete for admins"
  on storage.objects for delete to authenticated
  using (bucket_id = 'documents' and pms.is_admin());

create policy "media read for signed-in users"
  on storage.objects for select to authenticated
  using (bucket_id = 'media');

create policy "media write for staff"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and pms.is_staff());

create policy "media delete for staff"
  on storage.objects for delete to authenticated
  using (bucket_id = 'media' and pms.is_staff());

-- ####################################################################
-- ## 0012_grants.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0012 Explicit privilege grants
--
-- Supabase grants privileges on new public tables to anon/authenticated by
-- default. We do not rely on that: `anon` gets nothing, and `authenticated`
-- gets table privileges that RLS then narrows row by row. Being explicit means
-- the security posture survives a project restore or a move off Supabase.
-- ============================================================================

grant usage on schema public to authenticated, service_role;

-- Unauthenticated callers get no access to business data at all.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all functions in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;

grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to authenticated;
grant execute on all functions in schema public to authenticated;

grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant all on all functions in schema public to service_role;

grant usage on schema pms to authenticated, service_role;
grant execute on all functions in schema pms to authenticated, service_role;
grant usage, select on all sequences in schema pms to authenticated, service_role;

alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public
  grant usage, select on sequences to authenticated;

-- The audit log is append-only from the application's point of view: only the
-- SECURITY DEFINER trigger writes to it.
revoke insert, update, delete on audit_log from authenticated;

-- Ledger entries carrying a statement_id are historical record. Deleting them
-- would silently rewrite an issued owner statement.
revoke delete on owner_statement_lines from authenticated;

-- ####################################################################
-- ## 0013_current_profile.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0013 Single-round-trip profile lookup
--
-- Every page needs the signed-in user's profile. Doing that as
-- supabase.auth.getUser() followed by a select on `profiles` costs two
-- sequential round trips to the Supabase region - noticeable when the project
-- is far from the operator, which it is for a Dubai/Colombo team on a US or EU
-- region.
--
-- This collapses it to one. It is no less safe: PostgREST verifies the JWT
-- signature before it sets request.jwt.claims, so auth.uid() here is exactly
-- as trustworthy as it is inside every RLS policy.
-- ============================================================================

create or replace function current_profile()
returns profiles
language sql
stable
security definer
set search_path = public, pms
as $$
  select * from profiles where id = auth.uid() and is_active;
$$;

revoke all on function current_profile() from public, anon;
grant execute on function current_profile() to authenticated;

comment on function current_profile() is
  'The signed-in user''s profile row, or no row when the session is invalid or '
  'the account is deactivated. One round trip instead of getUser() + select.';

-- ####################################################################
-- ## 0014_owner_financial_isolation.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0014 Owner financial isolation
--
-- Rule: an owner never sees income, payouts, nightly rates, commissions or
-- revenue - not in the UI, not through the API, not by querying Supabase
-- directly with their own session.
--
-- Owners and staff share one Postgres role (`authenticated`), so hiding
-- columns with GRANTs is not possible: anything granted to an owner is granted
-- to every admin too. Instead:
--
--   1. Owners are removed from every RLS policy on a table that carries income
--      or rate data. For those tables an owner's row set is now empty.
--   2. Owners read what they need through three views that contain no money
--      columns at all: owner_units_view, owner_bookings_view and
--      owner_calendar_blocks_view. They run as their owner (which bypasses RLS)
--      and filter to the caller's units with pms.owns_unit(), under
--      security_barrier so a caller-supplied function cannot observe rows
--      before that filter runs. They are SELECT-only.
--
-- Costs the owner pays are not income and stay visible: maintenance quotes
-- (owners approve them), service charges, service orders.
--
-- Also fixes a privilege escalation: new accounts took their role from
-- raw_user_meta_data, which the signing-up client controls.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. New accounts get their role from server-controlled metadata only.
--
-- `raw_user_meta_data` is written by whoever calls auth.signUp(), i.e. anyone
-- holding the public key. Taking the role from it let a stranger create a
-- super_admin. `raw_app_meta_data` can only be set with the service key.
-- Everyone else starts as `guest`, which has no portal and no data.
-- ---------------------------------------------------------------------------
create or replace function pms.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_role app_role := 'guest';
begin
  begin
    v_role := coalesce((new.raw_app_meta_data->>'role')::app_role, 'guest');
  exception when invalid_text_representation then
    v_role := 'guest';
  end;

  insert into public.profiles (id, email, full_name, phone, role)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    new.raw_user_meta_data->>'phone',
    v_role
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

alter table profiles alter column role set default 'guest';

-- ---------------------------------------------------------------------------
-- 2. Owner-facing setting: may owners see the guest's first name?
-- ---------------------------------------------------------------------------
alter table company_settings
  add column if not exists show_guest_first_name_to_owners boolean not null default false;

comment on column company_settings.show_guest_first_name_to_owners is
  'When true, owner_bookings_view exposes the lead guest''s first name. Off by default.';

-- Imported bookings (Airbnb iCal) carry no guest count. The table requires at
-- least one adult, so imports record 1 and set this false; owners are then
-- shown "not provided" rather than a made-up number.
alter table bookings
  add column if not exists guest_count_known boolean not null default true;

-- ---------------------------------------------------------------------------
-- 3. The unit gate without the owner branch.
--
-- pms.can_read_unit() lets owners through, which is right for permits,
-- photos, maintenance and documents but wrong for anything carrying money.
-- ---------------------------------------------------------------------------
create or replace function pms.can_read_unit_financials(p_unit_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select pms.staff_scoped_to_unit(p_unit_id)
      or pms.tenants_unit(p_unit_id)
      or pms.stays_in_unit(p_unit_id);
$$;

comment on function pms.can_read_unit_financials(uuid) is
  'pms.can_read_unit() minus owners. Gate for every table carrying rates, rent, '
  'booking money or other income - owners reach those units through the '
  'owner_*_view views instead.';

-- Lease and booking children resolve through these, so switching them cuts
-- owners off from installments, deposits, notices, occupants and booking
-- guests in one place.
create or replace function pms.can_read_lease(p_lease_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from leases l
    where l.id = p_lease_id
      and (pms.can_read_unit_financials(l.unit_id) or pms.is_my_tenant_record(l.tenant_id))
  );
$$;

create or replace function pms.can_read_booking(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select exists (
    select 1 from bookings b
    where b.id = p_booking_id
      and (pms.can_read_unit_financials(b.unit_id) or pms.is_my_guest_record(b.guest_id))
  );
$$;

-- ---------------------------------------------------------------------------
-- 4. Policies. Each replaced policy keeps its name; only the owner path goes.
-- ---------------------------------------------------------------------------

-- Units carry target rent and nightly rate.
drop policy units_read on units;
create policy units_read on units
  for select to authenticated using (pms.can_read_unit_financials(id));

-- Leases carry rent, deposits and fees.
drop policy leases_read on leases;
create policy leases_read on leases
  for select to authenticated
  using (pms.can_read_unit_financials(unit_id) or pms.is_my_tenant_record(tenant_id));

-- Short-term commercial data.
drop policy channel_listings_read on channel_listings;
create policy channel_listings_read on channel_listings
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

drop policy pricing_connections_read on pricing_connections;
create policy pricing_connections_read on pricing_connections
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

drop policy nightly_rates_read on nightly_rates;
create policy nightly_rates_read on nightly_rates
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

-- Bookings carry the whole revenue breakdown. Owners use owner_bookings_view.
drop policy bookings_read on bookings;
create policy bookings_read on bookings
  for select to authenticated
  using (pms.can_read_unit_financials(unit_id) or pms.is_my_guest_record(guest_id));

-- Owners see blocks through owner_calendar_blocks_view.
drop policy availability_blocks_read on availability_blocks;
create policy availability_blocks_read on availability_blocks
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

drop policy housekeeping_read on housekeeping_tasks;
create policy housekeeping_read on housekeeping_tasks
  for select to authenticated
  using (assigned_to = auth.uid() or pms.can_read_unit_financials(unit_id));

-- Management agreements are the commission terms.
drop policy mgmt_agreements_read on management_agreements;
create policy mgmt_agreements_read on management_agreements
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

-- Purchase prices; owners have no screen that needs these rows.
drop policy unit_ownerships_read on unit_ownerships;
create policy unit_ownerships_read on unit_ownerships
  for select to authenticated using (pms.can_read_unit_financials(unit_id));

-- The ledger, statements, invoices and payments: income and payouts.
drop policy ledger_read on ledger_entries;
create policy ledger_read on ledger_entries
  for select to authenticated
  using (pms.is_finance() or (unit_id is not null and pms.staff_scoped_to_unit(unit_id)));

drop policy owner_statements_read on owner_statements;
create policy owner_statements_read on owner_statements
  for select to authenticated using (pms.is_finance() or pms.is_manager());

drop policy invoices_read on invoices;
create policy invoices_read on invoices
  for select to authenticated
  using (
    pms.is_finance()
    or (unit_id is not null and pms.staff_scoped_to_unit(unit_id))
    or (party_kind = 'tenant' and pms.is_my_tenant_record(party_id))
    or (party_kind = 'guest'  and pms.is_my_guest_record(party_id))
  );

drop policy payments_read on payments;
create policy payments_read on payments
  for select to authenticated
  using (pms.is_finance() or (unit_id is not null and pms.staff_scoped_to_unit(unit_id)));

-- Outbound messages to owners include statement and payout notifications.
drop policy messages_read on messages;
create policy messages_read on messages
  for select to authenticated
  using (
    pms.is_staff()
    or (party_kind = 'tenant' and pms.is_my_tenant_record(party_id))
    or (party_kind = 'guest'  and pms.is_my_guest_record(party_id))
  );

-- Company settings hold the default commission rates. Staff only; the few
-- values a portal needs come from portal_settings() below.
drop policy company_settings_read on company_settings;
create policy company_settings_read on company_settings
  for select to authenticated using (pms.is_staff());

-- ---------------------------------------------------------------------------
-- 5. Documents: owners keep their documents, minus anything that states
-- income. Tenancy contracts and Ejari certificates state the rent; invoices,
-- receipts and cheque copies are rent collection records.
-- ---------------------------------------------------------------------------
create or replace function pms.is_income_document(p_kind document_kind)
returns boolean
language sql
immutable
as $$
  select p_kind in (
    'owner_statement', 'invoice', 'receipt', 'cheque_copy',
    'tenancy_contract', 'ejari_certificate'
  );
$$;

comment on function pms.is_income_document(document_kind) is
  'Document kinds that state income or rent. Hidden from owners by documents_read.';

drop policy documents_read on documents;
create policy documents_read on documents
  for select to authenticated
  using (
    case
      when is_sensitive then
        pms.my_role() in ('super_admin','property_manager','finance')
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
      else
        (unit_id is not null and pms.can_read_unit(unit_id))
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
        or (entity_kind = 'company' and pms.is_staff())
        or uploaded_by = auth.uid()
    end
    and (
      pms.is_staff()
      or (is_owner_visible and owner_id in (select pms.my_owner_ids()))
      or (is_tenant_visible and unit_id is not null and (pms.tenants_unit(unit_id) or pms.stays_in_unit(unit_id)))
      or uploaded_by = auth.uid()
    )
    and (pms.my_role() is distinct from 'owner' or not pms.is_income_document(kind))
  );

-- ---------------------------------------------------------------------------
-- 6. The maintenance approval trigger ran as the caller and read the
-- threshold from company_settings, which owners can no longer see. Read it
-- through a definer helper so owner approvals keep working.
-- ---------------------------------------------------------------------------
create or replace function pms.maintenance_threshold()
returns numeric
language sql
stable
security definer
set search_path = public, pms
as $$
  select maintenance_owner_approval_threshold from company_settings where id;
$$;

create or replace function pms.flag_owner_approval()
returns trigger
language plpgsql
as $$
declare
  threshold numeric(12,2) := pms.maintenance_threshold();
begin
  if coalesce(new.quoted_amount_aed, 0) > threshold and new.cost_borne_by = 'owner' then
    new.owner_approval_required := true;
  end if;

  -- Work may not start on an owner-billed job above the threshold until the
  -- owner has actually approved it.
  if new.owner_approval_required
     and new.owner_approved_at is null
     and new.status in ('approved','scheduled','in_progress','completed') then
    raise exception
      'Ticket % requires owner approval before work proceeds (quote AED %, threshold AED %)',
      new.ticket_number, new.quoted_amount_aed, threshold
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- 6b. Audit trigger fix. company_settings is keyed by a boolean (`id = true`),
-- and write_audit() cast every row's id to uuid - so saving company settings
-- failed with "invalid input syntax for type uuid". Non-uuid ids are now
-- recorded as a null entity_id; the full row is still in before/after_data.
-- ---------------------------------------------------------------------------
create or replace function pms.write_audit()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_actor  uuid := auth.uid();
  v_role   app_role;
  v_before jsonb;
  v_after  jsonb;
  v_fields text[];
  v_id     text;
begin
  select role into v_role from profiles where id = v_actor;

  if tg_op = 'DELETE' then
    v_before := to_jsonb(old);
  elsif tg_op = 'INSERT' then
    v_after := to_jsonb(new);
  else
    v_before := to_jsonb(old);
    v_after  := to_jsonb(new);
    select array_agg(key) into v_fields
    from jsonb_each(v_after) a
    where a.value is distinct from v_before -> a.key;

    -- Nothing of substance changed (only updated_at) - skip the noise.
    if v_fields is null or v_fields <@ array['updated_at'] then
      return new;
    end if;
  end if;

  v_id := coalesce(v_after ->> 'id', v_before ->> 'id');

  insert into audit_log (actor_id, actor_role, action, entity_table, entity_id,
                         changed_fields, before_data, after_data)
  values (
    v_actor,
    v_role,
    lower(tg_op)::audit_action,
    tg_table_name,
    case when v_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         then v_id::uuid end,
    v_fields,
    v_before,
    v_after
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Settings a portal user may see. Nothing financial except the
-- maintenance approval threshold, which is a cost the owner signs off.
-- ---------------------------------------------------------------------------
create or replace function portal_settings()
returns table (
  trade_name text,
  phone text,
  email text,
  website text,
  brand_primary_hex text,
  brand_accent_hex text,
  maintenance_owner_approval_threshold numeric,
  show_guest_first_name_to_owners boolean
)
language sql
stable
security definer
set search_path = public, pms
as $$
  select trade_name, phone, email, website, brand_primary_hex, brand_accent_hex,
         maintenance_owner_approval_threshold, show_guest_first_name_to_owners
  from company_settings
  where id and auth.uid() is not null;
$$;

revoke all on function portal_settings() from public, anon;
grant execute on function portal_settings() to authenticated;

-- ---------------------------------------------------------------------------
-- 8. Owner-safe views. Every column is listed explicitly: adding a money
-- column to units or bookings later cannot leak through a `select *`.
-- ---------------------------------------------------------------------------
create or replace view owner_units_view
with (security_barrier = true)
as
select
  u.id,
  u.unit_number,
  u.reference_code,
  u.kind,
  u.floor,
  u.bedrooms,
  u.bathrooms,
  u.size_sqft,
  u.furnishing,
  u.operating_mode,
  u.status,
  u.max_guests,
  u.is_active,
  p.id   as property_id,
  p.name as property_name,
  c.name as community_name,
  hp.permit_number as det_permit_number,
  hp.expires_on    as det_permit_expiry,
  (select um.storage_path from unit_media um
    where um.unit_id = u.id order by um.is_cover desc, um.sort_order limit 1) as cover_path
from units u
join properties p on p.id = u.property_id
left join communities c on c.id = p.community_id
left join lateral (
  select hx.permit_number, hx.expires_on
  from holiday_home_permits hx
  where hx.unit_id = u.id and hx.status = 'active'
  order by hx.expires_on desc limit 1
) hp on true
where pms.owns_unit(u.id);

comment on view owner_units_view is
  'The caller''s own units, with no rent, rate or other money columns. Owner portal only.';

create or replace view owner_bookings_view
with (security_barrier = true)
as
select
  b.id,
  b.unit_id,
  u.unit_number,
  p.name as property_name,
  b.booking_number,
  b.check_in,
  b.check_out,
  b.nights,
  case when b.guest_count_known then b.adults + b.children end as guests,
  case when b.guest_count_known then b.adults end   as adults,
  case when b.guest_count_known then b.children end as children,
  case when b.guest_count_known then b.infants end  as infants,
  b.channel as source,
  b.status,
  case
    when s.show_guest_first_name_to_owners
    then nullif(split_part(btrim(g.full_name), ' ', 1), '')
  end as guest_first_name
from bookings b
join units u on u.id = b.unit_id
join properties p on p.id = u.property_id
left join guests g on g.id = b.guest_id
cross join company_settings s
where s.id
  -- Pending requests and cancellations are internal until confirmed.
  and b.status in ('confirmed','checked_in','checked_out')
  and pms.owns_unit(b.unit_id);

comment on view owner_bookings_view is
  'Confirmed stays on the caller''s own units: dates, nights, guest count and '
  'source only. No rates, totals, payouts or commissions. Owner portal only.';

create or replace view owner_calendar_blocks_view
with (security_barrier = true)
as
select
  ab.id,
  ab.unit_id,
  ab.start_date,
  ab.end_date,
  ab.reason
from availability_blocks ab
-- Booking blocks duplicate owner_bookings_view (and would expose tentative
-- stays); everything else - maintenance, owner stays, holds - is shown.
where ab.reason <> 'booking'
  and pms.owns_unit(ab.unit_id);

comment on view owner_calendar_blocks_view is
  'Non-booking calendar blocks on the caller''s own units. Owner portal only.';

-- Read-only. owner_calendar_blocks_view is a single-table view and would
-- otherwise be auto-updatable - running as its owner, past RLS.
revoke all on owner_units_view, owner_bookings_view, owner_calendar_blocks_view
  from public, anon, authenticated;
grant select on owner_units_view, owner_bookings_view, owner_calendar_blocks_view
  to authenticated;
grant select on owner_units_view, owner_bookings_view, owner_calendar_blocks_view
  to service_role;

-- ####################################################################
-- ## 0015_company_details.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0015 Company details
--
-- The company's legal name, address and contact details, as printed on the
-- owner statement letterhead. Only fields still at their placeholder or empty
-- are filled, so anything already entered in Company settings is kept. They
-- stay editable there afterwards.
-- ============================================================================

alter table company_settings
  alter column legal_name set default 'DRP Real Estate Brokers LLC';

update company_settings set
  legal_name = case when legal_name = 'D|R|P Real Estate'
                    then 'DRP Real Estate Brokers LLC' else legal_name end,
  registered_address = coalesce(nullif(registered_address, ''),
                                'DRP, Golden Mile 09, Palm Jumeirah, Dubai'),
  phone = coalesce(nullif(phone, ''), '+971 4 529 4904'),
  email = coalesce(nullif(email, ''), 'office@dubairapidproperties.com')
where id;

-- ####################################################################
-- ## 0016_performance_indexes.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0016 Indexes for the columns RLS, triggers and pages filter on
--
-- Found by listing every foreign key without a supporting index and keeping
-- the ones something actually reads by. Audit columns (created_by,
-- recorded_by ...) are deliberately left alone: nothing filters on them, and
-- an index there would only slow writes.
--
-- Safe to re-run. The tables are small enough that plain CREATE INDEX (which
-- runs inside the SQL editor's transaction) finishes instantly.
-- ============================================================================

-- Booking triggers: pms.sync_booking_block() deletes by booking_id and
-- pms.schedule_turnover() probes by booking_id on every booking write.
create index if not exists availability_blocks_booking_idx on availability_blocks(booking_id);
create index if not exists housekeeping_booking_idx on housekeeping_tasks(booking_id);
create index if not exists housekeeping_next_booking_idx on housekeeping_tasks(next_booking_id);

-- Calendars and the owner booking view filter a unit's stays by date range.
create index if not exists bookings_unit_checkin_idx on bookings(unit_id, check_in);

-- Columns RLS policies resolve through.
create index if not exists compliance_alerts_unit_idx on compliance_alerts(unit_id);
create index if not exists compliance_alerts_owner_idx on compliance_alerts(owner_id);
create index if not exists payments_unit_idx on payments(unit_id);
create index if not exists service_orders_owner_idx on service_orders(owner_id);
create index if not exists pm_plans_unit_idx on preventive_maintenance_plans(unit_id);
create index if not exists pm_plans_property_idx on preventive_maintenance_plans(property_id);

-- Detail pages: a lease's or booking's money and tickets.
create index if not exists ledger_lease_idx on ledger_entries(lease_id) where lease_id is not null;
create index if not exists ledger_booking_idx on ledger_entries(booking_id) where booking_id is not null;
create index if not exists invoices_lease_idx on invoices(lease_id) where lease_id is not null;
create index if not exists invoices_booking_idx on invoices(booking_id) where booking_id is not null;
create index if not exists payments_lease_idx on payments(lease_id) where lease_id is not null;
create index if not exists payments_booking_idx on payments(booking_id) where booking_id is not null;
create index if not exists maintenance_lease_idx on maintenance_requests(lease_id) where lease_id is not null;
create index if not exists maintenance_booking_idx on maintenance_requests(booking_id) where booking_id is not null;

-- ####################################################################
-- ## 0017_airbnb_calendar_sync.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0017 Airbnb calendar sync (iCal import and export)
--
-- No channel manager: Airbnb publishes each listing's calendar as an iCal
-- feed, and imports ours.
--
-- Import  - every 15 minutes the app fetches each unit's Airbnb feed and hands
--           the parsed events to apply_airbnb_ical(), which reconciles them in
--           one transaction: new reservations are created, moved ones updated,
--           vanished future ones cancelled, and "Not available" periods kept
--           as channel_sync blocks.
-- Export  - each unit has a secret feed token. /api/ical/<token>.ics lists
--           the unit's confirmed non-Airbnb bookings and manual blocks, so
--           Airbnb closes those dates. Airbnb's own bookings are never
--           exported back to it: that would loop.
-- ============================================================================

-- A 64-character hex secret. Built from two v4 UUIDs (122 random bits each,
-- from the server's strong RNG) so it needs no extension-schema function.
create or replace function pms.new_feed_token()
returns text
language sql
volatile
as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
$$;

-- ---------------------------------------------------------------------------
-- Units: the Airbnb feed to read, our feed's secret, and the last sync result.
-- ---------------------------------------------------------------------------
alter table units
  add column if not exists airbnb_ical_url       text,
  add column if not exists ical_export_token     text,
  add column if not exists ical_last_synced_at   timestamptz,
  add column if not exists ical_last_status      text,
  add column if not exists ical_last_error       text,
  add column if not exists ical_last_event_count integer;

update units set ical_export_token = pms.new_feed_token() where ical_export_token is null;
alter table units alter column ical_export_token set default pms.new_feed_token();
alter table units alter column ical_export_token set not null;
create unique index if not exists units_ical_export_token_idx on units(ical_export_token);

alter table units drop constraint if exists units_airbnb_ical_url_https;
alter table units add constraint units_airbnb_ical_url_https
  check (airbnb_ical_url is null or airbnb_ical_url ~ '^https://');
alter table units drop constraint if exists units_ical_last_status_check;
alter table units add constraint units_ical_last_status_check
  check (ical_last_status is null or ical_last_status in ('ok', 'error'));

comment on column units.airbnb_ical_url is
  'Airbnb listing calendar export (Airbnb: Calendar > Availability > Connect calendars > Export).';
comment on column units.ical_export_token is
  'Secret for /api/ical/<token>.ics. Anyone with the URL can see which dates are blocked (never who, never prices). Regenerate if leaked.';

-- ---------------------------------------------------------------------------
-- Bookings and blocks remember which feed event they came from.
-- ---------------------------------------------------------------------------
alter table bookings
  add column if not exists ical_uid                text,
  add column if not exists imported_without_permit boolean not null default false,
  add column if not exists last_seen_in_feed_at    timestamptz;

create unique index if not exists bookings_unit_ical_uid_idx
  on bookings(unit_id, ical_uid) where ical_uid is not null;

comment on column bookings.ical_uid is 'UID of the Airbnb calendar event this booking was imported from.';
comment on column bookings.imported_without_permit is
  'Imported from Airbnb while the unit had no valid DET permit for the check-in date. Needs attention.';

alter table availability_blocks
  add column if not exists ical_uid text;

create unique index if not exists availability_blocks_unit_ical_uid_idx
  on availability_blocks(unit_id, ical_uid) where ical_uid is not null;

-- ---------------------------------------------------------------------------
-- DET permit gate: an Airbnb reservation already exists whether or not we
-- record it, and not recording it would leave the dates open to a double
-- booking. So imports on a unit without a valid permit are accepted and
-- flagged instead of rejected. Everything else keeps the hard gate.
-- ---------------------------------------------------------------------------
create or replace function pms.enforce_permit_before_booking()
returns trigger
language plpgsql
as $$
begin
  if new.status in ('tentative','confirmed','checked_in') then
    if not pms.unit_has_valid_permit(new.unit_id, new.check_in) then
      if new.ical_uid is not null and new.channel = 'airbnb' then
        new.imported_without_permit := true;
        return new;
      end if;
      raise exception
        'Booking for unit % rejected: no valid DET holiday home permit covering check-in date %',
        new.unit_id, new.check_in
        using errcode = 'check_violation';
    end if;
    new.imported_without_permit := false;
    if new.permit_number_at_booking is null then
      new.permit_number_at_booking := pms.unit_permit_number(new.unit_id);
    end if;
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- apply_airbnb_ical: reconcile one unit's feed.
--
-- p_events is a JSON array of {uid, start, end, kind, code}: kind is
-- 'reservation' or 'blocked', dates are ISO, end is exclusive (the check-out
-- day), code is the Airbnb confirmation code when the feed carries one.
-- Pass p_error instead when the feed could not be fetched or parsed.
--
-- SECURITY INVOKER: RLS applies. Staff who may write the unit can run it
-- ("Sync now"); the scheduler runs it with the service key. Anyone else is
-- stopped at the first read of the unit.
--
-- Each event is applied in its own savepoint, so one clash (an Airbnb stay
-- overlapping a direct booking) is reported without blocking the rest.
-- ---------------------------------------------------------------------------
create or replace function apply_airbnb_ical(
  p_unit_id uuid,
  p_events  jsonb,
  p_error   text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pms
as $$
declare
  c_removed  constant text := 'Removed from the Airbnb calendar feed';
  v_today    date := (now() at time zone 'Asia/Dubai')::date;
  v_now      timestamptz := now();
  v_events   jsonb := coalesce(p_events, '[]'::jsonb);
  e          jsonb;
  v_uid      text;
  v_start    date;
  v_end      date;
  v_code     text;
  v_kind     text;
  v_id       uuid;
  v_row      bookings%rowtype;
  v_uids     text[];
  v_live     integer;
  v_errors   text[] := '{}';
  v_created  integer := 0;
  v_updated  integer := 0;
  v_reinstated integer := 0;
  v_cancelled  integer := 0;
  v_blocks   integer := 0;
begin
  if not exists (select 1 from units where id = p_unit_id) then
    raise exception 'Unit % not found', p_unit_id using errcode = 'no_data_found';
  end if;

  if p_error is not null then
    update units
       set ical_last_synced_at = v_now, ical_last_status = 'error', ical_last_error = left(p_error, 500)
     where id = p_unit_id;
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(p_error));
  end if;

  if jsonb_typeof(v_events) <> 'array' then
    raise exception 'p_events must be a JSON array' using errcode = 'invalid_parameter_value';
  end if;

  select coalesce(array_agg(x->>'uid') filter (where x->>'uid' is not null), '{}')
    into v_uids
    from jsonb_array_elements(v_events) x;

  for e in select * from jsonb_array_elements(v_events) loop
    v_uid  := nullif(e->>'uid', '');
    v_code := nullif(e->>'code', '');
    v_kind := coalesce(e->>'kind', 'reservation');
    begin
      v_start := (e->>'start')::date;
      v_end   := (e->>'end')::date;
    exception when others then
      v_start := null;
    end;

    if v_uid is null or v_start is null or v_end is null or v_end <= v_start then
      v_errors := v_errors || format('Skipped an event with missing or invalid dates (%s).', coalesce(v_uid, 'no UID'));
      continue;
    end if;

    begin
      if v_kind = 'blocked' then
        insert into availability_blocks (unit_id, start_date, end_date, reason, source_channel, ical_uid, note)
        values (p_unit_id, v_start, v_end, 'channel_sync', 'airbnb', v_uid, 'Not available on Airbnb')
        on conflict (unit_id, ical_uid) where ical_uid is not null
        do update set start_date = excluded.start_date, end_date = excluded.end_date;
        v_blocks := v_blocks + 1;
        continue;
      end if;

      select * into v_row from bookings where unit_id = p_unit_id and ical_uid = v_uid;

      if not found then
        -- A booking staff typed in by hand before the sync existed: adopt it
        -- rather than create a duplicate that would clash with it.
        select * into v_row
          from bookings
         where unit_id = p_unit_id
           and channel = 'airbnb'
           and ical_uid is null
           and status in ('tentative','confirmed','checked_in')
           and ((v_code is not null and external_booking_id = v_code)
                or (check_in = v_start and check_out = v_end))
         order by coalesce(v_code is not null and external_booking_id = v_code, false) desc
         limit 1;

        if found then
          update bookings
             set ical_uid = v_uid,
                 external_booking_id = coalesce(external_booking_id, v_code),
                 check_in = v_start,
                 check_out = v_end,
                 last_seen_in_feed_at = v_now
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          insert into bookings (unit_id, channel, status, check_in, check_out, adults,
                                guest_count_known, ical_uid, external_booking_id,
                                last_seen_in_feed_at, internal_notes)
          values (p_unit_id, 'airbnb', 'confirmed', v_start, v_end, 1,
                  false, v_uid, v_code, v_now, 'Imported from the Airbnb calendar feed.');
          v_created := v_created + 1;
        end if;
      else
        if v_row.status = 'cancelled' and v_row.cancellation_reason = c_removed then
          -- It came back (Airbnb restored or re-listed it).
          update bookings
             set status = 'confirmed', cancelled_on = null, cancellation_reason = null,
                 check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_reinstated := v_reinstated + 1;
        elsif v_row.check_in <> v_start or v_row.check_out <> v_end then
          update bookings
             set check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          update bookings
             set last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
        end if;
      end if;
    exception
      when exclusion_violation then
        v_errors := v_errors || format(
          'Airbnb stay %s to %s overlaps another booking on this unit and was not imported.',
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'));
      when check_violation or unique_violation then
        v_errors := v_errors || format('Airbnb stay %s to %s: %s',
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'), sqlerrm);
    end;
  end loop;

  -- Cancellations: a synced future stay missing from the feed was cancelled
  -- on Airbnb. Past stays are left alone - Airbnb drops old events from the
  -- feed, which is not a cancellation. Checked-in guests are left alone too.
  select count(*) into v_live
    from bookings
   where unit_id = p_unit_id and ical_uid is not null
     and status in ('tentative','confirmed') and check_out > v_today;

  if jsonb_array_length(v_events) = 0 and v_live >= 2 then
    -- An empty feed with several live stays is far more likely a broken or
    -- replaced link than every guest cancelling at once.
    v_errors := v_errors || format(
      'The Airbnb feed came back empty while %s upcoming stays are synced. Nothing was cancelled - check the calendar link.',
      v_live);
  else
    with gone as (
      update bookings
         set status = 'cancelled', cancelled_on = v_today, cancellation_reason = c_removed
       where unit_id = p_unit_id
         and channel = 'airbnb'
         and ical_uid is not null
         and not (ical_uid = any (v_uids))
         and status in ('tentative','confirmed')
         and check_out > v_today
      returning 1
    )
    select count(*) into v_cancelled from gone;

    delete from availability_blocks
     where unit_id = p_unit_id
       and reason = 'channel_sync'
       and ical_uid is not null
       and not (ical_uid = any (v_uids));
  end if;

  update units
     set ical_last_synced_at   = v_now,
         ical_last_status      = case when cardinality(v_errors) = 0 then 'ok' else 'error' end,
         ical_last_error       = nullif(array_to_string(v_errors[1:5], ' '), ''),
         ical_last_event_count = jsonb_array_length(v_events)
   where id = p_unit_id;

  return jsonb_build_object(
    'ok',         cardinality(v_errors) = 0,
    'created',    v_created,
    'updated',    v_updated,
    'reinstated', v_reinstated,
    'cancelled',  v_cancelled,
    'blocks',     v_blocks,
    'errors',     to_jsonb(v_errors)
  );
end;
$$;

revoke all on function apply_airbnb_ical(uuid, jsonb, text) from public, anon;
grant execute on function apply_airbnb_ical(uuid, jsonb, text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- ical_export_events: what our feed tells Airbnb. Dates and a neutral label
-- only - no guest names, no prices. Called server-side with the service key
-- after the route has matched the token; not reachable by portal users.
-- ---------------------------------------------------------------------------
create or replace function ical_export_events(p_token text)
returns table (uid text, start_date date, end_date date, kind text)
language sql
stable
security invoker
set search_path = public, pms
as $$
  with u as (
    select id from units where ical_export_token = p_token and is_active
  ), horizon as (
    select (now() at time zone 'Asia/Dubai')::date - 1 as from_day
  )
  select 'booking-' || b.id::text, b.check_in, b.check_out, 'booking'
    from bookings b join u on u.id = b.unit_id, horizon h
   where b.channel <> 'airbnb'
     and b.status in ('confirmed','checked_in','checked_out')
     and b.check_out >= h.from_day
  union all
  select 'block-' || ab.id::text, ab.start_date, ab.end_date, ab.reason::text
    from availability_blocks ab join u on u.id = ab.unit_id, horizon h
   where ab.reason in ('maintenance','owner_stay','blocked','housekeeping')
     and ab.end_date >= h.from_day
  order by 2, 1;
$$;

revoke all on function ical_export_events(text) from public, anon, authenticated;
grant execute on function ical_export_events(text) to service_role;

-- ####################################################################
-- ## 0018_booking_notifications.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0018 Booking notifications
--
-- When a stay is booked, moved or cancelled - from the Airbnb feed or by
-- staff - D|R|P and the unit's owners hear about it straight away:
--
--   * in the portal: a row in `notifications` for each recipient's login
--   * by email: a queued row in `messages`, sent by the app (lib/notify)
--
-- Owners are told the unit, the dates, the nights and the channel. Never an
-- amount: owner financial isolation (0014) holds for notifications too. The
-- guest's first name is included only when company settings allow it.
--
-- Not announced: stays already over, and the first read of a newly linked
-- Airbnb calendar, which would otherwise report every existing reservation
-- at once.
-- ============================================================================

create table notifications (
  id           uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references profiles(id) on delete cascade,
  kind         text not null
                 check (kind in ('booking_new', 'booking_changed', 'booking_cancelled')),
  title        text not null,
  body         text not null,
  -- Path inside the recipient's own portal.
  link         text,
  booking_id   uuid references bookings(id) on delete cascade,
  unit_id      uuid references units(id) on delete cascade,
  created_at   timestamptz not null default now(),
  read_at      timestamptz
);
create index notifications_recipient_idx on notifications(recipient_id, created_at desc);
create index notifications_unread_idx on notifications(recipient_id) where read_at is null;

alter table notifications enable row level security;
alter table notifications force row level security;

-- Everyone sees and marks read their own notifications, nothing else. Rows
-- are written only by the trigger below.
create policy notifications_own_read on notifications
  for select to authenticated using (recipient_id = auth.uid());
create policy notifications_own_mark_read on notifications
  for update to authenticated
  using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());

revoke all on notifications from anon;
revoke insert, update, delete on notifications from authenticated;
grant select on notifications to authenticated;
grant update (read_at) on notifications to authenticated;
grant all on notifications to service_role;

-- ---------------------------------------------------------------------------
-- The trigger
-- ---------------------------------------------------------------------------
create or replace function pms.notify_booking_event()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  c_live   constant text[] := array['tentative', 'confirmed', 'checked_in'];
  v_kind   text;
  v_unit   record;
  v_office text;
  v_show_first_name boolean;
  v_first  text;
  v_label  text;
  v_dates  text;
  v_via    text;
  v_title  text;
  v_owner_body text;
  v_staff_body text;
  v_owner_link constant text := '/portal/owner/bookings';
  v_staff_link text := '/bookings/' || new.id;
begin
  if tg_op = 'INSERT' then
    if new.status::text = any (c_live) then
      v_kind := 'booking_new';
    end if;
  elsif new.status::text = any (c_live) and not (old.status::text = any (c_live))
        and old.status <> 'checked_out' then
    -- An enquiry confirmed, or an Airbnb stay back in the feed.
    v_kind := 'booking_new';
  elsif old.status::text = any (c_live) and new.status = 'cancelled' then
    v_kind := 'booking_cancelled';
  elsif new.status::text = any (c_live)
        and (new.check_in <> old.check_in or new.check_out <> old.check_out) then
    v_kind := 'booking_changed';
  end if;

  if v_kind is null then
    return new;
  end if;

  -- History is not news.
  if new.check_out < (now() at time zone 'Asia/Dubai')::date then
    return new;
  end if;

  select u.id, u.unit_number, u.property_id, u.ical_last_synced_at, p.name as property_name
    into v_unit
    from units u
    join properties p on p.id = u.property_id
   where u.id = new.unit_id;

  -- The first sync of a newly linked Airbnb calendar imports every existing
  -- reservation; they are not new bookings.
  if new.ical_uid is not null and v_unit.ical_last_synced_at is null then
    return new;
  end if;

  select email, show_guest_first_name_to_owners
    into v_office, v_show_first_name
    from company_settings
   where id;

  if v_show_first_name and new.guest_id is not null then
    select nullif(split_part(trim(full_name), ' ', 1), '') into v_first
      from guests where id = new.guest_id;
  end if;

  v_label := v_unit.property_name || ' ' || v_unit.unit_number;
  v_dates := to_char(new.check_in, 'DD Mon YYYY') || ' to ' || to_char(new.check_out, 'DD Mon YYYY')
             || ' (' || (new.check_out - new.check_in)
             || case when new.check_out - new.check_in = 1 then ' night)' else ' nights)' end;
  v_via := case new.channel
             when 'airbnb' then 'Airbnb'
             when 'booking_com' then 'Booking.com'
             when 'vrbo' then 'Vrbo'
             when 'direct' then 'a direct booking'
             else initcap(replace(new.channel::text, '_', ' '))
           end;

  v_title := case v_kind
               when 'booking_new' then 'New booking: '
               when 'booking_changed' then 'Booking dates changed: '
               else 'Booking cancelled: '
             end || v_label;

  -- Owners: no booking number, no money.
  v_owner_body := case v_kind
                    when 'booking_cancelled' then 'The stay of ' || v_dates || ' via ' || v_via
                                                  || ' was cancelled. These dates are open again.'
                    when 'booking_changed' then 'The stay via ' || v_via || ' is now ' || v_dates || '.'
                    else v_dates || ', via ' || v_via || '.'
                  end
                  || coalesce(' Guest: ' || v_first || '.', '');

  v_staff_body := new.booking_number || ' - ' || v_dates || ', via ' || v_via || '.'
                  || case when v_kind <> 'booking_cancelled' and new.gross_total_aed = 0
                          then ' Price not entered yet.' else '' end
                  || case when new.imported_without_permit
                          then ' No valid DET permit for these dates.' else '' end;

  -- Portal notifications: super admins, staff assigned to the unit or its
  -- property, and every login linked to an owner of the unit.
  insert into notifications (recipient_id, kind, title, body, link, booking_id, unit_id)
  select p.id, v_kind, v_title, v_staff_body, v_staff_link, new.id, new.unit_id
    from profiles p
   where p.is_active
     and (p.role = 'super_admin'
          or (p.role in ('property_manager', 'agent')
              and (exists (select 1 from staff_unit_assignments a
                            where a.profile_id = p.id and a.unit_id = new.unit_id)
                   or exists (select 1 from staff_property_assignments a
                               where a.profile_id = p.id and a.property_id = v_unit.property_id))));

  insert into notifications (recipient_id, kind, title, body, link, booking_id, unit_id)
  select distinct p.id, v_kind, v_title, v_owner_body, v_owner_link, new.id, new.unit_id
    from unit_ownerships uo
    join owner_users ou on ou.owner_id = uo.owner_id
    join profiles p on p.id = ou.profile_id
   where uo.unit_id = new.unit_id
     and uo.end_date is null
     and p.is_active
     and p.role = 'owner';

  -- Emails, sent by the app: the office address, and each owner with one.
  if v_office is not null and v_office <> '' then
    insert into messages (channel, status, party_kind, to_address, subject, body,
                          unit_id, booking_id, variables)
    values ('email', 'queued', 'staff', v_office, v_title, v_staff_body,
            new.unit_id, new.id, jsonb_build_object('portal', 'admin', 'link', v_staff_link));
  end if;

  insert into messages (channel, status, party_kind, party_id, to_address, subject, body,
                        unit_id, booking_id, variables)
  select distinct on (lower(o.email))
         'email', 'queued', 'owner', o.id, o.email, v_title, v_owner_body,
         new.unit_id, new.id, jsonb_build_object('portal', 'owner', 'link', v_owner_link)
    from unit_ownerships uo
    join owners o on o.id = uo.owner_id
   where uo.unit_id = new.unit_id
     and uo.end_date is null
     and o.is_active
     and o.email is not null
     and o.email <> '';

  return new;
end;
$$;

create trigger bookings_notify
  after insert or update of status, check_in, check_out on bookings
  for each row execute function pms.notify_booking_event();

-- ####################################################################
-- ## 0019_complaints.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0019 Complaints and repairs
--
-- One queue for both: repairs (AC, plumbing ...) and complaints (noise,
-- cleaning, neighbours ...). Staff raise tickets for any unit they manage -
-- including ones a tenant or guest phoned in - and owners raise them for
-- their own units from the owner portal. Both sides follow the status and
-- the conversation.
--
--   * maintenance_requests.kind tells a repair from a complaint, with a few
--     complaint categories added.
--   * Owners raise tickets only through raise_owner_ticket(), which fixes
--     who raised it and its starting status. The direct insert is staff only.
--   * An owner may change nothing on a ticket but their approval decision.
--   * Notes: anyone who can see a ticket may add a note in their own name;
--     only staff write internal notes or change them afterwards.
--   * New tickets and status changes notify staff and the unit's owners in
--     the portal, never the person who made the change.
-- ============================================================================

alter type maintenance_category add value if not exists 'noise';
alter type maintenance_category add value if not exists 'neighbours';
alter type maintenance_category add value if not exists 'security';
alter type maintenance_category add value if not exists 'internet_tv';
alter type maintenance_category add value if not exists 'service';

alter table maintenance_requests
  add column if not exists kind text not null default 'repair'
    check (kind in ('repair', 'complaint'));

comment on column maintenance_requests.kind is
  'repair: something to fix. complaint: a service or behaviour issue (noise, cleaning, neighbours).';

-- ---------------------------------------------------------------------------
-- Who may raise a ticket
-- ---------------------------------------------------------------------------
drop policy if exists maintenance_insert on maintenance_requests;
create policy maintenance_insert on maintenance_requests
  for insert to authenticated
  with check (pms.is_staff() and pms.can_read_unit(unit_id));

create or replace function raise_owner_ticket(
  p_unit_id uuid,
  p_kind text,
  p_category maintenance_category,
  p_priority maintenance_priority,
  p_title text,
  p_description text default null,
  p_access_notes text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_id uuid;
begin
  if pms.my_role() is distinct from 'owner' or not pms.owns_unit(p_unit_id) then
    raise exception 'You can only report issues for your own properties'
      using errcode = 'insufficient_privilege';
  end if;
  if p_kind is null or p_kind not in ('repair', 'complaint') then
    raise exception 'Unknown ticket kind %', p_kind using errcode = 'check_violation';
  end if;
  if length(trim(coalesce(p_title, ''))) = 0 or length(p_title) > 150 then
    raise exception 'A short title is required' using errcode = 'check_violation';
  end if;

  insert into maintenance_requests
    (unit_id, kind, category, priority, title, description, access_notes,
     raised_by, raised_by_kind, status)
  values
    (p_unit_id, p_kind, coalesce(p_category, 'other'), coalesce(p_priority, 'medium'),
     trim(p_title),
     nullif(left(trim(coalesce(p_description, '')), 4000), ''),
     nullif(left(trim(coalesce(p_access_notes, '')), 1000), ''),
     auth.uid(), 'owner', 'submitted')
  returning id into v_id;

  return v_id;
end;
$$;

revoke all on function raise_owner_ticket(uuid, text, maintenance_category, maintenance_priority, text, text, text) from public, anon;
grant execute on function raise_owner_ticket(uuid, text, maintenance_category, maintenance_priority, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- What an owner may change: their approval decision, nothing else
-- ---------------------------------------------------------------------------
create or replace function pms.guard_owner_ticket_update()
returns trigger
language plpgsql
set search_path = public, pms
as $$
declare
  c_decision constant text[] := array[
    'status', 'owner_approved_at', 'owner_approved_by', 'approved_amount_aed',
    'owner_rejected_at', 'owner_rejection_reason', 'updated_at'];
begin
  if pms.is_staff() or auth.uid() is null then
    return new;
  end if;

  if (to_jsonb(new) - c_decision) is distinct from (to_jsonb(old) - c_decision)
     or new.status not in ('approved', 'rejected')
     or (new.owner_approved_by is not null and new.owner_approved_by <> auth.uid()) then
    raise exception 'Owners can only approve or decline a quote'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

drop trigger if exists maintenance_owner_guard on maintenance_requests;
create trigger maintenance_owner_guard
  before update on maintenance_requests
  for each row execute function pms.guard_owner_ticket_update();

-- ---------------------------------------------------------------------------
-- Notes on a ticket
-- ---------------------------------------------------------------------------
drop policy if exists maintenance_updates_write on maintenance_updates;

create policy maintenance_updates_insert on maintenance_updates
  for insert to authenticated
  with check (
    exists (select 1 from maintenance_requests r where r.id = maintenance_updates.request_id)
    and author_id = auth.uid()
    and (pms.is_staff() or (not is_internal and status_from is null and status_to is null))
  );

create policy maintenance_updates_manage on maintenance_updates
  for update to authenticated
  using (pms.is_manager()) with check (pms.is_manager());

create policy maintenance_updates_delete on maintenance_updates
  for delete to authenticated
  using (pms.is_manager());

-- ---------------------------------------------------------------------------
-- Notifications for tickets
-- ---------------------------------------------------------------------------
alter table notifications drop constraint if exists notifications_kind_check;
alter table notifications add constraint notifications_kind_check
  check (kind in ('booking_new', 'booking_changed', 'booking_cancelled',
                  'ticket_new', 'ticket_status'));

alter table notifications
  add column if not exists ticket_id uuid references maintenance_requests(id) on delete cascade;

create or replace function pms.notify_ticket_event()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_kind   text;
  v_unit   record;
  v_what   text;
  v_title  text;
  v_body   text;
  v_actor  uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    v_kind := 'ticket_new';
  elsif new.status is distinct from old.status then
    v_kind := 'ticket_status';
  else
    return new;
  end if;

  select u.id, u.unit_number, u.property_id, p.name as property_name
    into v_unit
    from units u
    join properties p on p.id = u.property_id
   where u.id = new.unit_id;

  v_what := case new.kind when 'complaint' then 'complaint' else 'repair' end;

  if v_kind = 'ticket_new' then
    v_title := 'New ' || v_what || ': ' || v_unit.property_name || ' ' || v_unit.unit_number;
    v_body  := new.ticket_number || ' - ' || new.title
               || case new.raised_by_kind
                    when 'owner' then ' (reported by the owner)'
                    when 'tenant' then ' (reported by the tenant)'
                    when 'guest' then ' (reported by a guest)'
                    else '' end
               || '.';
  else
    v_title := initcap(v_what) || ' ' || new.ticket_number || ': '
               || replace(initcap(replace(new.status::text, '_', ' ')), 'Owner', 'owner');
    v_body  := new.title || ' - ' || v_unit.property_name || ' ' || v_unit.unit_number || '.';
  end if;

  -- Staff: super admins, the assignee, and staff assigned to the unit or
  -- its property.
  insert into notifications (recipient_id, kind, title, body, link, unit_id, ticket_id)
  select p.id, v_kind, v_title, v_body, '/maintenance/' || new.id, new.unit_id, new.id
    from profiles p
   where p.is_active
     and p.id is distinct from v_actor
     and (p.role = 'super_admin'
          or p.id = new.assigned_to
          or (p.role in ('property_manager', 'agent', 'maintenance')
              and (exists (select 1 from staff_unit_assignments a
                            where a.profile_id = p.id and a.unit_id = new.unit_id)
                   or exists (select 1 from staff_property_assignments a
                               where a.profile_id = p.id and a.property_id = v_unit.property_id))));

  -- Owners of the unit.
  insert into notifications (recipient_id, kind, title, body, link, unit_id, ticket_id)
  select distinct p.id, v_kind, v_title, v_body, '/portal/owner/maintenance/' || new.id,
         new.unit_id, new.id
    from unit_ownerships uo
    join owner_users ou on ou.owner_id = uo.owner_id
    join profiles p on p.id = ou.profile_id
   where uo.unit_id = new.unit_id
     and uo.end_date is null
     and p.is_active
     and p.role = 'owner'
     and p.id is distinct from v_actor;

  return new;
end;
$$;

drop trigger if exists maintenance_notify on maintenance_requests;
create trigger maintenance_notify
  after insert or update of status on maintenance_requests
  for each row execute function pms.notify_ticket_event();

-- ####################################################################
-- ## 0020_unit_pricing.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0020 Holiday home pricing for direct bookings
--
-- The prices D|R|P quotes for a direct booking, kept on the unit next to the
-- base nightly rate:
--
--   weekend_rate_aed      Friday and Saturday nights (as Airbnb's weekend
--                         price). Empty: the nightly rate applies.
--   cleaning_fee_aed      Charged once per stay.
--   weekly_discount_pct   Off the nights' total for stays of 7-27 nights.
--   monthly_discount_pct  Off the nights' total for stays of 28+ nights.
--
-- Airbnb stays are priced by Airbnb itself (earnings import); these are only
-- defaults for the New booking form, which staff can still change.
-- ============================================================================

alter table units
  add column if not exists weekend_rate_aed numeric(10,2) check (weekend_rate_aed is null or weekend_rate_aed >= 0),
  add column if not exists cleaning_fee_aed numeric(10,2) check (cleaning_fee_aed is null or cleaning_fee_aed >= 0),
  add column if not exists weekly_discount_pct numeric(5,2)
    check (weekly_discount_pct is null or (weekly_discount_pct >= 0 and weekly_discount_pct < 100)),
  add column if not exists monthly_discount_pct numeric(5,2)
    check (monthly_discount_pct is null or (monthly_discount_pct >= 0 and monthly_discount_pct < 100));

comment on column units.weekend_rate_aed is 'Friday and Saturday nights; null = base nightly rate.';
comment on column units.weekly_discount_pct is 'Percent off the nights for stays of 7 to 27 nights.';
comment on column units.monthly_discount_pct is 'Percent off the nights for stays of 28 nights or more.';

-- ####################################################################
-- ## 0021_airbnb_history.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0021 Past Airbnb stays from the earnings export
--
-- The Airbnb calendar feed only carries current and future stays. Stays that
-- ended before a unit was linked come in from Airbnb's earnings CSV instead,
-- matched to a unit by the listing's name in that file.
--
--   units.airbnb_listing_name  The listing's title as Airbnb's earnings CSV
--                              shows it. Set the first time a file names it.
--
-- A stay recorded after it ended is inserted as checked_out. It needs no
-- turnover clean, so schedule_turnover() now skips that case; every other
-- path is unchanged.
-- ============================================================================

alter table units add column if not exists airbnb_listing_name text;

comment on column units.airbnb_listing_name is
  'The Airbnb listing title as the earnings CSV shows it; matches past stays to this unit.';

create index if not exists units_airbnb_listing_name_idx
  on units (lower(airbnb_listing_name))
  where airbnb_listing_name is not null;

create or replace function pms.schedule_turnover()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_next uuid;
begin
  if new.status not in ('confirmed','checked_out') then
    return new;
  end if;

  -- History: a stay entered after it ended was cleaned long ago.
  if tg_op = 'INSERT' and new.status = 'checked_out' then
    return new;
  end if;

  if exists (select 1 from housekeeping_tasks
             where booking_id = new.id and kind = 'turnover' and status <> 'cancelled') then
    return new;
  end if;

  select id into v_next
  from bookings
  where unit_id = new.unit_id
    and check_in >= new.check_out
    and status in ('tentative','confirmed','checked_in')
    and id <> new.id
  order by check_in
  limit 1;

  insert into housekeeping_tasks (
    unit_id, booking_id, next_booking_id, kind, status, scheduled_start, scheduled_end
  ) values (
    new.unit_id, new.id, v_next, 'turnover', 'pending',
    (new.check_out + time '11:00') at time zone 'Asia/Dubai',
    (new.check_out + time '15:00') at time zone 'Asia/Dubai'
  );

  return new;
end;
$$;

-- ####################################################################
-- ## 0022_owner_emails_and_csv_stays.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0022 Owner booking emails switch; current and upcoming stays
-- from the earnings export
--
-- 1. company_settings.email_owners_about_bookings (default off)
--    The booking trigger (0018) queues an email to each owner for every new,
--    moved or cancelled stay. Until D|R|P has introduced owners to the
--    portal those emails stay unsent: a gate on `messages` drops booking
--    emails addressed to owners while the switch is off. Owners still get
--    the in-portal notification, and the office email is unchanged.
--
-- 2. bookings.import_source
--    'earnings_csv' marks a stay added from Airbnb's earnings export. Like
--    the first read of a newly linked calendar, a bulk import is not news,
--    so adding one announces nothing; later changes to it (a cancellation)
--    are announced as usual.
--
-- 3. Permit gate: an Airbnb stay from the earnings export is recorded even
--    without a permit for its dates and flagged imported_without_permit,
--    exactly as the calendar sync does - Airbnb has already taken the guest,
--    and refusing to record the stay would only hide it.
-- ============================================================================

alter table company_settings
  add column if not exists email_owners_about_bookings boolean not null default false;

comment on column company_settings.email_owners_about_bookings is
  'When false, booking emails to owners are not sent (portal notifications still are).';

alter table bookings
  add column if not exists import_source text
    check (import_source is null or import_source in ('earnings_csv'));

comment on column bookings.import_source is
  'How a stay entered the portal when not by hand or the calendar feed: earnings_csv.';

-- ---------------------------------------------------------------------------
-- 1. Owner booking emails off unless switched on
-- ---------------------------------------------------------------------------
create or replace function pms.gate_owner_booking_email()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
begin
  if not coalesce((select email_owners_about_bookings from company_settings where id), false) then
    return null; -- not queued
  end if;
  return new;
end;
$$;

drop trigger if exists messages_owner_booking_email_gate on messages;
create trigger messages_owner_booking_email_gate
  before insert on messages
  for each row
  when (new.channel = 'email' and new.party_kind = 'owner' and new.booking_id is not null)
  execute function pms.gate_owner_booking_email();

-- ---------------------------------------------------------------------------
-- 2. A stay added from the earnings export is not announced
-- ---------------------------------------------------------------------------
drop trigger if exists bookings_notify on bookings;
drop trigger if exists bookings_notify_insert on bookings;
drop trigger if exists bookings_notify_update on bookings;

create trigger bookings_notify_insert
  after insert on bookings
  for each row
  when (new.import_source is null)
  execute function pms.notify_booking_event();

create trigger bookings_notify_update
  after update of status, check_in, check_out on bookings
  for each row execute function pms.notify_booking_event();

-- ---------------------------------------------------------------------------
-- 3. Permit gate (0017) with the earnings export alongside the calendar feed
-- ---------------------------------------------------------------------------
create or replace function pms.enforce_permit_before_booking()
returns trigger
language plpgsql
as $$
begin
  if new.status in ('tentative','confirmed','checked_in') then
    if not pms.unit_has_valid_permit(new.unit_id, new.check_in) then
      if new.channel = 'airbnb'
         and (new.ical_uid is not null or new.import_source = 'earnings_csv') then
        new.imported_without_permit := true;
        return new;
      end if;
      raise exception
        'Booking for unit % rejected: no valid DET holiday home permit covering check-in date %',
        new.unit_id, new.check_in
        using errcode = 'check_violation';
    end if;
    new.imported_without_permit := false;
    if new.permit_number_at_booking is null then
      new.permit_number_at_booking := pms.unit_permit_number(new.unit_id);
    end if;
  end if;
  return new;
end;
$$;

-- ####################################################################
-- ## 0023_post_booking_income.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0023 Holiday-home stays post their income to the ledger
--
-- Until now only cleared rent cheques reached the ledger, so the Ledger page,
-- owner statements and the finance figures had no holiday-home income at all.
--
-- post_completed_bookings() brings the ledger in line with the bookings:
--
--   * a stay that has ended (check-out today or earlier), is not cancelled
--     and has a payout gets one income line under INC-BOOKING, dated its
--     check-out day, for the payout (Airbnb's "Amount": what D|R|P receives,
--     after the channel's fee and the Tourism Dirham). No VAT line.
--   * if the payout changes later (a price entered by hand, then the earnings
--     CSV), the line follows it - until the line is in an owner statement,
--     which never changes after it is issued.
--   * a stay cancelled or unpriced after posting loses its line, on the same
--     condition.
--
-- Status is not used to decide "ended": an Airbnb stay stays "confirmed"
-- unless someone checks the guest out, but it has ended all the same. So the
-- function runs on a schedule rather than from a trigger - the app calls it
-- when the ledger or a statement is opened, and the calendar cron calls it
-- too. Running it twice changes nothing.
-- ============================================================================

create or replace function post_completed_bookings()
returns integer
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_today date := (now() at time zone 'Asia/Dubai')::date;
  v_cat   uuid := (select id from gl_categories where code = 'INC-BOOKING');
  v_posted integer;
begin
  -- Staff, or the service role (cron). Owners and tenants never post.
  if auth.uid() is not null and not pms.is_staff() then
    return 0;
  end if;

  -- Lines whose stay was deleted, not yet in a statement.
  delete from ledger_entries le
   where le.source_table = 'bookings'
     and le.statement_id is null
     and not exists (select 1 from bookings b where b.id = le.source_id);

  -- Lines whose stay no longer qualifies, not yet in a statement.
  delete from ledger_entries le
   using bookings b
   where le.source_table = 'bookings'
     and le.source_id = b.id
     and le.statement_id is null
     and (b.status not in ('confirmed','checked_in','checked_out')
          or b.check_out > v_today
          or coalesce(b.payout_expected_aed, 0) <= 0);

  -- Lines whose stay's payout or dates moved, not yet in a statement.
  update ledger_entries le
     set amount_aed = b.payout_expected_aed,
         entry_date = b.check_out,
         unit_id    = b.unit_id
    from bookings b
   where le.source_table = 'bookings'
     and le.source_id = b.id
     and le.statement_id is null
     and (le.amount_aed <> b.payout_expected_aed
          or le.entry_date <> b.check_out
          or le.unit_id is distinct from b.unit_id);

  -- New lines for ended, priced stays.
  insert into ledger_entries (
    entry_date, unit_id, owner_id, category_id, direction, description,
    amount_aed, vat_applicable, source_table, source_id, booking_id
  )
  select b.check_out,
         b.unit_id,
         (select uo.owner_id from unit_ownerships uo
           where uo.unit_id = b.unit_id and uo.end_date is null
           order by uo.is_primary_contact desc, uo.ownership_pct desc
           limit 1),
         v_cat,
         'income',
         'Stay ' || b.booking_number
           || coalesce(' (' || initcap(b.channel::text) || ' ' || b.external_booking_id || ')', '')
           || ', ' || to_char(b.check_in, 'DD Mon') || ' - ' || to_char(b.check_out, 'DD Mon YYYY'),
         b.payout_expected_aed,
         false,
         'bookings',
         b.id,
         b.id
    from bookings b
   where b.status in ('confirmed','checked_in','checked_out')
     and b.check_out <= v_today
     and coalesce(b.payout_expected_aed, 0) > 0
     and not exists (select 1 from ledger_entries le
                      where le.source_table = 'bookings' and le.source_id = b.id);
  get diagnostics v_posted = row_count;

  return v_posted;
end;
$$;

comment on function post_completed_bookings() is
  'Posts the payout of every ended, priced stay to the ledger (INC-BOOKING) and keeps unissued lines in step. Idempotent.';

revoke all on function post_completed_bookings() from public, anon;
grant execute on function post_completed_bookings() to authenticated, service_role;

create unique index if not exists ledger_entries_booking_source_idx
  on ledger_entries (source_id)
  where source_table = 'bookings';

-- ####################################################################
-- ## 0024_holiday_home_unit_status.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0024 Holiday-home units read "Listed (short-term)", not "Vacant"
--
-- A unit's status only ever changed with leases (0011 sync_unit_status), so a
-- unit added as a holiday home - every Airbnb listing - stayed "vacant" for
-- good, and the Properties page counted it as empty.
--
-- From now on the status follows the operating mode whenever nothing more
-- specific applies: a short-term (or both) unit that is not leased, under
-- maintenance, owner-occupied or off the market is "listed_short_term"; a
-- unit taken off short-term letting goes back to "vacant". Whether a guest is
-- in tonight is a matter of bookings and is shown from them, not stored.
-- ============================================================================

create or replace function pms.holiday_home_status()
returns trigger
language plpgsql
as $$
begin
  if new.status = 'vacant' and new.operating_mode in ('short_term','both') then
    new.status := 'listed_short_term';
  elsif new.status = 'listed_short_term' and new.operating_mode not in ('short_term','both') then
    new.status := 'vacant';
  end if;
  return new;
end;
$$;

drop trigger if exists units_holiday_home_status on units;
create trigger units_holiday_home_status
  before insert or update of operating_mode, status on units
  for each row execute function pms.holiday_home_status();

-- Units already in the portal.
update units
   set status = 'listed_short_term'
 where status = 'vacant'
   and operating_mode in ('short_term','both');

-- ####################################################################
-- ## 0025_booking_com.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0025 Booking.com alongside Airbnb
--
-- Booking.com publishes each property's availability as an iCal feed too
-- (extranet: Rates & Availability > Sync calendars > Export). Its events carry
-- dates only - no reservation number, no guest - and the reservation details
-- come from the extranet's reservations export, imported like Airbnb's
-- earnings file.
--
--   units.booking_ical_url (+ its own last-sync columns)
--   units.booking_listing_name  the property's name in Booking.com's export
--
-- apply_channel_ical(unit, channel, events, error) is apply_airbnb_ical made
-- per channel: each channel's feed creates, moves and cancels only its own
-- stays and blocks, and keeps its own sync status. apply_airbnb_ical stays as
-- a wrapper, so existing callers are unchanged.
--
-- The first read of a newly linked feed is still not announced; that is now
-- marked on the booking (import_source = 'feed_first_read') rather than
-- inferred from the Airbnb sync time, so it works for each channel.
-- ============================================================================

alter table units
  add column if not exists booking_ical_url              text,
  add column if not exists booking_ical_last_synced_at   timestamptz,
  add column if not exists booking_ical_last_status      text,
  add column if not exists booking_ical_last_error       text,
  add column if not exists booking_ical_last_event_count integer,
  add column if not exists booking_listing_name          text;

alter table units drop constraint if exists units_booking_ical_url_https;
alter table units add constraint units_booking_ical_url_https
  check (booking_ical_url is null or booking_ical_url ~ '^https://');
alter table units drop constraint if exists units_booking_ical_last_status_check;
alter table units add constraint units_booking_ical_last_status_check
  check (booking_ical_last_status is null or booking_ical_last_status in ('ok', 'error'));

comment on column units.booking_ical_url is
  'Booking.com calendar export (extranet: Rates & Availability > Sync calendars > Export).';
comment on column units.booking_listing_name is
  'The property name as Booking.com''s reservations export shows it; matches its reservations to this unit.';

create index if not exists units_booking_listing_name_idx
  on units (lower(booking_listing_name))
  where booking_listing_name is not null;

alter table bookings drop constraint if exists bookings_import_source_check;
alter table bookings add constraint bookings_import_source_check
  check (import_source is null or import_source in ('earnings_csv', 'feed_first_read'));

-- ---------------------------------------------------------------------------
-- Per-channel feed reconciliation
-- ---------------------------------------------------------------------------
create or replace function apply_channel_ical(
  p_unit_id uuid,
  p_channel sales_channel,
  p_events  jsonb,
  p_error   text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pms
as $$
declare
  v_name     text := case p_channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com' end;
  c_removed  text := 'Removed from the ' || case p_channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com' end || ' calendar feed';
  v_first    boolean;
  v_today    date := (now() at time zone 'Asia/Dubai')::date;
  v_now      timestamptz := now();
  v_events   jsonb := coalesce(p_events, '[]'::jsonb);
  e          jsonb;
  v_uid      text;
  v_start    date;
  v_end      date;
  v_code     text;
  v_kind     text;
  v_id       uuid;
  v_row      bookings%rowtype;
  v_uids     text[];
  v_live     integer;
  v_errors   text[] := '{}';
  v_created  integer := 0;
  v_updated  integer := 0;
  v_reinstated integer := 0;
  v_cancelled  integer := 0;
  v_blocks   integer := 0;
begin
  if p_channel not in ('airbnb','booking_com') then
    raise exception 'No calendar feed for channel %', p_channel using errcode = 'invalid_parameter_value';
  end if;

  select case p_channel when 'airbnb' then ical_last_synced_at is null
                        else booking_ical_last_synced_at is null end
    into v_first
    from units where id = p_unit_id;
  if not found then
    raise exception 'Unit % not found', p_unit_id using errcode = 'no_data_found';
  end if;

  if p_error is not null then
    if p_channel = 'airbnb' then
      update units
         set ical_last_synced_at = v_now, ical_last_status = 'error', ical_last_error = left(p_error, 500)
       where id = p_unit_id;
    else
      update units
         set booking_ical_last_synced_at = v_now, booking_ical_last_status = 'error',
             booking_ical_last_error = left(p_error, 500)
       where id = p_unit_id;
    end if;
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(p_error));
  end if;

  if jsonb_typeof(v_events) <> 'array' then
    raise exception 'p_events must be a JSON array' using errcode = 'invalid_parameter_value';
  end if;

  select coalesce(array_agg(x->>'uid') filter (where x->>'uid' is not null), '{}')
    into v_uids
    from jsonb_array_elements(v_events) x;

  for e in select * from jsonb_array_elements(v_events) loop
    v_uid  := nullif(e->>'uid', '');
    v_code := nullif(e->>'code', '');
    v_kind := coalesce(e->>'kind', 'reservation');
    begin
      v_start := (e->>'start')::date;
      v_end   := (e->>'end')::date;
    exception when others then
      v_start := null;
    end;

    if v_uid is null or v_start is null or v_end is null or v_end <= v_start then
      v_errors := v_errors || format('Skipped an event with missing or invalid dates (%s).', coalesce(v_uid, 'no UID'));
      continue;
    end if;

    begin
      if v_kind = 'blocked' then
        insert into availability_blocks (unit_id, start_date, end_date, reason, source_channel, ical_uid, note)
        values (p_unit_id, v_start, v_end, 'channel_sync', p_channel, v_uid, 'Not available on ' || v_name)
        on conflict (unit_id, ical_uid) where ical_uid is not null
        do update set start_date = excluded.start_date, end_date = excluded.end_date;
        v_blocks := v_blocks + 1;
        continue;
      end if;

      select * into v_row from bookings where unit_id = p_unit_id and ical_uid = v_uid;

      if not found then
        -- A booking staff typed in by hand before the sync existed: adopt it
        -- rather than create a duplicate that would clash with it.
        select * into v_row
          from bookings
         where unit_id = p_unit_id
           and channel = p_channel
           and ical_uid is null
           and status in ('tentative','confirmed','checked_in')
           and ((v_code is not null and external_booking_id = v_code)
                or (check_in = v_start and check_out = v_end))
         order by coalesce(v_code is not null and external_booking_id = v_code, false) desc
         limit 1;

        if found then
          update bookings
             set ical_uid = v_uid,
                 external_booking_id = coalesce(external_booking_id, v_code),
                 check_in = v_start,
                 check_out = v_end,
                 last_seen_in_feed_at = v_now
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          -- The first read of a newly linked feed brings every existing
          -- reservation: recorded, not announced (0018 did this for Airbnb by
          -- its own sync time; each channel now has its own).
          insert into bookings (unit_id, channel, status, check_in, check_out, adults,
                                guest_count_known, ical_uid, external_booking_id,
                                last_seen_in_feed_at, internal_notes, import_source)
          values (p_unit_id, p_channel, 'confirmed', v_start, v_end, 1,
                  false, v_uid, v_code, v_now, 'Imported from the ' || v_name || ' calendar feed.',
                  case when v_first then 'feed_first_read' end);
          v_created := v_created + 1;
        end if;
      else
        if v_row.status = 'cancelled' and v_row.cancellation_reason = c_removed then
          -- It came back (Airbnb restored or re-listed it).
          update bookings
             set status = 'confirmed', cancelled_on = null, cancellation_reason = null,
                 check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_reinstated := v_reinstated + 1;
        elsif v_row.check_in <> v_start or v_row.check_out <> v_end then
          update bookings
             set check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          update bookings
             set last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
        end if;
      end if;
    exception
      when exclusion_violation then
        v_errors := v_errors || format(
          '%s stay %s to %s overlaps another booking on this unit and was not imported.', v_name,
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'));
      when check_violation or unique_violation then
        v_errors := v_errors || format('%s stay %s to %s: %s', v_name,
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'), sqlerrm);
    end;
  end loop;

  -- Cancellations: a synced future stay missing from the feed was cancelled
  -- on Airbnb. Past stays are left alone - Airbnb drops old events from the
  -- feed, which is not a cancellation. Checked-in guests are left alone too.
  select count(*) into v_live
    from bookings
   where unit_id = p_unit_id and channel = p_channel and ical_uid is not null
     and status in ('tentative','confirmed') and check_out > v_today;

  if jsonb_array_length(v_events) = 0 and v_live >= 2 then
    -- An empty feed with several live stays is far more likely a broken or
    -- replaced link than every guest cancelling at once.
    v_errors := v_errors || format(
      'The %s feed came back empty while %s upcoming stays are synced. Nothing was cancelled - check the calendar link.',
      v_name, v_live);
  else
    with gone as (
      update bookings
         set status = 'cancelled', cancelled_on = v_today, cancellation_reason = c_removed
       where unit_id = p_unit_id
         and channel = p_channel
         and ical_uid is not null
         and not (ical_uid = any (v_uids))
         and status in ('tentative','confirmed')
         and check_out > v_today
      returning 1
    )
    select count(*) into v_cancelled from gone;

    delete from availability_blocks
     where unit_id = p_unit_id
       and reason = 'channel_sync'
       and source_channel = p_channel
       and ical_uid is not null
       and not (ical_uid = any (v_uids));
  end if;

  if p_channel = 'airbnb' then
    update units
       set ical_last_synced_at   = v_now,
           ical_last_status      = case when cardinality(v_errors) = 0 then 'ok' else 'error' end,
           ical_last_error       = nullif(array_to_string(v_errors[1:5], ' '), ''),
           ical_last_event_count = jsonb_array_length(v_events)
     where id = p_unit_id;
  else
    update units
       set booking_ical_last_synced_at   = v_now,
           booking_ical_last_status      = case when cardinality(v_errors) = 0 then 'ok' else 'error' end,
           booking_ical_last_error       = nullif(array_to_string(v_errors[1:5], ' '), ''),
           booking_ical_last_event_count = jsonb_array_length(v_events)
     where id = p_unit_id;
  end if;

  return jsonb_build_object(
    'ok',         cardinality(v_errors) = 0,
    'created',    v_created,
    'updated',    v_updated,
    'reinstated', v_reinstated,
    'cancelled',  v_cancelled,
    'blocks',     v_blocks,
    'errors',     to_jsonb(v_errors)
  );
end;
$$;

revoke all on function apply_channel_ical(uuid, sales_channel, jsonb, text) from public, anon;
grant execute on function apply_channel_ical(uuid, sales_channel, jsonb, text) to authenticated, service_role;

create or replace function apply_airbnb_ical(
  p_unit_id uuid,
  p_events  jsonb,
  p_error   text default null
)
returns jsonb
language sql
security invoker
set search_path = public, pms
as $$
  select apply_channel_ical(p_unit_id, 'airbnb', p_events, p_error);
$$;

-- ---------------------------------------------------------------------------
-- Permit gate: Booking.com stays from its feed or export are recorded and
-- flagged like Airbnb's, not refused.
-- ---------------------------------------------------------------------------
create or replace function pms.enforce_permit_before_booking()
returns trigger
language plpgsql
as $$
begin
  if new.status in ('tentative','confirmed','checked_in') then
    if not pms.unit_has_valid_permit(new.unit_id, new.check_in) then
      if new.channel in ('airbnb','booking_com')
         and (new.ical_uid is not null or new.import_source = 'earnings_csv') then
        new.imported_without_permit := true;
        return new;
      end if;
      raise exception
        'Booking for unit % rejected: no valid DET holiday home permit covering check-in date %',
        new.unit_id, new.check_in
        using errcode = 'check_violation';
    end if;
    new.imported_without_permit := false;
    if new.permit_number_at_booking is null then
      new.permit_number_at_booking := pms.unit_permit_number(new.unit_id);
    end if;
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Ledger lines name the channel properly ("Booking.com", not "Booking_Com").
-- ---------------------------------------------------------------------------
create or replace function post_completed_bookings()
returns integer
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_today date := (now() at time zone 'Asia/Dubai')::date;
  v_cat   uuid := (select id from gl_categories where code = 'INC-BOOKING');
  v_posted integer;
begin
  -- Staff, or the service role (cron). Owners and tenants never post.
  if auth.uid() is not null and not pms.is_staff() then
    return 0;
  end if;

  -- Lines whose stay was deleted, not yet in a statement.
  delete from ledger_entries le
   where le.source_table = 'bookings'
     and le.statement_id is null
     and not exists (select 1 from bookings b where b.id = le.source_id);

  -- Lines whose stay no longer qualifies, not yet in a statement.
  delete from ledger_entries le
   using bookings b
   where le.source_table = 'bookings'
     and le.source_id = b.id
     and le.statement_id is null
     and (b.status not in ('confirmed','checked_in','checked_out')
          or b.check_out > v_today
          or coalesce(b.payout_expected_aed, 0) <= 0);

  -- Lines whose stay's payout or dates moved, not yet in a statement.
  update ledger_entries le
     set amount_aed = b.payout_expected_aed,
         entry_date = b.check_out,
         unit_id    = b.unit_id
    from bookings b
   where le.source_table = 'bookings'
     and le.source_id = b.id
     and le.statement_id is null
     and (le.amount_aed <> b.payout_expected_aed
          or le.entry_date <> b.check_out
          or le.unit_id is distinct from b.unit_id);

  -- New lines for ended, priced stays.
  insert into ledger_entries (
    entry_date, unit_id, owner_id, category_id, direction, description,
    amount_aed, vat_applicable, source_table, source_id, booking_id
  )
  select b.check_out,
         b.unit_id,
         (select uo.owner_id from unit_ownerships uo
           where uo.unit_id = b.unit_id and uo.end_date is null
           order by uo.is_primary_contact desc, uo.ownership_pct desc
           limit 1),
         v_cat,
         'income',
         'Stay ' || b.booking_number
           || coalesce(' (' || case b.channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com' else initcap(replace(b.channel::text, '_', ' ')) end || ' ' || b.external_booking_id || ')', '')
           || ', ' || to_char(b.check_in, 'DD Mon') || ' - ' || to_char(b.check_out, 'DD Mon YYYY'),
         b.payout_expected_aed,
         false,
         'bookings',
         b.id,
         b.id
    from bookings b
   where b.status in ('confirmed','checked_in','checked_out')
     and b.check_out <= v_today
     and coalesce(b.payout_expected_aed, 0) > 0
     and not exists (select 1 from ledger_entries le
                      where le.source_table = 'bookings' and le.source_id = b.id);
  get diagnostics v_posted = row_count;

  return v_posted;
end;
$$;


-- ---------------------------------------------------------------------------
-- Notifications: the "first read of a new Airbnb link" rule (0018) looked at
-- the Airbnb sync time for any feed stay. Now Airbnb only.
-- ---------------------------------------------------------------------------
create or replace function pms.notify_booking_event()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  c_live   constant text[] := array['tentative', 'confirmed', 'checked_in'];
  v_kind   text;
  v_unit   record;
  v_office text;
  v_show_first_name boolean;
  v_first  text;
  v_label  text;
  v_dates  text;
  v_via    text;
  v_title  text;
  v_owner_body text;
  v_staff_body text;
  v_owner_link constant text := '/portal/owner/bookings';
  v_staff_link text := '/bookings/' || new.id;
begin
  if tg_op = 'INSERT' then
    if new.status::text = any (c_live) then
      v_kind := 'booking_new';
    end if;
  elsif new.status::text = any (c_live) and not (old.status::text = any (c_live))
        and old.status <> 'checked_out' then
    -- An enquiry confirmed, or an Airbnb stay back in the feed.
    v_kind := 'booking_new';
  elsif old.status::text = any (c_live) and new.status = 'cancelled' then
    v_kind := 'booking_cancelled';
  elsif new.status::text = any (c_live)
        and (new.check_in <> old.check_in or new.check_out <> old.check_out) then
    v_kind := 'booking_changed';
  end if;

  if v_kind is null then
    return new;
  end if;

  -- History is not news.
  if new.check_out < (now() at time zone 'Asia/Dubai')::date then
    return new;
  end if;

  select u.id, u.unit_number, u.property_id, u.ical_last_synced_at, p.name as property_name
    into v_unit
    from units u
    join properties p on p.id = u.property_id
   where u.id = new.unit_id;

  -- The first sync of a newly linked Airbnb calendar imports every existing
  -- reservation; they are not new bookings.
  -- (Airbnb only: every channel's first read is now marked on the booking,
  -- import_source = 'feed_first_read', and the insert trigger skips those.
  -- Checking Airbnb's sync time for a Booking.com stay would silence a unit
  -- that has no Airbnb link for good.)
  if new.ical_uid is not null and new.channel = 'airbnb' and v_unit.ical_last_synced_at is null then
    return new;
  end if;

  select email, show_guest_first_name_to_owners
    into v_office, v_show_first_name
    from company_settings
   where id;

  if v_show_first_name and new.guest_id is not null then
    select nullif(split_part(trim(full_name), ' ', 1), '') into v_first
      from guests where id = new.guest_id;
  end if;

  v_label := v_unit.property_name || ' ' || v_unit.unit_number;
  v_dates := to_char(new.check_in, 'DD Mon YYYY') || ' to ' || to_char(new.check_out, 'DD Mon YYYY')
             || ' (' || (new.check_out - new.check_in)
             || case when new.check_out - new.check_in = 1 then ' night)' else ' nights)' end;
  v_via := case new.channel
             when 'airbnb' then 'Airbnb'
             when 'booking_com' then 'Booking.com'
             when 'vrbo' then 'Vrbo'
             when 'direct' then 'a direct booking'
             else initcap(replace(new.channel::text, '_', ' '))
           end;

  v_title := case v_kind
               when 'booking_new' then 'New booking: '
               when 'booking_changed' then 'Booking dates changed: '
               else 'Booking cancelled: '
             end || v_label;

  -- Owners: no booking number, no money.
  v_owner_body := case v_kind
                    when 'booking_cancelled' then 'The stay of ' || v_dates || ' via ' || v_via
                                                  || ' was cancelled. These dates are open again.'
                    when 'booking_changed' then 'The stay via ' || v_via || ' is now ' || v_dates || '.'
                    else v_dates || ', via ' || v_via || '.'
                  end
                  || coalesce(' Guest: ' || v_first || '.', '');

  v_staff_body := new.booking_number || ' - ' || v_dates || ', via ' || v_via || '.'
                  || case when v_kind <> 'booking_cancelled' and new.gross_total_aed = 0
                          then ' Price not entered yet.' else '' end
                  || case when new.imported_without_permit
                          then ' No valid DET permit for these dates.' else '' end;

  -- Portal notifications: super admins, staff assigned to the unit or its
  -- property, and every login linked to an owner of the unit.
  insert into notifications (recipient_id, kind, title, body, link, booking_id, unit_id)
  select p.id, v_kind, v_title, v_staff_body, v_staff_link, new.id, new.unit_id
    from profiles p
   where p.is_active
     and (p.role = 'super_admin'
          or (p.role in ('property_manager', 'agent')
              and (exists (select 1 from staff_unit_assignments a
                            where a.profile_id = p.id and a.unit_id = new.unit_id)
                   or exists (select 1 from staff_property_assignments a
                               where a.profile_id = p.id and a.property_id = v_unit.property_id))));

  insert into notifications (recipient_id, kind, title, body, link, booking_id, unit_id)
  select distinct p.id, v_kind, v_title, v_owner_body, v_owner_link, new.id, new.unit_id
    from unit_ownerships uo
    join owner_users ou on ou.owner_id = uo.owner_id
    join profiles p on p.id = ou.profile_id
   where uo.unit_id = new.unit_id
     and uo.end_date is null
     and p.is_active
     and p.role = 'owner';

  -- Emails, sent by the app: the office address, and each owner with one.
  if v_office is not null and v_office <> '' then
    insert into messages (channel, status, party_kind, to_address, subject, body,
                          unit_id, booking_id, variables)
    values ('email', 'queued', 'staff', v_office, v_title, v_staff_body,
            new.unit_id, new.id, jsonb_build_object('portal', 'admin', 'link', v_staff_link));
  end if;

  insert into messages (channel, status, party_kind, party_id, to_address, subject, body,
                        unit_id, booking_id, variables)
  select distinct on (lower(o.email))
         'email', 'queued', 'owner', o.id, o.email, v_title, v_owner_body,
         new.unit_id, new.id, jsonb_build_object('portal', 'owner', 'link', v_owner_link)
    from unit_ownerships uo
    join owners o on o.id = uo.owner_id
   where uo.unit_id = new.unit_id
     and uo.end_date is null
     and o.is_active
     and o.email is not null
     and o.email <> '';

  return new;
end;
$$;


-- ####################################################################
-- ## 0026_feed_uid_changes.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0026 Calendar feeds: follow a stay whose UID changes; name clashes
--
-- Booking.com issues new UIDs for the same reservation from one export to
-- the next. apply_channel_ical (0025) only adopted bookings with no UID yet,
-- so the second read of a Booking.com feed took a known stay for a new one,
-- and the database refused it as overlapping itself ("overlaps another
-- booking on this unit").
--
-- Now a feed event whose UID is unknown also adopts the same channel's live
-- stay on the same dates (or with the same confirmation code) when that
-- stay's UID is no longer in the feed. And a real clash names the booking in
-- the way - number, channel, reference and dates - instead of "another
-- booking".
-- ============================================================================

create or replace function apply_channel_ical(
  p_unit_id uuid,
  p_channel sales_channel,
  p_events  jsonb,
  p_error   text default null
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pms
as $$
declare
  v_name     text := case p_channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com' end;
  c_removed  text := 'Removed from the ' || case p_channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com' end || ' calendar feed';
  v_first    boolean;
  v_clash    text;
  v_today    date := (now() at time zone 'Asia/Dubai')::date;
  v_now      timestamptz := now();
  v_events   jsonb := coalesce(p_events, '[]'::jsonb);
  e          jsonb;
  v_uid      text;
  v_start    date;
  v_end      date;
  v_code     text;
  v_kind     text;
  v_id       uuid;
  v_row      bookings%rowtype;
  v_uids     text[];
  v_live     integer;
  v_errors   text[] := '{}';
  v_created  integer := 0;
  v_updated  integer := 0;
  v_reinstated integer := 0;
  v_cancelled  integer := 0;
  v_blocks   integer := 0;
begin
  if p_channel not in ('airbnb','booking_com') then
    raise exception 'No calendar feed for channel %', p_channel using errcode = 'invalid_parameter_value';
  end if;

  select case p_channel when 'airbnb' then ical_last_synced_at is null
                        else booking_ical_last_synced_at is null end
    into v_first
    from units where id = p_unit_id;
  if not found then
    raise exception 'Unit % not found', p_unit_id using errcode = 'no_data_found';
  end if;

  if p_error is not null then
    if p_channel = 'airbnb' then
      update units
         set ical_last_synced_at = v_now, ical_last_status = 'error', ical_last_error = left(p_error, 500)
       where id = p_unit_id;
    else
      update units
         set booking_ical_last_synced_at = v_now, booking_ical_last_status = 'error',
             booking_ical_last_error = left(p_error, 500)
       where id = p_unit_id;
    end if;
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(p_error));
  end if;

  if jsonb_typeof(v_events) <> 'array' then
    raise exception 'p_events must be a JSON array' using errcode = 'invalid_parameter_value';
  end if;

  select coalesce(array_agg(x->>'uid') filter (where x->>'uid' is not null), '{}')
    into v_uids
    from jsonb_array_elements(v_events) x;

  for e in select * from jsonb_array_elements(v_events) loop
    v_uid  := nullif(e->>'uid', '');
    v_code := nullif(e->>'code', '');
    v_kind := coalesce(e->>'kind', 'reservation');
    begin
      v_start := (e->>'start')::date;
      v_end   := (e->>'end')::date;
    exception when others then
      v_start := null;
    end;

    if v_uid is null or v_start is null or v_end is null or v_end <= v_start then
      v_errors := v_errors || format('Skipped an event with missing or invalid dates (%s).', coalesce(v_uid, 'no UID'));
      continue;
    end if;

    begin
      if v_kind = 'blocked' then
        insert into availability_blocks (unit_id, start_date, end_date, reason, source_channel, ical_uid, note)
        values (p_unit_id, v_start, v_end, 'channel_sync', p_channel, v_uid, 'Not available on ' || v_name)
        on conflict (unit_id, ical_uid) where ical_uid is not null
        do update set start_date = excluded.start_date, end_date = excluded.end_date;
        v_blocks := v_blocks + 1;
        continue;
      end if;

      select * into v_row from bookings where unit_id = p_unit_id and ical_uid = v_uid;

      if not found then
        -- The same stay under another UID: one typed in by hand or imported
        -- from the channel's export before the sync (no UID yet), or one an
        -- earlier read of this feed brought in under a UID the feed no longer
        -- uses - Booking.com issues new UIDs on each export. Adopt it rather
        -- than create a duplicate that would clash with it. A booking another
        -- event in this same feed still owns is never taken.
        select * into v_row
          from bookings
         where unit_id = p_unit_id
           and channel = p_channel
           and (ical_uid is null or not (ical_uid = any (v_uids)))
           and status in ('tentative','confirmed','checked_in')
           and ((v_code is not null and external_booking_id = v_code)
                or (check_in = v_start and check_out = v_end))
         order by coalesce(v_code is not null and external_booking_id = v_code, false) desc,
                  (ical_uid is null) desc
         limit 1;

        if found then
          update bookings
             set ical_uid = v_uid,
                 external_booking_id = coalesce(external_booking_id, v_code),
                 check_in = v_start,
                 check_out = v_end,
                 last_seen_in_feed_at = v_now
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          -- The first read of a newly linked feed brings every existing
          -- reservation: recorded, not announced (0018 did this for Airbnb by
          -- its own sync time; each channel now has its own).
          insert into bookings (unit_id, channel, status, check_in, check_out, adults,
                                guest_count_known, ical_uid, external_booking_id,
                                last_seen_in_feed_at, internal_notes, import_source)
          values (p_unit_id, p_channel, 'confirmed', v_start, v_end, 1,
                  false, v_uid, v_code, v_now, 'Imported from the ' || v_name || ' calendar feed.',
                  case when v_first then 'feed_first_read' end);
          v_created := v_created + 1;
        end if;
      else
        if v_row.status = 'cancelled' and v_row.cancellation_reason = c_removed then
          -- It came back (Airbnb restored or re-listed it).
          update bookings
             set status = 'confirmed', cancelled_on = null, cancellation_reason = null,
                 check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_reinstated := v_reinstated + 1;
        elsif v_row.check_in <> v_start or v_row.check_out <> v_end then
          update bookings
             set check_in = v_start, check_out = v_end, last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
          v_updated := v_updated + 1;
        else
          update bookings
             set last_seen_in_feed_at = v_now,
                 external_booking_id = coalesce(external_booking_id, v_code)
           where id = v_row.id;
        end if;
      end if;
    exception
      when exclusion_violation then
        -- Name the booking in the way, so staff can see which one to check.
        select b.booking_number || ' (' ||
               case b.channel when 'airbnb' then 'Airbnb' when 'booking_com' then 'Booking.com'
                              when 'direct' then 'direct' else initcap(replace(b.channel::text, '_', ' ')) end ||
               coalesce(' ' || b.external_booking_id, '') || ', ' ||
               to_char(b.check_in, 'DD Mon') || ' - ' || to_char(b.check_out, 'DD Mon YYYY') || ')'
          into v_clash
          from bookings b
         where b.unit_id = p_unit_id
           and b.status in ('tentative','confirmed','checked_in')
           and daterange(b.check_in, b.check_out, '[)') && daterange(v_start, v_end, '[)')
         order by b.check_in
         limit 1;
        v_errors := v_errors || format(
          '%s stay %s to %s overlaps %s on this unit and was not imported.', v_name,
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'),
          coalesce(v_clash, 'another booking'));
      when check_violation or unique_violation then
        v_errors := v_errors || format('%s stay %s to %s: %s', v_name,
          to_char(v_start, 'DD Mon YYYY'), to_char(v_end, 'DD Mon YYYY'), sqlerrm);
    end;
  end loop;

  -- Cancellations: a synced future stay missing from the feed was cancelled
  -- on Airbnb. Past stays are left alone - Airbnb drops old events from the
  -- feed, which is not a cancellation. Checked-in guests are left alone too.
  select count(*) into v_live
    from bookings
   where unit_id = p_unit_id and channel = p_channel and ical_uid is not null
     and status in ('tentative','confirmed') and check_out > v_today;

  if jsonb_array_length(v_events) = 0 and v_live >= 2 then
    -- An empty feed with several live stays is far more likely a broken or
    -- replaced link than every guest cancelling at once.
    v_errors := v_errors || format(
      'The %s feed came back empty while %s upcoming stays are synced. Nothing was cancelled - check the calendar link.',
      v_name, v_live);
  else
    with gone as (
      update bookings
         set status = 'cancelled', cancelled_on = v_today, cancellation_reason = c_removed
       where unit_id = p_unit_id
         and channel = p_channel
         and ical_uid is not null
         and not (ical_uid = any (v_uids))
         and status in ('tentative','confirmed')
         and check_out > v_today
      returning 1
    )
    select count(*) into v_cancelled from gone;

    delete from availability_blocks
     where unit_id = p_unit_id
       and reason = 'channel_sync'
       and source_channel = p_channel
       and ical_uid is not null
       and not (ical_uid = any (v_uids));
  end if;

  if p_channel = 'airbnb' then
    update units
       set ical_last_synced_at   = v_now,
           ical_last_status      = case when cardinality(v_errors) = 0 then 'ok' else 'error' end,
           ical_last_error       = nullif(array_to_string(v_errors[1:5], ' '), ''),
           ical_last_event_count = jsonb_array_length(v_events)
     where id = p_unit_id;
  else
    update units
       set booking_ical_last_synced_at   = v_now,
           booking_ical_last_status      = case when cardinality(v_errors) = 0 then 'ok' else 'error' end,
           booking_ical_last_error       = nullif(array_to_string(v_errors[1:5], ' '), ''),
           booking_ical_last_event_count = jsonb_array_length(v_events)
     where id = p_unit_id;
  end if;

  return jsonb_build_object(
    'ok',         cardinality(v_errors) = 0,
    'created',    v_created,
    'updated',    v_updated,
    'reinstated', v_reinstated,
    'cancelled',  v_cancelled,
    'blocks',     v_blocks,
    'errors',     to_jsonb(v_errors)
  );
end;
$$;


-- ####################################################################
-- ## 0027_owner_unit_documents.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0027 Owners see the documents shared on their units
--
-- A document uploaded on a unit's page carries the unit, not an owner. The
-- read policy (0014) let an owner see an owner-visible document only when it
-- named one of their owner records, so every title deed, permit or NOC filed
-- on a unit stayed hidden from its owner even with "Owner can see" ticked.
--
-- Now an owner-visible document on a unit the owner currently owns is theirs
-- to read as well. Everything else is unchanged: sensitive files stay with
-- their own party, income documents stay hidden from owners, and tenants and
-- guests keep their own rule.
-- ============================================================================

drop policy if exists documents_read on documents;
create policy documents_read on documents
  for select to authenticated
  using (
    case
      when is_sensitive then
        pms.my_role() in ('super_admin','property_manager','finance')
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
      else
        (unit_id is not null and pms.can_read_unit(unit_id))
        or (owner_id is not null and owner_id in (select pms.my_owner_ids()))
        or (entity_kind = 'company' and pms.is_staff())
        or uploaded_by = auth.uid()
    end
    and (
      pms.is_staff()
      or (is_owner_visible and owner_id in (select pms.my_owner_ids()))
      or (is_owner_visible and unit_id is not null and pms.owns_unit(unit_id))
      or (is_tenant_visible and unit_id is not null and (pms.tenants_unit(unit_id) or pms.stays_in_unit(unit_id)))
      or uploaded_by = auth.uid()
    )
    and (pms.my_role() is distinct from 'owner' or not pms.is_income_document(kind))
  );

-- ####################################################################
-- ## 0028_website_listings.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0028 Website listings
--
-- The sale and rental listings shown on the D|R|P website (Buy / Rent, the
-- /properties pages) are kept here and edited in the admin portal. The
-- website reads the published ones from /api/public/listings when it is
-- built, in the shape its own data file uses, so its pages need no change.
--
--   * A listing is a draft until published; "hidden" takes it off the
--     website without deleting it.
--   * Columns follow the website's Listing type: offering buy/rent, price in
--     AED (a year's rent for rentals), type, area, building, beds (0 =
--     studio), baths, size in sq ft, completion, furnishing, agent, photos,
--     description, features, the DLD advertising permit.
--   * A listing may point at a unit the portal manages; most sale listings
--     are other people's properties and do not.
--   * Photos uploaded in the portal go to the public bucket listing-photos,
--     so the website can show them without signing in.
--
-- Staff read every listing; super admins, property managers, agents and
-- marketing edit them. Owners, tenants and guests see none of this table.
-- ============================================================================

create table website_listings (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique
                  check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 120),
  status        text not null default 'draft'
                  check (status in ('draft', 'published', 'hidden')),
  title         text not null check (length(trim(title)) between 3 and 200),
  offering      text not null check (offering in ('buy', 'rent')),
  -- Sale price, or a year's rent for a rental.
  price_aed     numeric(14,2) not null check (price_aed > 0),
  property_type text not null check (property_type in ('Apartment', 'Penthouse', 'Townhouse', 'Villa')),
  area          text not null check (length(trim(area)) > 0),
  building      text,
  -- What the website's map searches for, and whether that finds the
  -- building itself (true) or only the community.
  map_query     text,
  map_exact     boolean not null default false,
  beds          integer not null default 0 check (beds between 0 and 20),
  baths         integer not null default 1 check (baths between 0 and 20),
  size_sqft     integer not null check (size_sqft > 0),
  completion    text not null default 'Ready' check (completion in ('Ready', 'Off-Plan')),
  furnishing    text check (furnishing in ('Furnished', 'Unfurnished')),
  listed_at     date not null default ((now() at time zone 'Asia/Dubai')::date),
  agent         text,
  -- Photo URLs in display order; the first is the cover.
  images        jsonb not null default '[]'::jsonb check (jsonb_typeof(images) = 'array'),
  -- Paragraphs separated by a blank line.
  description   text not null default '',
  features      text[] not null default '{}',
  -- Property Finder reference and the DLD advertising permit.
  ref           text,
  permit        text,
  source_url    text,
  unit_id       uuid references units(id) on delete set null,
  created_by    uuid references profiles(id) on delete set null,
  updated_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index website_listings_status_idx on website_listings(status, offering);
create index website_listings_unit_idx on website_listings(unit_id);

create trigger website_listings_touch before update on website_listings
  for each row execute function pms.touch_updated_at();

comment on table website_listings is
  'Sale and rental listings for the D|R|P website, edited in the admin portal and read by /api/public/listings.';

-- ---------------------------------------------------------------------------
-- Who may edit
-- ---------------------------------------------------------------------------
create or replace function pms.can_edit_listings()
returns boolean
language sql
stable
security definer
set search_path = public, pms
as $$
  select coalesce(pms.my_role() in ('super_admin', 'property_manager', 'agent', 'marketing'), false);
$$;

alter table website_listings enable row level security;

create policy website_listings_read on website_listings
  for select to authenticated using (pms.is_staff());

create policy website_listings_insert on website_listings
  for insert to authenticated with check (pms.can_edit_listings());

create policy website_listings_update on website_listings
  for update to authenticated
  using (pms.can_edit_listings()) with check (pms.can_edit_listings());

create policy website_listings_delete on website_listings
  for delete to authenticated using (pms.can_edit_listings());

grant select, insert, update, delete on website_listings to authenticated;
grant all on website_listings to service_role;
grant execute on function pms.can_edit_listings() to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Photos: a public bucket, written only by listing editors
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('listing-photos', 'listing-photos', true, 10485760,
        array['image/jpeg', 'image/png', 'image/webp', 'image/avif'])
on conflict (id) do nothing;

drop policy if exists "listing photos upload by listing editors" on storage.objects;
create policy "listing photos upload by listing editors"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'listing-photos' and pms.can_edit_listings());

drop policy if exists "listing photos delete by listing editors" on storage.objects;
create policy "listing photos delete by listing editors"
  on storage.objects for delete to authenticated
  using (bucket_id = 'listing-photos' and pms.can_edit_listings());

-- ####################################################################
-- ## 0029_website_homes.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0029 Holiday homes on the Holiday Homes website
--
-- The Holiday Homes website (drpholidayhomes / hh-drp) reads its homes from
-- the portal instead of keeping its own list:
--
--   * A holiday-home unit carries the website content next to its operating
--     data: title, photos, description, rules, amenities, map position and the
--     slug of its page. Rates (nightly, weekend, cleaning, weekly/monthly
--     discount) are the ones already on the unit (0020); seasonal rates are
--     new.
--   * "On the website" (website_published) is the switch. A published unit
--     must be a short-term unit with a title, photos, an area and a rate.
--   * Bookings made on the website arrive through website_book_unit() and
--     land in bookings (channel direct, website_ref = the website's own
--     reference), so the Airbnb export feed, the calendar and the double-
--     booking constraint all see them. website_set_booking_status() confirms
--     or cancels them as the guest pays or cancels.
--
-- Both functions are for the service role only (the portal's /api/public
-- routes): they trust their caller, who has already authenticated the
-- website with WEBSITE_API_KEY.
-- ============================================================================

alter table units
  add column website_published   boolean not null default false,
  add column website_slug        text,
  add column website_title       text,
  add column website_tag         text,
  add column website_type        text
    check (website_type is null or website_type in ('studio','apartment','penthouse','villa','townhouse')),
  -- One of the website's area names (Palm Jumeirah, Dubai Marina, JVT, ...).
  add column website_area        text,
  add column website_building    text,
  add column website_description text,
  add column website_highlights  text[] not null default '{}',
  add column website_house_rules text[] not null default '{}',
  -- Website amenity ids (pool, wifi, gym, ...).
  add column website_amenities   text[] not null default '{}',
  -- Photo URLs in display order; the first is the cover.
  add column website_images      jsonb not null default '[]'::jsonb
    check (jsonb_typeof(website_images) = 'array'),
  add column website_lat         numeric(9,6) check (website_lat is null or website_lat between -90 and 90),
  add column website_lng         numeric(9,6) check (website_lng is null or website_lng between -180 and 180),
  add column website_maps_url    text,
  add column website_check_in    text not null default '15:00' check (website_check_in ~ '^[0-2][0-9]:[0-5][0-9]$'),
  add column website_check_out   text not null default '11:00' check (website_check_out ~ '^[0-2][0-9]:[0-5][0-9]$'),
  -- [{"from":"2026-12-20","to":"2027-01-05","rate":1200,"name":"New Year"}] (both dates inclusive)
  add column website_seasons     jsonb not null default '[]'::jsonb
    check (jsonb_typeof(website_seasons) = 'array');

alter table units
  add constraint units_website_slug_format
    check (website_slug is null or (website_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(website_slug) <= 120));

create unique index units_website_slug_idx on units(website_slug) where website_slug is not null;

-- A unit only goes on the website once it can be shown and booked there.
alter table units
  add constraint units_website_ready
    check (
      not website_published
      or (
        website_slug is not null
        and website_title is not null and length(trim(website_title)) >= 3
        and website_area is not null
        and website_type is not null
        and jsonb_array_length(website_images) > 0
        and base_nightly_rate_aed is not null and base_nightly_rate_aed > 0
        and max_guests is not null and max_guests > 0
        and operating_mode in ('short_term','both')
      )
    );

comment on column units.website_published is 'Shown and bookable on the Holiday Homes website.';

alter table bookings
  add column website_ref text;
create unique index bookings_website_ref_idx on bookings(website_ref) where website_ref is not null;
comment on column bookings.website_ref is 'The Holiday Homes website''s booking reference (DRP-XXXXXX) for bookings made there.';

-- ---------------------------------------------------------------------------
-- Book a unit from the website. Serialised per unit; refuses a unit that is
-- blocked, already booked, not published or without a valid DET permit.
-- Errors carry a stable first word the API maps to HTTP statuses:
--   not_found, blocked, taken, no_permit, invalid
-- ---------------------------------------------------------------------------
create or replace function website_book_unit(
  p_slug          text,
  p_ref           text,
  p_check_in      date,
  p_check_out     date,
  p_adults        integer,
  p_guest_name    text,
  p_guest_email   text,
  p_guest_phone   text,
  p_nationality   text,
  p_status        booking_status,
  p_nightly       numeric,
  p_accommodation numeric,
  p_cleaning      numeric,
  p_tourism       numeric,
  p_gross         numeric,
  p_message       text,
  p_notes         text
)
returns table (booking_id uuid, booking_number text)
language plpgsql
set search_path = public, pms
as $$
declare
  v_unit   units%rowtype;
  v_guest  uuid;
  v_id     uuid;
  v_number text;
begin
  if p_status not in ('tentative','confirmed') then
    raise exception 'invalid: a website booking starts as tentative or confirmed';
  end if;
  if p_check_out <= p_check_in or p_adults < 1 then
    raise exception 'invalid: check the dates and guests';
  end if;

  -- Lock the unit so two bookings for the same nights cannot both pass the checks.
  select * into v_unit from units
   where website_slug = p_slug and website_published and is_active
   for update;
  if not found then
    raise exception 'not_found: that home is not available on the website';
  end if;
  if v_unit.max_guests is not null and p_adults > v_unit.max_guests then
    raise exception 'invalid: this home sleeps up to % guests', v_unit.max_guests;
  end if;
  if v_unit.min_nights > (p_check_out - p_check_in) then
    raise exception 'invalid: minimum stay is % nights', v_unit.min_nights;
  end if;

  -- Existing bookings, owner stays, maintenance and channel (Airbnb) holds all
  -- show up as calendar blocks.
  if exists (
    select 1 from availability_blocks
     where unit_id = v_unit.id and start_date < p_check_out and end_date > p_check_in
  ) then
    raise exception 'blocked: those dates are not available';
  end if;

  if not pms.unit_has_valid_permit(v_unit.id, p_check_in) then
    raise exception 'no_permit: this home has no valid DET permit for those dates';
  end if;

  insert into guests (full_name, email, phone, whatsapp, nationality)
  values (trim(p_guest_name), nullif(trim(p_guest_email), ''), nullif(trim(p_guest_phone), ''),
          nullif(trim(p_guest_phone), ''), nullif(trim(p_nationality), ''))
  returning id into v_guest;

  begin
    insert into bookings (
      booking_number, unit_id, guest_id, channel, status, website_ref,
      check_in, check_out, adults,
      nightly_rate_aed, accommodation_aed, cleaning_fee_aed, tourism_dirham_aed, gross_total_aed,
      payout_expected_aed, guest_message, internal_notes
    ) values (
      '', v_unit.id, v_guest, 'direct', p_status, p_ref,
      p_check_in, p_check_out, p_adults,
      p_nightly, p_accommodation, coalesce(p_cleaning, 0), coalesce(p_tourism, 0), p_gross,
      -- Tourism Dirham is collected for the government, not paid out.
      p_gross - coalesce(p_tourism, 0), nullif(p_message, ''), nullif(p_notes, '')
    )
    returning id, bookings.booking_number into v_id, v_number;
  exception
    when exclusion_violation then
      raise exception 'taken: those dates were just booked';
    when unique_violation then
      raise exception 'invalid: that booking reference already exists';
  end;

  return query select v_id, v_number;
end;
$$;

-- ---------------------------------------------------------------------------
-- Move a website booking along: tentative -> confirmed (paid), or cancelled.
-- Returns the booking's status afterwards.
-- ---------------------------------------------------------------------------
create or replace function website_set_booking_status(
  p_ref    text,
  p_status text,
  p_reason text default null
)
returns text
language plpgsql
set search_path = public, pms
as $$
declare
  v_booking bookings%rowtype;
begin
  select * into v_booking from bookings where website_ref = p_ref for update;
  if not found then
    raise exception 'not_found: no booking with that reference';
  end if;

  if p_status = 'confirmed' then
    if v_booking.status in ('confirmed','checked_in','checked_out') then
      return v_booking.status::text;
    end if;
    if v_booking.status <> 'tentative' then
      raise exception 'invalid: a % booking cannot be confirmed', v_booking.status;
    end if;
    update bookings set status = 'confirmed' where id = v_booking.id;
    return 'confirmed';
  elsif p_status = 'cancelled' then
    if v_booking.status = 'cancelled' then
      return 'cancelled';
    end if;
    if v_booking.status not in ('inquiry','tentative','confirmed') then
      raise exception 'invalid: a % booking cannot be cancelled', v_booking.status;
    end if;
    update bookings
       set status = 'cancelled',
           cancelled_on = (now() at time zone 'Asia/Dubai')::date,
           cancellation_reason = left(coalesce(p_reason, 'Cancelled on the website'), 300)
     where id = v_booking.id;
    return 'cancelled';
  end if;

  raise exception 'invalid: status must be confirmed or cancelled';
end;
$$;

-- Only the portal's server (service role) calls these.
revoke all on function website_book_unit(text, text, date, date, integer, text, text, text, text, booking_status, numeric, numeric, numeric, numeric, numeric, text, text) from public, anon, authenticated;
revoke all on function website_set_booking_status(text, text, text) from public, anon, authenticated;
grant execute on function website_book_unit(text, text, date, date, integer, text, text, text, text, booking_status, numeric, numeric, numeric, numeric, numeric, text, text) to service_role;
grant execute on function website_set_booking_status(text, text, text) to service_role;

-- ####################################################################
-- ## 0030_website_beds.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0030 Sleeping arrangements on the Holiday Homes website
--
-- "Where you'll sleep" on a home's website page: one row per room, e.g.
--   [{"room":"Bedroom 1","beds":"1 king bed"},{"room":"Living room","beds":"1 sofa bed"}]
-- Edited on the unit's Website tab; sent to the website by /api/public/homes.
-- ============================================================================

alter table units
  add column if not exists website_beds jsonb not null default '[]'::jsonb
    check (jsonb_typeof(website_beds) = 'array');

comment on column units.website_beds is 'Sleeping arrangements shown on the Holiday Homes website: [{room, beds}].';

-- ####################################################################
-- ## 0031_website_listing_removed.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0031 Deleting a Property Finder listing from the website
--
-- Property Finder listings come from Property Finder, not from this table, so
-- deleting the portal's copy of one used to bring Property Finder's version
-- back on the website. "removed" keeps the web address here as a marker
-- instead: /api/public/listings/hidden lists it and the website leaves the
-- listing off, for good. The portal shows these only on the Property Finder
-- page, where Restore deletes the marker.
-- ============================================================================

alter table website_listings drop constraint if exists website_listings_status_check;
alter table website_listings add constraint website_listings_status_check
  check (status in ('draft', 'published', 'hidden', 'removed'));

comment on column website_listings.status is
  'draft | published | hidden | removed (a Property Finder listing deleted from the website; only the address is used).';

-- ####################################################################
-- ## 0032_no_booking_over_holds.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0032 No booking over an owner stay, and no hold over a booking
--
-- bookings_no_overlap (0005) stops two stays sharing a night, but nothing in
-- the database stopped a stay landing on an owner stay, a maintenance hold or
-- a manual block. The staff forms check this themselves; the Airbnb and
-- Booking.com feeds, the CSV import and confirming a request did not, so an
-- owner could find a guest booked into their own stay.
--
-- Now both sides are refused in SQL, whatever writes them:
--   * a live booking (tentative, confirmed, checked in) whose nights touch an
--     owner stay, maintenance, housekeeping or manual block;
--   * an owner stay, maintenance, housekeeping or manual block whose nights
--     touch a live booking.
-- Blocks mirrored from bookings ('booking') and dates closed on Airbnb
-- ('channel_sync') are not holds: D|R|P closes Airbnb for its own direct
-- guests, so a direct booking is expected there.
--
-- The refusal is a check_violation with a sentence naming the clash, so the
-- feed sync reports it against that stay ("Airbnb stay ... : These dates
-- overlap an owner stay ...") and the rest of the feed still imports.
--
-- Only new or moved stays and holds are checked: a stay that already overlaps
-- from before this migration can still be checked in, out or cancelled.
-- ============================================================================

create or replace function pms.hold_label(p_reason block_reason)
returns text
language sql
immutable
as $$
  select case p_reason
    when 'owner_stay'   then 'an owner stay'
    when 'maintenance'  then 'a maintenance block'
    when 'housekeeping' then 'a housekeeping block'
    else 'a blocked period'
  end
$$;

-- One writer at a time per unit calendar, so a booking and a hold saved at
-- the same moment cannot each miss the other.
create or replace function pms.lock_unit_calendar(p_unit_id uuid)
returns void
language sql
as $$
  select pg_advisory_xact_lock(hashtext('unit-calendar:' || p_unit_id::text))
$$;

create or replace function pms.reject_booking_over_hold()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_hold availability_blocks%rowtype;
begin
  if new.status not in ('tentative','confirmed','checked_in') then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and old.status in ('tentative','confirmed','checked_in')
     and new.unit_id = old.unit_id
     and new.check_in = old.check_in
     and new.check_out = old.check_out then
    return new;
  end if;

  perform pms.lock_unit_calendar(new.unit_id);

  select * into v_hold
    from availability_blocks ab
   where ab.unit_id = new.unit_id
     and ab.reason not in ('booking','channel_sync')
     and daterange(ab.start_date, ab.end_date, '[)') && daterange(new.check_in, new.check_out, '[)')
   order by ab.start_date
   limit 1;

  if found then
    raise exception 'These dates overlap % on this unit (% to %). Move or remove it first.',
      pms.hold_label(v_hold.reason),
      to_char(v_hold.start_date, 'DD Mon YYYY'), to_char(v_hold.end_date, 'DD Mon YYYY')
      using errcode = 'check_violation', constraint = 'bookings_no_overlap_holds';
  end if;

  return new;
end;
$$;

drop trigger if exists bookings_hold_gate on bookings;
create trigger bookings_hold_gate
  before insert or update of status, unit_id, check_in, check_out on bookings
  for each row execute function pms.reject_booking_over_hold();

create or replace function pms.reject_hold_over_booking()
returns trigger
language plpgsql
security definer
set search_path = public, pms
as $$
declare
  v_booking bookings%rowtype;
begin
  if new.reason in ('booking','channel_sync') then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and old.reason not in ('booking','channel_sync')
     and new.unit_id = old.unit_id
     and new.start_date = old.start_date
     and new.end_date = old.end_date then
    return new;
  end if;

  perform pms.lock_unit_calendar(new.unit_id);

  select * into v_booking
    from bookings b
   where b.unit_id = new.unit_id
     and b.status in ('tentative','confirmed','checked_in')
     and daterange(b.check_in, b.check_out, '[)') && daterange(new.start_date, new.end_date, '[)')
   order by b.check_in
   limit 1;

  if found then
    raise exception 'Booking % (% to %) is in these dates. Cancel or move it first.',
      v_booking.booking_number,
      to_char(v_booking.check_in, 'DD Mon YYYY'), to_char(v_booking.check_out, 'DD Mon YYYY')
      using errcode = 'check_violation', constraint = 'availability_blocks_no_overlap_bookings';
  end if;

  return new;
end;
$$;

drop trigger if exists availability_blocks_booking_gate on availability_blocks;
create trigger availability_blocks_booking_gate
  before insert or update of reason, unit_id, start_date, end_date on availability_blocks
  for each row execute function pms.reject_hold_over_booking();

-- ####################################################################
-- ## 0033_guest_incidents.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0033 Guest incidents (staff only)
--
-- A record of what a guest did to a unit: vomit or other mess, damage,
-- smoking, a party, extra guests, missing items. Kept for cleaning charges,
-- deposit deductions and Airbnb claims - and never shown to owners.
--
-- Repairs and complaints (maintenance_requests, 0019) are shared with the
-- unit's owner by design. Incidents are not, so they get their own table
-- whose every policy requires staff scoped to the unit; there is no owner,
-- tenant or guest path to a row, and no owner view over it.
--
-- Photos live in the private 'documents' bucket under incident/<id>/... with
-- no documents row: the bucket lets staff read any object and everyone else
-- only objects a documents row grants them, so these stay staff only too.
-- ============================================================================

create table guest_incidents (
  id            uuid primary key default gen_random_uuid(),
  unit_id       uuid not null references units(id) on delete restrict,
  booking_id    uuid references bookings(id) on delete set null,
  occurred_on   date not null default current_date,
  category      text not null check (category in (
                  'vomit', 'mess', 'damage', 'smoking', 'party_noise',
                  'extra_guests', 'pets', 'missing_items', 'rule_breach', 'other')),
  description   text not null check (length(btrim(description)) between 3 and 4000),
  charge_aed    numeric(10,2) check (charge_aed >= 0),
  photo_paths   text[] not null default '{}',
  status        text not null default 'open' check (status in ('open', 'resolved')),
  resolution    text check (length(resolution) <= 2000),
  resolved_at   timestamptz,
  reported_by   uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on table guest_incidents is
  'What a guest did to a unit (mess, damage, smoking ...). Staff only - never shown to owners.';
comment on column guest_incidents.charge_aed is
  'What D|R|P means to recover from the guest or their deposit, if anything.';
comment on column guest_incidents.photo_paths is
  'Object keys in the private documents bucket (incident/<id>/...).';

create index guest_incidents_unit_idx on guest_incidents(unit_id, occurred_on desc);
create index guest_incidents_booking_idx on guest_incidents(booking_id);
create index guest_incidents_open_idx on guest_incidents(occurred_on desc) where status = 'open';

create trigger guest_incidents_touch before update on guest_incidents
  for each row execute function pms.touch_updated_at();

-- The stay must be on the same unit, and resolving stamps the time.
create or replace function pms.guest_incident_checks()
returns trigger
language plpgsql
set search_path = public, pms
as $$
begin
  if new.booking_id is not null
     and not exists (select 1 from bookings b where b.id = new.booking_id and b.unit_id = new.unit_id) then
    raise exception 'That booking is not on this unit' using errcode = 'check_violation';
  end if;
  if new.status = 'resolved' and (tg_op = 'INSERT' or old.status <> 'resolved') then
    new.resolved_at := now();
  elsif new.status = 'open' then
    new.resolved_at := null;
  end if;
  return new;
end;
$$;

create trigger guest_incidents_checks
  before insert or update on guest_incidents
  for each row execute function pms.guest_incident_checks();

alter table guest_incidents enable row level security;

create policy guest_incidents_read on guest_incidents
  for select to authenticated
  using (pms.is_staff() and pms.staff_scoped_to_unit(unit_id));

create policy guest_incidents_insert on guest_incidents
  for insert to authenticated
  with check (pms.is_staff() and pms.staff_scoped_to_unit(unit_id));

create policy guest_incidents_update on guest_incidents
  for update to authenticated
  using (pms.is_staff() and pms.staff_scoped_to_unit(unit_id))
  with check (pms.is_staff() and pms.staff_scoped_to_unit(unit_id));

create policy guest_incidents_delete on guest_incidents
  for delete to authenticated
  using (pms.is_admin());

revoke all on guest_incidents from public, anon;
grant select, insert, update, delete on guest_incidents to authenticated;
grant all on guest_incidents to service_role;

-- ####################################################################
-- ## 0034_website_team.sql
-- ####################################################################

-- ============================================================================
-- D|R|P PMS - 0034 The team on the D|R|P website
--
-- The people on the website's About page and on its listings (photo, role,
-- RERA BRN, phone, WhatsApp, email), edited under Website -> Team. The
-- website reads them from /api/public/team when it builds.
--
--   * A listing names its agent in website_listings.agent; the website finds
--     the team member by name or by one of agent_names (the spellings used on
--     Property Finder, e.g. "Adithya Mitter").
--   * phone / whatsapp / email are what the website's buttons use. Leave one
--     empty and that button is not shown (the listing card falls back to
--     the DRP office numbers).
--   * show_on_about: on the About page and with a profile page. Off: still
--     shown as the agent on their listings.
--   * Photos: the public listing-photos bucket, or a path on the website
--     (the members imported below keep their current portraits).
--
-- Staff read the team; super admins, property managers, agents and
-- marketing edit it (pms.can_edit_listings, 0028).
-- ============================================================================

create table website_team (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique
                  check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 80),
  name          text not null check (length(trim(name)) between 2 and 120),
  role          text not null default '',
  -- One line under the role on the About page
  summary       text,
  -- Paragraphs separated by a blank line
  bio           text not null default '',
  photo_url     text,
  brn           text,
  phone         text,
  whatsapp      text,
  email         text,
  agent_names   text[] not null default '{}',
  show_on_about boolean not null default true,
  sort_order    integer not null default 100,
  is_active     boolean not null default true,
  created_by    uuid references profiles(id) on delete set null,
  updated_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index website_team_order_idx on website_team(sort_order, name);

create trigger website_team_touch before update on website_team
  for each row execute function pms.touch_updated_at();

comment on table website_team is
  'The team on the D|R|P website (About page, listing agents), edited under Website -> Team and read by /api/public/team.';

alter table website_team enable row level security;

create policy website_team_read on website_team
  for select to authenticated using (pms.is_staff());

create policy website_team_insert on website_team
  for insert to authenticated with check (pms.can_edit_listings());

create policy website_team_update on website_team
  for update to authenticated
  using (pms.can_edit_listings()) with check (pms.can_edit_listings());

create policy website_team_delete on website_team
  for delete to authenticated using (pms.can_edit_listings());

grant select, insert, update, delete on website_team to authenticated;
grant all on website_team to service_role;

